  },
  "事件结束时间": {
    "年": 1259,
    "月": 10,
    "日": 23,
    "时": 11
  },
  "事件引子": "你听说英雄大宴散后，郭大侠夫妇在房中商议——一群三山五岳的怪人突然齐聚襄阳为郭二小姐祝寿，此事透着蹊跷。",
  "后续事件": {
    "事件名": "神雕第三十六回01-丐帮大会开台比武选帮主",
    "描述": "十月廿四郭襄生辰之日，丐帮大会推选新帮主，各路怪客果然如约而至"
  },
  "事件详情": "当日英雄大宴尽欢而散。郭靖回到房中与妻子说起会上群英齐心协力敌忾同仇，言语中甚是兴奋。黄蓉随即说起圣因师太、百草仙等七人与郭襄夜宴之事。郭靖一怔道竟有这般事，看了千年雪参果是生平仅见的珍物。黄蓉笑道咱们这位宝贝小姑娘的面子倒似比爹娘还大呢。郭靖不语低头想着圣因师太、转轮王、韩无垢等一干人的生平行事。黄蓉提议丐帮推选帮主之事不如提早几日办妥，否则迟到襄儿生日倘若百草仙等人真的到来襄阳城中龙蛇混杂或有他变。郭靖却另有主意——咱们索性在十月廿四推选帮主大大的热闹一场，要是无色禅师、聋哑头陀等人驾临，咱们晓以大义请这伙朋友同抗外敌岂不是好。黄蓉皱眉道我只怕他们只是借祝寿为名却是存心来捣乱一场——自来树大招风人怕出名，只怕天下武学之士倒有一半不愿你做这武林盟主呢。郭靖站起身来哈哈一笑，说道蓉儿咱们行事但求无愧于天无愧于心，为抗蒙古帮手越多越好，这武林盟主嘛是谁当都一样。再说邪不能胜正，这干人若是真有歹意咱们便跟他们周旋一场，打狗棒法和降龙十八掌倒有十多年没动了未必就不管事了。黄蓉见他意兴勃发豪气不减当年，笑道好咱们便照主帅之意。两人商量了布阵御敌方略以及如何安排席次。黄蓉说让郭靖服雪参滋补，郭靖推让说蓉儿连生三个孩子内力受损正该滋补。夫妻俩推让半日，最后郭靖说这雪参乃救命之物来日龙争虎斗定有好朋友受到损伤，咱们还是留着。",
  "事件概要": "郭靖黄蓉决定将丐帮帮主推选与郭襄生辰并作一日应变，千年雪参暂留待救急，襄阳明暗两场聚会自此并轨。",
  "insert": {
    "郭靖": {
      "人物经历": {
        "神雕第三十五回10-黄蓉郭靖商议应对怪客生日": "与黄蓉商议圣因师太百草仙等怪客为郭襄祝寿之事。郭靖主张将丐帮帮主推选放在十月廿四与郭襄生辰同日——趁怪客到来晓以大义请同抗外敌。说'邪不能胜正'意兴勃发豪气不减当年。为将雪参留作救治伤者之用心意深重"
      }
    },
    "黄蓉": {
      "人物经历": {
        "神雕第三十五回10-黄蓉郭靖商议应对怪客生日": "忧心怪客借祝寿为名存心捣乱——树大招风人怕出名。提议提早办妥丐帮推选以免襄阳城中龙蛇混杂。郭靖主张索性在郭襄生日同日办大事后尊重丈夫决定"
      }
    }
  },
  "update": {
    "郭靖": {
      "状态": "英雄大宴散后与黄蓉商议怪客之事。决定将丐帮推选放在十月廿四——要大大的热闹一场。对雪参推让半日最终决定留作救命之物"
    },
    "黄蓉": {
      "所在位置": "大宋/襄阳/郭府",
      "状态": "与郭靖商议决定尊重丈夫之意——丐帮推选放在十月廿四与郭襄生辰同日。虽忧怪客别有图谋但见丈夫豪气不减当年心中欣慰"
    }
  },
  "参与人物": [
    "郭靖",
    "黄蓉"
  ]
}

2479.content:
{
  "事件地点": "大宋/河南府/龙驹寨",
  "触发条件": {
