  "事件引子": "深夜，完颜萍再次叩响耶律家大门，耶律齐仍坚持只用右手应战；她手中只有刚学会的三记险招，成败全在临场一搏。",
  "后续事件": {
    "事件名": "神雕第十回04-杨过完颜萍溪边互诉衷肠",
    "描述": "完颜萍终不忍下手杀耶律齐，掷刀掩面奔出，六神无主直奔郊外小溪"
  },
  "事件详情": "完颜萍奔回耶律家时众人正要安寝。她在大门上敲了两下朗声求见耶律齐。耶律齐侧身让进，完颜萍拔刀呼呼呼连环三招刀风中夹六招铁掌掌法。二人斗了一阵完颜萍正要使杨过所授三招，门外陆无双突然出声示警：'耶律齐，她要骗你使用左手，可须小心了。'耶律齐一怔，完颜萍不等他会过意来立时一招'云横秦岭'削去，待他侧身闪避突地伸出左手'枯藤缠树'抓住他右手，自己右手回转横刀猛往颈中抹去。在这电光石火之间耶律齐心中转了几转——他明知这一出手相救乃是自舍性命，但慷慨豪侠危急之际竟还是伸出左手在完颜萍右腕上一挡，手腕翻处夺过柳叶刀。二人交换三招各自跃后。耶律齐将刀掷还坦然道：'你已迫得了我用左手，你杀我便是，但有一事相求——求你别再加害家父。'完颜萍慢慢走近举起刀来，烛光下见他神色坦然凛凛生威——见到这般男子汉的气概，想起他是为救自己才用左手，这一刀哪里还砍得下去？眼中杀气突转柔和，将刀子往地下一掷掩面奔出。",
  "事件概要": "完颜萍终逼得耶律齐出左手却仍未能成事，也由此看清耶律齐并非可轻易刺杀之人。",
  "insert": {
    "完颜萍": {
      "人物经历": {
        "神雕第十回03-完颜萍用计逼耶律齐出左手": "完颜萍深夜回耶律家拔刀再战耶律齐，依杨过所授使出连环三招。陆无双示警，耶律齐明知是计仍为救她用出左手，夺刀后坦然说可杀他但勿害其父。完颜萍举刀难下，杀气转柔，掷刀掩面奔出。"
      },
      "关系网": {
        "耶律齐": "惨败/40（持刀面对坦然受死的耶律齐竟难以下手——见他为救自己不惜舍命，这般男子汉气概令她杀气消散。仇已无法亲手报，心中乱成一团）"
      }
    },
    "耶律齐": {
      "人物经历": {
        "神雕第十回03-完颜萍用计逼耶律齐出左手": "深夜完颜萍又来挑战，见她刀中夹使九招仍被自己单手化解。忽听陆无双示警说她要骗自己出左手，一怔间完颜萍已使出连环三招——待她横刀自刎时明知是计，慷慨豪侠之心却不容见死不救，危急中伸出左手挡腕夺刀。坦然说'你已迫得了我用左手你杀我便是，但求你别再加害家父'。面不改色坦然受死。"
      }
    },
    "陆无双": {
      "人物经历": {
        "神雕第十回03-完颜萍用计逼耶律齐出左手": "在门外出声示警耶律齐'她要用计骗你使用左手须小心了'——暗中搅乱了杨过所设的必杀之计。"
      }
    }
  },
  "update": {
    "完颜萍": {
      "所在位置": "大宋/河南府/龙驹寨",
      "状态": "心乱如麻（用计逼耶律齐出了左手却终不忍下手杀他。对耶律齐的慷慨舍命既震撼又感动——父母之仇与对他的不忍在心头剧烈交战，掷刀奔出后六神无主）"
    },
    "耶律齐": {
      "所在位置": "大宋/河南府/龙驹寨",
      "状态": "随父避祸（深夜再遇完颜萍挑战——明知她用计相逼仍舍命出左手相救。凭豪侠之气放下生路，坦然让完颜萍动手，面不改色）"
    }
  },
  "参与人物": [
    "完颜萍",
    "耶律齐",
    "陆无双"
  ]
}

4666.content:
{
  "事件地点": "大宋/大胜关/陆家庄",
  "触发条件": {
    "类型": "时间",
