    "月": 10,
    "日": 26,
    "时": 23
  },
  "事件引子": "朱子柳走到厅中向霍都拱了拱手，从袖里取出笔来在空中画了几个虚圈儿——全然是个迂儒模样。霍都凝神看那枝笔却无异处，正欲相询，外面走进来一个白衣少女...",
  "后续事件": {
    "事件名": "神雕第十三回01-朱子柳一阳书指胜霍都遭毒钉暗算",
    "描述": "朱子柳与霍都的比武仍在继续，小龙女已找到了杨过，但金轮法王一行的挑战尚未了结..."
  },
  "事件详情": "朱子柳走到厅中，向霍都拱手讨教，从袖里取出一枝竹管羊毫毛笔——笔锋沾着半寸墨，全无特异之处。他说'蒙古乃蛮夷之邦未受圣人教化'，惹得霍都恼怒。朱子柳以'一阳书指'代笔为指，将书法与一阳指融为一炉——先以楷书'房玄龄碑'法度严谨一笔不苟，霍都因曾临写过此碑尚能招架。朱子柳喝彩后变招为草书'自言帖'——除下帽子往地上一掷，长袖飞舞狂奔疾走如疯如癫。黄蓉认出是张旭三杯草圣传的意境，以弹指神通连环弹出三杯酒助兴。朱子柳连干三杯后笔势更佳，写到'担夫争道'的'道'字时最后一笔钩上来直划上霍都衣衫——群豪轰笑声中霍都踉跄后退。正在此时，一个白衣少女在厅口一站——群雄不约而同望去。她脸色苍白若有病容，烛光映照下仍无半点血色，清雅绝俗姿容秀丽无比。杨过一见大喜若狂，胸口如被大铁槌重重一击，从屋角一跃而出抱住她大叫'姑姑姑姑'。这少女正是小龙女——她在古墓中再也忍耐不住对杨过的思念，下山漫无目的四处寻他。一路闹了不少笑话，在客店中听到英雄大宴之事便赶来。杨过流下泪来哽咽道你不再撇下我了罢，小龙女摇头不知。杨过牵着小龙女之手旁若无人与她在厅柱石础上并肩坐下，心中欢喜要炸开来一般。",
  "事件概要": "朱子柳接战霍都，小龙女也在厅中现身，陆家庄风波由盟主之争转向杨龙重逢。",
  "insert": {
    "朱子柳": {
      "人物经历": {
        "神雕第十二回08-朱子柳战霍都小龙女现身": "朱子柳以独创一阳书指战霍都，先楷书房玄龄碑，后草书自言帖，脱帽狂奔。黄蓉弹指神通递酒三杯，酒后笔势更锐，写担夫争道之道字，末笔钩破霍都衣衫，霍都踉跄后退，群豪哄笑。"
      }
    },
    "黄蓉": {
      "人物经历": {
        "神雕第十二回08-朱子柳战霍都小龙女现身": "全神观斗中随口答郭芙问题。见朱子柳使出张旭草书'自言帖'——斟三杯酒以弹指神通一一弹出，凑合朱子柳笔意总是乘着空隙弹出叫霍都击打不着。朱子柳连干三杯道谢赞'好俊的弹指神通功夫'——黄蓉笑道'好锋锐的\"自言帖\"'。一语道破朱子柳苦研十余年的绝技——令朱子柳心想'朱某一生自负聪明总是逊这小姑娘一筹'"
      }
    },
    "小龙女": {
      "人物经历": {
        "神雕第十二回08-朱子柳战霍都小龙女现身": "小龙女与杨过别后，于古墓住月余难耐，下山寻人，见人就问可见杨过，闹出许多笑话。一日闻天下英雄集于大胜关陆家庄赴宴，心想杨过或在其间，遂前往。到庄中遍寻，终见杨过，被他抱住连呼姑姑。"
      },
      "所在位置": "大宋/大胜关/陆家庄"
    },
    "杨过": {
      "人物经历": {
        "神雕第十二回08-朱子柳战霍都小龙女现身": "在屋角里坐着正看朱子柳与霍都激斗，忽见白衣少女在厅口一站——大喜若狂如被大铁槌重击胸口。从屋角一跃而出抱住小龙女大叫'姑姑姑姑'，流下泪来哽咽道'你不再撇下我了罢'。牵着小龙女的手旁若无人坐在厅柱石础上，心中欢喜有如要炸开来一般"
      }
    },
    "霍都": {
      "人物经历": {
        "神雕第十二回08-朱子柳战霍都小龙女现身": "抱拳以礼见朱子柳从袖里取出毛笔不动声色。被朱子柳'蛮夷之邦'之言激怒。虽曾跟汉儒读过经书学过诗词能应付一路楷书，但朱子柳变成草书后便渐感吃力。当着群雄面前被劝酒已感羞辱，又见小龙女进来——虽心中一动却不知她就是自己曾在终南山求婚的姑娘"
      }
    },
    "郭芙": {
      "人物经历": {
        "神雕第十二回08-朱子柳战霍都小龙女现身": "走到母亲身边问'他拿笔划来划去那是甚么玩意'——黄蓉全神观斗随口答'房玄龄碑'，郭芙愕然不解。见朱子柳如疯如癫骇然笑问'妈他发癫了吗'"
      }
    }
  },
  "update": {
    "杨过": {
      "状态": "与小龙女重逢（在英雄大宴上终于找到小龙女——欣喜若狂。与她并肩坐在厅柱石础上心中欢喜得如要炸开一般。两人旁若无人只顾自行叙话）",
      "所在位置": "大宋/大胜关/陆家庄",
      "关系网": {
        "小龙女": "师父且爱慕/100（终于找到朝思暮想的小龙女——大喜若狂眼泪迸流。牵着她的手再不放开——心中发誓今生今世再也不让她离开。两人并肩坐于厅柱旁旁若无人——心中欢喜得如要炸开来一般）"
      }
    },
    "小龙女": {
      "状态": "与杨过重逢（下了终南山一路寻来终于在英雄大宴上找到杨过。被他抱住流泪呼唤——心中也不知是喜是悲。牵着杨过的手并肩坐在厅中）",
      "所在位置": "大宋/大胜关/陆家庄",
      "关系网": {
        "杨过": "爱侣/99（终于找到杨过——被他抱住大哭呼唤，心中震荡。牵着他的手不放不知是喜是悲。嘴上不说但心中对他的牵挂和怨恨已无从分辨）"
      }
    },
    "尹志平": {
      "状态": "极度惊恐（见到小龙女突然出现在大厅——脸色惨白身子发颤。心中最害怕的事终于发生了——杨过果然和小龙女在一起）",
      "关系网": {
        "小龙女": "暗恋/70（见小龙女突然出现在英雄宴——脸色惨白身子发颤。心中又怕杨过揭发自己的罪行又暗暗牵挂小龙女——此刻恐惧远多于爱恋）"
      }
    },
    "赵志敬": {
      "关系网": {
        "小龙女": "旧识/5（在英雄宴上见到小龙女出现——认出她便是活死人墓中那绝色少女。斜眼瞧着尹志平微微冷笑——心中暗想他必定为小龙女的到来而魂不守舍）"
