      }
    },
    "公孙绿萼": {
      "人物经历": {
        "神雕第十八回12-公孙止审女挥剑杀女杨过同坠深渊": "宁死不肯求饶——低声说出'饶他'任父亲挥剑劈下。被公孙止推肩撞向杨过——二人一同坠入丹房下的深渊。在急坠的黑暗中感受到杨过将自己身体托起护住——心中既是恐惧又是温暖。扑通摔入水中下沉——与杨过同命相连暗夜深渊生死未卜"
      },
