      "人物经历": {
        "神雕第十一回05-天下无狗被破洪七公叹服二老相抱大笑同逝": "洪七公传杨过打狗棒法绝招天下无狗，次晨见其使欧阳锋杖法即服，一跃而起抱西毒大笑，数十载深仇大恨一笑而罢，与宿敌同日逝于华山绝顶，含笑而终，尸身由杨过葬于洞侧。"
      }
    },
    "欧阳锋": {
      "状态": "已故（在华山绝顶苦思一夜破解'天下无狗'后回光返照忆起自己是谁。与洪七公相抱大笑三声'我是欧阳锋'后气绝。杨过守尸七日七夜后将其安葬于洞侧，比武棍棒一同入土）",
      "人物经历": {
        "神雕第十一回05-天下无狗被破洪七公叹服二老相抱大笑同逝": "欧阳锋听杨过演完天下无狗，思索整夜须眉尽白，次晨想出破招杖法。听洪七公连呼其名，回光返照记起自己是谁，大笑自称欧阳锋，与宿敌相抱同逝，深仇一笑而罢，尸身由义子葬于华山绝顶。"
      },
      "关系网": {
        "洪七公": "宿敌/100（在华山绝顶最后一战——见洪七公叹服相抱大叫自己名字后回光返照忆起一生，与宿敌相抱大笑同时归天。数十年的深仇大恨一笑而罢）"
      }
    },
    "杨过": {
      "状态": "哀毁逾恒（亲见义父欧阳锋与洪七公相抱大笑中同时气绝，守尸七日七夜不肯离去。将二老安葬后磕了八个头。下山时觉世事只如浮云——别人看重也好轻视也好于我又有何干系。小小年纪竟然愤世嫉俗、玩世不恭起来）",
      "人物经历": {
        "神雕第十一回05-天下无狗被破洪七公叹服二老相抱大笑同逝": "杨过学完洪七公最后一招\"天下无狗\"，次晨目睹欧阳锋一夜白首，见二老相抱大笑后同时气绝，惊骇大哭。他初疑是假死，守尸七日，待二尸变色方知当真离世，遂在洞侧并排掘坑安葬，将洪七公酒葫芦与比武棍棒一并埋入。他磕了八个头，念及义父终究逊洪七公一筹，叹息后觅路下山。"
      },
      "关系网": {
        "洪七公": "忘年之交/90（亲见洪七公大笑而逝——守尸七日七夜伤心欲绝。将他与义父合葬华山绝顶磕了八个头。洪七公的酒葫芦与棍棒皆入土相伴。心底认定他武功盖世肝胆照人——就算是义父也逊他一筹。下山后每逢想起丐帮便因洪七公而心生亲近）",
        "欧阳锋": "义父/95（亲见义父一夜白首——心中难过之极。见义父与洪七公相抱而逝后守尸七日七夜。将他与洪七公合葬华山绝顶恭恭敬敬磕了八个头。心底终究认定义父武功逊洪老前辈一筹——却更增对义父的爱怜与不舍）"
      }
    }
  },
  "参与人物": [
