  },
  "事件引子": "你听说千钧一发之际，远处一声清啸鼓风而至，刹那间将千军万马的厮杀声一齐淹没——杨过与小龙女在神雕开路之下冲破刀山枪林，直向烈火中的高台扑去。",
  "后续事件": {
    "事件名": "神雕第三十九回08-杨过飞石击杀蒙哥大汗宋军大胜",
    "描述": "郭襄获救后杨过率众人冲向攻打襄阳的蒙古大军，最终飞石击杀蒙哥大汗。"
  },
  "事件详情": "郭襄被绑高台浓烟烈火围住台脚自知顷刻间将遭火焚而死。正当她神驰深谷追忆杨过之际，忽听得远处一声清啸鼓风而至，刹那间将千军万马的厮杀声一齐淹没。西北方蒙古兵翻翻滚滚向两旁散开，杨过与小龙女各执长剑在神雕之后冲向高台。神雕双翅鼓风将弩箭纷纷拨落，两人一雕相互护持片刻间冲到台前。杨过纵身跃上梯级向上攀行，金轮法王发掌袭击二人对掌各退一步均暗赞对手功力精进。杨过长剑与法王双轮相交——剑断数截法王双轮也脱手飞出。法王取出铜铁双轮扑击杨过空手以袖掌相抗。激斗二百招以上杨过虽无兵刃却始终不落下风。法王毒念陡起铁轮砸向杨过右肩趁他沉肩卸避铜轮飞出击向郭襄。杨过大惊纵起挥袖击落铜轮——全身门户洞开被法王铁轮击中右腿血如泉涌左肩亦被轮子划伤。杨过数次欲使黯然销魂掌但因与小龙女重逢喜悦欢乐已无黯然销魂心情威力有限。眼见高台将塌杨过万念俱灰凄然向小龙女望了一眼——心中想到便要永诀哀痛欲绝之际黯然销魂掌大威力不知不觉而出：拖泥带水击中法王肩头、魂不守舍倒行逆施若有所失连出三招、行尸走肉一脚正中法王胸口。法王狂喷鲜血翻下高台。杨过挥掌击断木桩将郭襄连桩抱起涌身跳上神雕之背稳稳着地。周伯通身穿软猬甲将受伤法王拦腰抱住按在地下——法王被压在倒塌高台的火柱之下。",
  "事件概要": "杨过小龙女救下郭襄并重创金轮法王，郭襄火焚之危当场解除。",
  "insert": {
    "杨过": {
      "人物经历": {
        "神雕第三十九回07-杨过小龙女神雕冲高台战金轮法王救郭襄": "杨过与小龙女、神雕赶到襄阳战场，冲向高台战金轮法王。断剑后徒手相抗，救郭襄时右腿左肩受伤。与小龙女重逢后喜悦，黯然销魂掌威力有限。高台将塌时凄然道别，哀痛欲绝中掌力大生，连出拖泥带水、魂不守舍、倒行逆施、行尸走肉等招重伤法王，令其翻下高台。最终击断木桩抱起郭襄骑神雕着地。"
      }
    },
    "小龙女": {
      "人物经历": {
        "神雕第三十九回07-杨过小龙女神雕冲高台战金轮法王救郭襄": "小龙女随杨过至襄阳，偕神雕冲高台救郭襄。台下守护，驱蒙古射手。心神尽系杨过，忽见其浴血，心头剧跳。木梯烧断难助战，茫然舞剑。杨过救下郭襄，她撕衣襟为其裹伤，双手颤抖，说不出话。"
      }
    },
    "神雕": {
      "人物经历": {
        "神雕第三十九回07-杨过小龙女神雕冲高台战金轮法王救郭襄": "随杨过小龙女赶到襄阳战场。当先开路双翅展开激起狂风将射来的弩箭纷纷拨落——蒙古兵将跃马挺枪来刺均被杨过小龙女长剑一一刺落马下。冲至高台前杨过郭襄从台上跳下时双翅一扑跃起丈余稳稳接住二人缓缓着地。"
      }
    },
    "金轮法王": {
      "人物经历": {
        "神雕第三十九回07-杨过小龙女神雕冲高台战金轮法王救郭襄": "金轮法王与杨过对掌，暗赞其十六年来功力精进。双轮对长剑，剑断轮飞，激斗二百余招，察觉高台将塌，遂起毒念，先以铁轮击杨过右腿，又袭郭襄诱其相救，再划伤其左肩。杨过万念俱灰之际使出黯然销魂掌，法王连中数招，被一脚踢中胸口狂喷鲜血翻下高台，复被周伯通以软猬甲拦腰抱住按倒，高台倒塌后被压在火柱之下。"
      }
    },
    "郭襄": {
      "人物经历": {
        "神雕第三十九回07-杨过小龙女神雕冲高台战金轮法王救郭襄": "在烈火高台之上忽听清啸声认出杨过——大喜凝目望去果见杨过与白衣女子冲向高台。法王攻击自己诱杨过相救时大声叫道'大哥哥你别管我只须杀了这藏僧给我报仇'。见杨过身上染血啊的一声惊叫。最终杨过击断木桩将她连桩抱起跳上神雕之背稳稳着地——终于死里逃生。"
      }
    },
    "周伯通": {
      "人物经历": {
        "神雕第三十九回07-杨过小龙女神雕冲高台战金轮法王救郭襄": "在台下与小龙女合力驱赶蒙古射手。法王被杨过踢下高台后哈哈大笑——将重伤法王拦腰抱住按在地下。身穿桃花岛至宝软猬甲刀枪不入且生满尖刺犹如刺猬——法王本已受伤再被老顽童这么一抱一按哪里还能动弹。高台倒塌时纵身跃开——法王便被压在火柱之下。"
      }
    },
    "郭靖": {
      "人物经历": {
        "神雕第三十九回07-杨过小龙女神雕冲高台战金轮法王救郭襄": "正领兵回救郭襄突见杨过小龙女神雕斜刺杀出冲上高台——无不精神大振。黄药师调兵二万袭击攻城敌军后方余二万在高台下为杨过声援。见杨过在高台上空手搏击肩腿受伤的情景只是相距过远无法相助。黄蓉提议射剑上去——郭靖取两张铁胎硬弓双弓相并将剑柄扣在弓弦之上左手托弓右手拉满双弦飕的一声长剑破空飞向杨过。"
      }
    },
    "黄蓉": {
      "人物经历": {
        "神雕第三十九回07-杨过小龙女神雕冲高台战金轮法王救郭襄": "见杨过小龙女冲上高台精神大振。见杨过在高台上空手搏击心念一动——抢过耶律齐手中长剑抛给郭靖叫'射上去给过儿'。见女儿终于死里逃生不禁喜极而泣心里对杨过的感激难以言宣——便是为他死了亦所甘愿。忙奔向女儿身旁割断她身上的绑缚。"
      }
    },
