  "事件引子": "金轮法王携杨过之手走进忽必烈王帐。一个二十五六岁的青年男子科头布服正坐着看书，见二人进帐忙离座相迎笑吟吟寒暄。",
  "后续事件": {
    "事件名": "神雕第十六回09-忽必烈大宴筷子争肉斗五高手",
    "描述": "忽必烈大喜之下命大张筵席，命左右请招贤馆的几位英雄来见。帐门开处走进潇湘子、尼摩星、马光佐、尹克西四人。"
  },
  "事件详情": "金轮法王携杨过走进王帐。忽必烈是个二十五六岁的青年男子，科头布服正坐着看书——杨过只道成吉思汗之孙若非贵盛尊荣便当威武刚猛，哪知竟是这么一个会说汉语谦和可亲的青年颇觉诧异。忽必烈向杨过微一打量后左手拉住法王命左右取酒三人各尽三斗马乳酒。杨过说'此酒辛辣酸涩入口如刀味道不美却是男子汉大丈夫的本色'——忽必烈大喜连声呼酒又各尽三斗。法王将杨过经历约略一说把他身份抬得甚高隐然当他是中原武林的大人物——杨过被他这么一捧不自禁也有些飘飘然。忽必烈奉命南取大宋江山在中原日久心慕汉化日常与儒生为伍读经学书又广聘武学高人结交宾客。大喜之下即命大张筵席酒肉满几蒙汉食事各居全半。忽必烈命请招贤馆的几位英雄来见，不多时左右报称客到。",
  "事件概要": "金轮法王将杨过引见忽必烈，杨过正式进入蒙古高层的招揽视野。",
  "insert": {
    "杨过": {
      "人物经历": {
        "神雕第十六回08-金轮法王引杨过见忽必烈": "随金轮法王进入忽必烈王帐。见忽必烈竟是一个会说汉语谦和可亲的青年颇觉诧异。与忽必烈金轮法王三人各尽三斗马乳酒——赞酒味'辛辣酸涩入口如刀却是男子汉大丈夫的本色'大合忽必烈心意。被金轮法王在忽必烈面前抬高身份隐然当他是中原武林大人物——不自禁也有些飘飘然之感"
      }
    },
    "忽必烈": {
      "人物经历": {
        "神雕第十六回08-金轮法王引杨过见忽必烈": "忽必烈见金轮法王引入少年杨过，引见知是人杰，与饮马乳酒三斗，闻其赞酒辛辣如刀乃大丈夫本色，大喜；闻法王述其经历益喜，赞得此人才乃大蒙古之幸，即命大张筵席，请招贤馆英雄来见。"
      },
      "关系网": {
        "杨过": "初次相识甚喜/60（见杨过年纪虽轻却言语不凡气度脱俗——敬酒对答之间已看出这个少年不同凡响。法王将他比作中原武林大人物后更添敬意。大喜之下连呼酒各尽三斗脱略形迹以兄弟相称）"
      }
    },
    "金轮法王": {
      "人物经历": {
        "神雕第十六回08-金轮法王引杨过见忽必烈": "携杨过之手走进王帐向忽必烈引见——盛赞杨过年纪虽轻却是一位了不起的人杰。将杨过经历约略一说言语中将他身份抬得甚高隐然当他是中原武林的一位大人物"
      }
    }
  },
  "update": {
