  },
  "事件结束时间": {
    "年": 1259,
    "月": 10,
    "日": 7,
    "时": 21
  },
  "事件引子": "你听说屋角一直蜷缩大睡的大头矮子突然翻身站起，轰然道：姑娘要见神雕侠却也不难，今晚我领你去见他就是。",
  "后续事件": {
    "事件名": "神雕第三十三回07-西山一窟鬼遇万兽山庄起冲突",
    "描述": "西山一窟鬼一行人驰往倒马坪途中经过万兽山庄树林，与史氏兄弟发生冲突。"
  },
  "事件详情": "郭襄正叹英雄会上未必有真英雄时，屋角一直蜷缩大睡的大头矮子突然翻身站起，轰然道要见神雕侠不难今晚便可领她去。郭襄大喜，郭芙起身问矮子姓名，矮子冷笑说天下似我这般丑陋之人岂有第二个。就在此时远处传来游丝般的声音低声呼唤'西山一窟鬼十者到其九，大头鬼此时不至更待何时'——话声若断若续充满森森鬼气。大头矮子一声大喝撞穿门板跃出，又忽地站回身前对郭襄说同他去。宋五惊恐说此人是西山一窟鬼中人物去不得，被矮子一掌打得撞墙昏晕。郭襄心意已决说纵然撞到妖魔鬼怪也要见神雕侠一见，双足一点从破门穿出。郭芙急追却被矮子以身躯挡住门口险些撞个满怀，跃出门时只听得远处轰轰大笑已不见郭襄踪影。大头鬼拉着郭襄如大青蛙般一跃跟着一跃向前，跃出里许后山后转出数十匹马上骑着九人——正是西山一窟鬼其余九人。郭襄见其中两个女子一个老态龙钟一个身穿大红衣裙，其余七人面目瞧不清楚。众人纵马向西北方驰出十余里，当先的长须老翁停马说要计议攻打神雕侠之事——郭襄这才大吃一惊，原来他们是要与神雕侠为敌。煞神鬼道出被神雕侠割去双耳的原委：他调戏霸占小妾、娶了又娶别个，神雕侠怒斥'你这般无情无义之徒世上多生几个岂不教天下女子心寒'，割其双耳约下月尽之夜倒马坪之约。众鬼计议车轮大战还是群起围攻要宰神雕侠。",
  "事件概要": "郭襄被大头鬼带离客店直赴倒马坪，意外卷入西山一窟鬼围攻神雕侠的谋划，与杨过的相见已近在眼前。",
  "insert": {
    "大头鬼": {
      "人物经历": {
