    "分": 15
  },
  "事件引子": "荒山绝顶狂风厉啸，刺骨寒雨倾泻，断崖边泥泞血迹蜿蜒伸向万丈迷雾。",
  "事件详情": "荒山绝顶狂风厉啸，刺骨寒雨漫天倾泻。游坦之双目已剜、双腿尽断且胸骨碎裂，瘫卧在血泥碎石中。他为阿紫倾尽毕生骨血与光明，换来的却只有嫌恶辱骂与绝情弃置，心中最后一丝苟活执念轰然崩塌，万念俱灰只求一死。在无边黑暗与剧痛中，游坦之不再哀嚎，而是咬碎牙关，凭借残存双臂将十指如鹰爪般狠狠抠入坚硬岩缝，拖着毫无知觉的残废下肢向悬崖边缘艰难爬行。嶙峋怪石划破其胸腹，指甲尽数崩裂翻卷，在荒崖泥径上拖曳出一条十余丈长的触目惊心血痕。风声愈发凄厉，游坦之血肉模糊的右手掌心终于探出岩台、抓入一片虚无。感知到下方深不可测的万丈渊薮，游坦之惨然凄笑，经脉中残存的冰蚕寒气最后一次激荡，双臂运足残劲向崖边猛力一推，残躯决绝腾空翻滚，径直坠入深渊白雾之中。崖风呼啸吞没一切，游坦之粉身碎骨殒命崖底，唯余岩边数道带血抓痕与几片撕裂的破烂衣布在寒风中摇曳。",
  "事件概要": "游坦之双目尽盲且残躯碎裂，惨遭阿紫绝情弃置后万念俱灰。他在黑暗与剧痛中咬牙以十指抠石，拖着残废躯体在荒岩间爬行十余丈；探至断崖边缘，游坦之惨然凄笑，运尽残存冰蚕寒劲决绝跃入万丈深渊，粉身碎骨殒命崖底。",
  "insert": {
    "游坦之": {
      "人物经历": {
        "天龙第四十四回03-游坦之万念俱灰跳崖自尽": "遭阿紫嫌恶弃置后万念俱灰，再无苟活之念；在无边剧痛与黑暗中以十指抠入坚岩硬石，拖着残废下肢在泥泞中爬向崖边，终在万丈深渊前惨然凄笑，运尽残存冰蚕寒劲腾身翻入白雾深渊，粉身碎骨自尽殒命。"
      }
    }
  },
  "update": {
    "游坦之": {
      "状态": "死亡"
    }
  },
  "后续事件": {
    "天龙第四十四回04-段誉继位为君迎娶王语嫣": "游坦之殒命深渊尽散痴孽，少室山风波告一段落，大理诸事底定，静候段誉回朝履位。"
  },
  "参与人物": [
    "游坦之"
  ]
}

