    "时": 15,
    "分": 30
  },
  "事件引子": "小艇泊岸，曼陀山庄内漫山茶花姹紫嫣红、暗香扑鼻，花径深处忽起幽幽叹息。",
  "事件详情": "段誉与阿朱、阿碧驾乘小艇逃脱追捕，一路疾驰抵达曼陀山庄码头，随即弃舟登岸以避凶险。众人踏入庄内，只见漫山遍野盛开着姹紫嫣红的珍奇茶花，微风拂过，馥郁芳香四溢扑鼻。三人正沿着花径前行，幽深的花树掩映深处忽然传来一阵清丽绝伦、婉转动人的女子幽幽叹息之声。段誉心弦微动，循声穿过重重繁茂的花丛凝神望去，只见一株盛放的花树之下，静静伫立着一名白衣如雪的绝色少女，正若有所思地凝眸抚弄花瓣。那少女身姿婀娜绰约，肌肤宛若凝脂白玉，容颜清丽绝世，其眉目轮廓竟与段誉早先在无量山石洞中所参拜的“神仙姐姐”玉像生得一模一样，宛若那尊汉白玉雕像化为生灵走入了人间凡尘。段誉只觉脑海中轰然炸响，浑身剧烈颤抖如遭雷击，整个人痴痴定在原地，情不自禁地脱口惊呼“神仙姐姐”。段誉刹那间神魂颠倒、心旌动摇，就此万劫不复地陷入了对王语嫣无怨无悔的一生痴恋之中。",
  "事件概要": "段誉随阿朱、阿碧弃舟登上曼陀山庄避险，循着幽微叹息穿行于繁茂花丛，赫然惊见花树下一名容貌与无量山“神仙姐姐”玉像全然无二的白衣绝色少女。段誉震骇之下失声惊呼，神魂颠倒间就此深陷痴恋。",
  "insert": {
    "段誉": {
      "人物经历": {
        "天龙第十二回06-曼陀山庄段誉惊遇语嫣": "随二女弃舟登岸避入曼陀山庄，循着花径深处传来的幽幽叹息穿林寻去，赫见树下一名白衣少女容貌神态竟与无量山石洞中的玉像分毫不差；刹那间如遭雷击、神魂颠倒，情不自禁脱口惊呼“神仙姐姐”，就此满心沉沦于难以自拔的痴恋之中。"
      }
    },
    "阿朱": {
      "人物经历": {
        "天龙第十二回06-曼陀山庄段誉惊遇语嫣": "引小艇避开番僧追捕靠泊曼陀山庄码头，携阿碧与段公子弃舟登岸暂避凶险；引着众人沿着繁花盛开的花径深入庄内，忽闻幽深花树深处传来女子叹息声与段公子的失声惊呼。"
      }
    },
    "阿碧": {
      "人物经历": {
        "天龙第十二回06-曼陀山庄段誉惊遇语嫣": "同阿朱姐姐合力操舟摆脱凶险险境，在曼陀山庄码头弃舟登岸，随二人穿行于漫山遍野盛开的茶花小径之间；正自步履匆匆暂谋容身，忽听林中传来幽微叹息与段公子的痴绝呼喊。"
      }
    },
    "王语嫣": {
      "人物经历": {
        "天龙第十二回06-曼陀山庄段誉惊遇语嫣": "独倚盛放的花树下抚弄茶花花瓣，正自若有所思地幽幽叹息，冷不防花丛外忽有一名陌生年轻书生循声而来，更神色震骇地脱口直呼自己为“神仙姐姐”，心绪顿起惊愕涟漪。"
      }
    }
