      }
    },
    "阿紫": {
      "人物经历": {
        "天龙第二十三回07-康敏照镜见毁容惊骇暴毙": "冷酷掰开恶妇眼皮逼其直视铜镜中的毁容惨状，亲睹其在极端惊骇与绝望中凄厉尖叫、喷血抽搐暴毙，冷眼坐视其气绝栽倒于梳妆台前。"
      }
    }
  },
  "update": {
    "康敏": {
      "状态": "死亡"
    }
  },
  "后续事件": {
