    },
    "杨过": {
      "人物经历": {
        "神雕第五回05-小龙女现身孙婆婆临终托付": "见小龙女突然出现在大殿门口凄然告状。舍命维护孙婆婆的情形被小龙女瞧在眼里眼中满是泪水。孙婆婆临终嘱托时知其心意弯腰将耳朵与她口唇碰在一起听她低语。孙婆婆满口鲜血喷出溅得自己半边脸与胸口衣襟都是斑斑血点，伤心难忍伏在婆婆身上号啕大哭"
      }
    }
  },
  "update": {
