{
  "事件地点": "大宋/河南府/马宅/密室内堂",
  "触发条件": {
    "类型": "时间",
    "年": 1092,
    "月": 3,
    "日": 16,
    "时": 23,
    "分": 20
  },
  "事件结束时间": {
    "年": 1092,
    "月": 3,
    "日": 16,
    "时": 23,
    "分": 50
  },
  "事件引子": "屋顶瓦片碎裂崩飞，昏暗内室中寒风呼啸，血腥之气弥漫，杀机凌厉慑人。",
  "事件详情": "黑衣神秘人倏忽遁走、全冠清仓皇逃命之后，屋顶之上的乔峰再也无法压抑胸中翻江倒海的狂怒与悲痛。他体内浩瀚真气猛然爆发，双脚一顿震裂漫天屋瓦，整个人如狂怒苍鹰般携着凌厉风雷破窗直坠而下。落地刹那，乔峰右臂如闪电探出，五指似淬火精钢铸就的铁箍，一把狠狠卡死了瘫坐在地上的马夫人康敏的纤细脖颈，将这蛇蝎妇人硬生生凌空提至自己眼前。乔峰双目充血赤红，面容因极致的悲愤而扭曲，声若九天炸雷般厉声喝问三十年前雁门关惨案中那位“带头大哥”的真实法号与姓名。被锁喉悬空的康敏面色涨紫、气息艰难，但其骨子里的扭曲与自负已臻病态，深知今日绝无幸免之理，不仅毫无惧色求饶，反倒从染血的嘴角挤出刺耳狂笑。她眼神阴毒至极，用极尽恶毒刻薄的话语疯狂嘲讽乔峰空有一身通天彻地的盖世神功，却不过是个被自己玩弄于股掌、亲手打死至爱阿朱的愚蠢汉子，并咬碎带血银牙发下毒誓，至死也休想从她嘴里撬出一个字。乔峰悲怒交加，铁指深深陷进其颈项皮肉勒出数道紫黑淤痕，却强自克制未下杀手，双方在昏暗屋内陷入冰冷绝望的审讯死局。",
  "事件概要": "乔峰怒极破窗直坠内室，铁指锁喉凌空提起康敏，厉声逼问当年雁门关惨案带头大哥的真实姓名。康敏已知必死，反倒狂笑讥讽乔峰枉有盖世武功却愚蠢错杀至爱阿朱，并发毒誓拒不吐露半字。乔峰悲怒交加强忍杀念，审讯陷入绝望死局。",
  "insert": {
    "乔峰": {
      "人物经历": {
        "天龙第二十三回05-乔峰破窗逼问带头大哥": "震碎屋顶瓦片飞身破窗而入，铁指死死锁住康敏咽喉凌空提起，厉声喝问当年雁门关惨案带头大哥的真实身份；面对其恶毒讥讽自己亲手打死阿朱且拒不吐供的狂笑，胸中悲愤欲狂，却强自克制未下杀手，双方僵持于昏暗内室。"
      }
    },
    "康敏": {
      "人物经历": {
        "天龙第二十三回05-乔峰破窗逼问带头大哥": "瘫坐内室忽遭破窗而入的乔峰锁喉凌空提起，厉声追问带头大哥身份；深知今日难逃一死，遂咬牙狂笑恶毒嘲讽其枉称英雄却被自己玩弄掌中打死至爱，立下毒誓绝不吐露实情。"
      }
    }
  },
  "update": {
    "康敏": {
      "状态": "受制"
    }
  },
  "后续事件": {
    "天龙第二十三回06-阿紫施蚁刑以铜镜逼供": "乔峰面对康敏宁死不屈的死局束手无策，同行赶至马宅的阿紫眼见审讯受阻，暗运星宿派毒辣手段准备插手施刑逼供。"
  },
  "参与人物": [
    "乔峰",
    "康敏"
  ]
