{
  "事件地点": "大理/云南/大理城/皇宫",
  "触发条件": {
    "类型": "时间",
    "年": 1092,
    "月": 3,
    "日": 16,
    "时": 14,
    "分": 0
  },
  "事件结束时间": {
    "年": 1092,
    "月": 3,
    "日": 20,
    "时": 16,
    "分": 30
  },
  "事件引子": "内廷偏殿内檀香幽幽，案几上摊开着泛黄的无量山密道舆图，气氛肃穆凝重。",
  "事件详情": "段誉眼见王语嫣深陷容貌衰老的心魔煎熬、整日研磨药石致使神思恍惚且日渐消瘦，心中充满了怜惜与疼惜。为了彻底宽慰爱妻、解开其心头那道近乎病态的容貌死结，段誉决意迎请无量山玉洞中的神仙姐姐雕像入宫供其观瞻比对。段誉在内廷偏殿密召大理御林侍卫统领与技艺最精湛的石雕工匠，当面展开无量山密道图卷，神色极其严肃地下达御令：“此玉雕乃天地造化之至宝，起运全程万勿有丝毫磕碰损伤，若损分毫定按律严惩！”段誉亲自监督，命内库拨出大批特制的厚软毛毡、粗麻绞索以及减震极佳的双辕大车，令侍卫与工匠领命后星夜兼程赶赴无量山澜沧江畔的琅嬛福地。众人潜入潮湿幽深的无量玉洞，在石室微光下肃立行礼，随后小心翼翼地利用特制木撬与滑轮，将整尊通体晶莹的白玉雕像平稳移离石基。工匠们以层层织锦缎匹与厚软毛毡将玉像从头到脚严密包裹捆扎，合力抬上减震车驾。历经数日跋涉护送，车队毫发无损地将玉像运抵大理皇宫，稳妥安放于内苑静心殿深处，垂下重重帷幔，静候帝后亲临观瞻。",
  "事件概要": "段誉因怜惜王语嫣深陷容貌焦虑，决意自无量玉洞迎请神仙姐姐雕像入宫供其排解心魔。他在内廷偏殿严令侍卫统领与能工巧匠携减震车乘潜入琅嬛福地，历经数日跋涉，终将毫无损伤的白玉雕像平稳移置于内苑静心殿中。",
  "insert": {
    "段誉": {
      "人物经历": {
        "天龙第四十八回03-段誉命工匠起运神仙姐玉像": "见语嫣为红颜易老之念所困、消瘦恍惚，心疼难当之下密召侍卫与巧匠，亲授舆图敕令赴无量山迎请玉像；见数日后白玉雕像毫发无损地运抵静心殿安置，深盼此举能解爱妻心结。"
      }
    }
  },
  "update": {},
  "后续事件": {
    "天龙第四十八回04-段誉伴王语嫣烛下共瞻玉像": "神仙姐姐白玉雕像已妥善运抵并移置于静心殿深处，帷幔重垂，静候帝后亲临一睹真容。"
  },
  "参与人物": [
    "段誉"
  ]
}

178154.content:
{
  "事件地点": "大宋/晋南/黑龙潭",
  "触发条件": {
    "类型": "时间",
    "年": 1259,
    "月": 10,
    "日": 10,
    "时": 8
  },
  "事件结束时间": {
    "年": 1259,
    "月": 10,
    "日": 10,
    "时": 9
  },
  "事件引子": "你来到黑龙潭边，只见方圆七八里内草木不生，眼前一片死气沉沉的泥沼。潭心堆着不少枯柴茅草，隐约有白影闪动——那九尾灵狐便藏身其中。",
  "后续事件": {
    "事件名": "神雕第三十四回04-一灯求见杨过长啸逼瑛姑恩怨揭晓",
    "描述": "瑛姑以死相胁不肯交出灵狐，此时身后传来一声佛号，一灯大师求见瑛姑"
  },
  "事件详情": "杨过独自北行前往黑龙潭，郭襄好奇心起缓步跟随。杨过加快脚步试她轻功，郭襄展开家传轻功追赶却越落越远，一交摔在雪地中哭了出来。杨过倏去倏回拾起她掉落的手帕，郭襄反过来诬他抢帕。两人互相试探身份，郭襄不肯先说姓名，杨过也不愿以真面目示人。郭襄说起风陵渡听来的神雕侠事迹，衷心钦佩。杨过一时兴起要她说出几位大英雄才肯带她同行，郭襄说出父亲郭靖、母亲黄蓉、外公黄药师、鲁有脚四位，最后灵机一动说出神雕侠也算一位。杨过笑道大英雄岂能失信于小姑娘，携她同往黑龙潭。到达潭边后杨过以树枝掷入淤泥试出深浅，折下两根树枝缚在脚底在潭泥上滑行如飞。又为郭襄缚好树枝，握住她手带她滑入潭中。两人发现潭心柴草布置暗合五行方位，杨过高声呼喊却无人应答。忽然两只九尾灵狐从草丛中钻出分头逃窜，杨过独自追狐与灵狐在雪泥上风驰电掣般追逐。他以雪团击倒一头灵狐，存心与另一头赛脚力，赶至灵狐之前衣袖挥处将灵狐卷入袖中。不料灵狐竟是装死，郭襄用枯柴探草丛时引出白发老妇瑛姑。瑛姑恶狠狠望着二人，杨过施礼求赐灵狐救治朋友，瑛姑却凄惨大笑说起自己孩儿当年受伤无人肯救的往事。杨过好言恳求，瑛姑提出要郭襄留下陪伴十年作为交换。杨过婉拒，瑛姑出掌攻击，杨过连挨三掌不还手。瑛姑见伤他不得，提起灵狐厉声威胁：若再上前一步便捏死灵狐。",
  "事件概要": "杨过携郭襄追狐至黑龙潭并惊动瑛姑，灵狐仍未到手，求药之事转而系于化解她与旧人的深仇。",
  "insert": {
    "杨过": {
      "人物经历": {
        "神雕第三十四回03-杨过郭襄黑龙潭追狐遇瑛姑": "杨过带郭襄去黑龙潭，以树枝缚脚滑行泥沼，见潭心柴草暗合五行，料潭中有人。追捕灵狐以衣袖卷住，灵狐装死引瑛姑出。杨过自认捉其爱物理亏，受瑛姑三记寒阴箭不还手，笑吟吟若无事。"
      }
    },
    "郭襄": {
      "人物经历": {
