  "事件引子": "石壁珍珑前黑白棋子森然如列阵，幽谷松风肃杀，唯闻石子破空激射之声。",
  "事件详情": "段誉败退后，慕容复为扬姑苏威名、招揽天下豪杰以图光复大燕帝业，理了理长袍昂然出阵。他自负才智绝顶、文武双全，誓要踏平石壁珍珑，以全复国大计。慕容复神情冷峻，以内力吸过白子，隔空激射入石壁“上平三四路”。他落子雷厉风行、杀气腾腾，排兵布阵宛如大军对垒，步步紧逼黑子中腹。然而珍珑棋局暗合阴阳生克之变，苏星河从容落黑子围追堵截，黑白双方便如两军血战沙场。弈至五十余手，棋局杀意狂暴奔涌，慕容复心神剧烈震荡，眼前石壁上的棋子竟幻化作千军万马，旌旗猎猎、杀声震天。幻象之中，大燕铁骑尽遭重重合围，部众伏尸千里，慕容复左冲右突皆是绝路。复国狂念与绝望交织成凶猛心魔，死死扼住其神识。他双目赤红如血，面容惨白扭曲，惨然狂笑：“大燕亡了！三军尽没，我慕容复复国无望，何颜立于天地之间！”在极度癫狂与神智崩溃之下，他心智彻底失守，右手猛然拔出腰间寒光凛冽的佩剑，顺势横架于咽喉之上，便要横剑自刎断送残生。佩剑锋刃已然割破颈间表皮、渗出丝丝鲜血，四大家臣惊呼救援不及，满场群豪骇然失色，慕容复命悬一线，陷入走火入魔自残之死局。",
  "事件概要": "段誉认负后慕容复昂然入局，欲破残局扬名以图复燕。慕容复落子凌厉杀气极重，却陷于苏星河精妙杀招与棋局幻象之中，复国狂念引发暴烈心魔。他在极度癫狂下神智彻底失守，拔剑横颈自刎，剑刃已割破咽喉渗血，命悬一线。",
  "insert": {
    "慕容复": {
      "人物经历": {
        "天龙第三十一回03-慕容复执念入魔欲自刎": "为招揽群雄以全复燕大业昂然接弈珍珑，布阵杀伐步步紧逼，弈至五十余手却见石壁化为万马覆灭之绝境；在三军尽没的幻象与心魔噬咬下神智癫狂崩溃，惨笑拔剑横刎咽喉，决意以死殉国。"
      }
    },
    "苏星河": {
      "人物经历": {
        "天龙第三十一回03-慕容复执念入魔欲自刎": "见姑苏慕容复昂然出战且棋风杀伐凌厉，从容操持黑子顺应阴阳生克步步截堵围剿，坐视其在五十余手后终因执念过深深陷心魔幻境、拔剑自戕。"
      }
    },
    "段誉": {
      "人物经历": {
        "天龙第三十一回03-慕容复执念入魔欲自刎": "退归阵中凝神观战，见慕容复下子杀伐刚猛却渐露迷乱，五十余手后竟惨呼大燕亡尽、拔出佩剑横割咽喉自尽，眼见其颈间渗血命在旦夕，心中惊骇大急。"
      }
    }
  },
  "update": {
