      }
    },
    "阿朱": {
      "人物经历": {
        "天龙第十七回09-菩提院镜后偶遇重伤阿朱": "易容潜入少林盗得经书，却遭玄难大金刚拳重创震碎经脉，濒死蜷缩于菩提院镜后；弥留之际见乔峰现身，拼尽残力将怀中《易筋经》滑落托付，在其浩瀚内力护持下勉力维持一丝残息。"
      },
      "关系网": {
        "乔峰": "托付信赖/80"
      }
