  "事件引子": "少室山麓柴扉半掩，昔日温馨的农舍死寂无声，唯有浓重的血腥气自门缝中弥散而出。",
  "事件详情": "乔峰身负契丹遗孤的身世谜团，内心惊涛骇浪难平，辞别江南后日夜兼程、千里迢迢赶回少室山下，急欲向抚养自己成人的养父母乔三槐夫妇当面问清当年雁门关惨变与收养真相。乔峰怀着忐忑与依恋推开熟悉的农舍柴扉，口中深情呼唤“爹、娘”，然而屋内死寂无声，唯有一股刺鼻血腥扑面而来。他抢步冲入堂屋，眼前惨状令他如坠冰窟：养父乔三槐与养母双双仆倒在暗红血泊之中，身躯僵硬冰冷。乔峰扑上前去颤抖着抱起二老，伸手探查鼻息与经脉，发现二老胸骨尽数碎裂塌陷，心脉被一股极其强横霸道的高深内力硬生生震断，五脏六腑受创糜烂，分明是死于当世绝顶高手的狠毒重击之下。乔峰本拟向至亲求证身世以洗刷污名，却骤见含辛茹苦抚育自己的双亲惨遭灭口横祸，杀人者手法凶狠且分明蓄意栽赃，这令他五内俱崩，在悲痛欲绝中伏尸痛哭，仰天发出杜鹃啼血般的凄厉长啸。乔三槐夫妇当场气绝殒命，乔峰满手与衣襟皆被双亲鲜血染红，农舍内桌翻椅碎，身世真相亦因二老惨死而陷入死无对证的绝境。",
  "事件概要": "乔峰日夜兼程赶回少室山求证身世，推门却惊见养父母双双惨遭绝顶内力震断心脉毙命。身世真相骤成死无对证之局，乔峰满手血污伏尸悲号，深陷遭人蓄意灭口构陷的滔天危局。",
  "insert": {
    "乔峰": {
      "人物经历": {
        "天龙第十七回04-乔峰归家惊见养父母惨死": "满怀忐忑推门归家欲向二老求证身世真相，却骇见养父母倒卧血泊、胸骨尽碎心脉断绝，五内俱崩下伏尸痛哭，仰天发出凄厉长啸。"
      }
    },
    "乔三槐": {
      "人物经历": {
        "天龙第十七回04-乔峰归家惊见养父母惨死": "在农舍中骤遭绝顶高手狠辣突袭，胸骨被至强霸道的内力生生震断塌陷，五脏受创糜烂，未及等到养子归家便气绝殒命于血泊之中。"
      }
    }
  },
  "update": {
    "乔三槐": {
      "状态": "死亡"
    }
  },
  "后续事件": {
    "天龙第十七回05-巡山僧误认凶手乔峰奔少林": "乔峰悲愤交加欲掩埋双亲遗体，忽闻舍外脚步杂沓，少林巡山僧人循声而至推门探看。"
  },
  "参与人物": [
    "乔峰",
    "乔三槐"
  ]
}

211825.content:
{
  "事件地点": "大宋/河南府/擂鼓山/棋局石壁幽谷",
  "触发条件": {
    "类型": "时间",
