  "事件引子": "石壁前黑龙气绝残局顿开，聪辩先生老泪纵横，四下群雄屏息震骇、鸦雀无声。",
  "事件详情": "眼见黑子大龙尽诛、珍珑残局彻底解开，聪辩先生苏星河激动得老泪纵横，三十年隐忍受辱与师门夙愿终于在这一刻得偿所愿。他遵照逍遥派门规及恩师无崖子立下的严苛誓约，正式认定解局之僧虚竹为逍遥派唯一有缘传人。苏星河整肃衣冠，无视在场目瞪口呆的鸠摩智、慕容复以及少林众高僧，快步走到茫然失措的虚竹身前，双膝微屈深深作揖行礼，恭敬道：“恭喜小师傅勘破神局！先师无崖子老人家在三仙洞中恭候有缘人已整整三十年，请随老朽入洞拜见！”少林玄难大师合十欲阻，言明虚竹乃少林低辈弟子不宜涉足他派隐秘；虚竹亦惶恐推辞，连连称自己只是误打误撞。苏星河却态度坚决如铁，拂袖一振挡开众人，拉住虚竹僧袍袖口执意相请。在群雄艳羡与震骇的目光聚焦下，虚竹身不由己，只得随苏星河举步前行。苏星河引着虚竹穿过擂鼓山幽深松林与嶙峋怪石，行至后山绝壁处，伸手推开掩映在藤蔓后的沉重石门。两人踏入漆黑幽邃的三仙洞中，沉重石门轰然闭合将外界喧嚣彻底隔绝，珍珑破局之会圆满落幕，懵懂的小和尚虚竹就此正式跨入逍遥派三十年不传的惊天机缘与武林隐秘之中。",
  "事件概要": "珍珑得解，苏星河狂喜认定虚竹为先师无崖子苦候三十年的唯一传人，整肃衣冠大礼相迎。面对玄难出言劝阻与虚竹的惶恐推辞，苏星河态度决绝执意相邀，引其穿松林入后山绝壁。随着三仙洞沉重石门轰然闭合，虚竹就此踏入逍遥派不传之秘与惊天机缘之中。",
  "insert": {
    "苏星河": {
      "人物经历": {
        "天龙第三十一回09-苏星河引虚竹入洞见无崖子": "见珍珑死局终被勘破，三十年师门夙愿得偿，喜极而泣下整肃衣冠向少林小僧深揖拜贺；力排玄难阻挠与小僧惶恐推辞，执意引其穿过松林步入后山三仙洞拜谒恩师，合拢石门隔绝尘寰。"
      }
    },
    "虚竹": {
      "人物经历": {
        "天龙第三十一回09-苏星河引虚竹入洞见无崖子": "见自己误打误撞竟破开死局，引得聪辩先生大礼相拜并坚请入洞拜见无崖子老前辈，一时慌乱无措连连推辞；奈何师叔祖阻拦未果且对方坚执相邀，只得身不由己随其穿林入洞，在石门闭合的轰鸣声中茫然面对未知机缘。"
      }
    },
    "玄难": {
      "人物经历": {
        "天龙第三十一回09-苏星河引虚竹入洞见无崖子": "见聪辩先生认定虚竹解开珍珑、欲强引其入洞拜见无崖子，唯恐本门低辈弟子涉入他派隐秘招致祸端，当即合十出言劝阻；无奈对方态度坚决执意相邀，只能眼看虚竹被其带离幽谷步入后山秘洞。"
      }
    },
    "慕容复": {
      "人物经历": {
        "天龙第三十一回09-苏星河引虚竹入洞见无崖子": "眼见自己殚精竭虑未能破解且险些丧命的珍珑神局，竟被一个毫无弈道根基的少林丑僧误打误撞勘破，更见聪辩先生折节大礼引其入洞继承三十年机缘；在旁目瞪口呆，心中妒恨交加却无可奈何。"
      }
    },
    "鸠摩智": {
      "人物经历": {
        "天龙第三十一回09-苏星河引虚竹入洞见无崖子": "冷眼旁观少林懵懂小僧破开残局，见聪辩先生竟对其奉若上宾、折节躬身引其步入绝壁秘洞拜见无崖子；见逍遥派三十年不传的绝世机缘竟落入鲁钝小僧之手，暗自震骇艳羡，合十冷观其变。"
      }
    }
  },
  "update": {
    "虚竹": {
      "所在位置": "大宋/河南府/擂鼓山/三仙洞"
    },
    "苏星河": {
      "所在位置": "大宋/河南府/擂鼓山/三仙洞"
    }
  },
  "后续事件": {
    "天龙第三十二回01-虚竹随苏星河入洞拜谒无崖子": "虚竹随苏星河步入幽深的三仙洞拜见无崖子，由此正式跨入逍遥派尘封三十年的武林隐秘与旷世传承之中。"
  },
  "参与人物": [
    "苏星河",
