  "事件引子": "石壁珍珑黑白交错杀伐正烈，铁杖点地铮然作响，谷中阴风骤起、杀气弥漫。",
  "事件详情": "慕容复狼狈退场后，“恶贯满盈”段延庆拄着双铁杖沉沉上前。他本是大理国延庆太子，昔年惨遭内乱皇位被篡、肢体残废面容尽毁，半生积聚的滔天仇怨与夺位执念刻骨铭心，欲借攻破这天下第一奇局证明自身天命所归。段延庆喉间发出阴恻腹语，右手精钢拐杖猛然一点，内力催动一枚白子如强弩般深凿入石壁“平位四二路”。其棋风极度狠辣凶戾，招招阴鸷诡谲，全是不留退路的搏命绞杀。苏星河神色微凝，拈黑子沉着拆解。段延庆越下越急，内力狂吐，铁杖在石壁上划出阵阵刺耳火星。石壁珍珑所蕴含的迷魂摄魄魔力被其凶戾棋路彻底激发，黑白子力交错间，昔年受辱、血流成河的悲惨过往排山倒海般涌入脑海。滔天怨恨化作汹涌心魔反噬脏腑，段延庆神识被仇恨吞噬，铁杖胡乱挥舞。他体内经脉狂乱逆行，丹田真气如脱缰野马疯狂冲撞奇经八脉，面皮青紫抽搐，双目渗出猩红血丝，已然深陷走火入魔绝境，高举左手精钢拐杖便要朝自身天灵盖猛击自尽。段延庆经脉受损、真气逆乱，手中铁杖杀机毕露逼向己身死穴，四大恶人惊呼失措，一代凶煞命悬一线、濒临气绝身亡。",
  "事件概要": "段延庆欲破珍珑以证天命，运内力以铁杖落子强攻，棋路阴鸷凶戾、步步绞杀。不料局中摄魂魔力激起其昔年惨痛身世与滔天怨念，心魔反噬之下经脉狂乱逆行。段延庆面目青紫陷入走火入魔绝境，神智崩溃高举精钢拐杖猛击己身天灵欲自戕，命悬一线。",
  "insert": {
    "段延庆": {
      "人物经历": {
        "天龙第三十一回05-段延庆怨念反噬走火入魔": "手拄双铁杖上前强弈珍珑，以内力催动白子狠辣搏杀，欲攻破奇局以证自身天命；未料棋中魔力勾起被夺皇位与残废受辱之惨痛过往，滔天仇怨反噬脏腑致使真气暴走逆乱，神智癫狂之下举起精钢拐杖直击己身天灵死穴。"
      }
    },
    "苏星河": {
      "人物经历": {
        "天龙第三十一回05-段延庆怨念反噬走火入魔": "见段延庆运杖落子狠厉诡谲、招招不留退路，遂拈黑子沉着拆解围截；冷眼察觉其被棋局幻象引动心魔，体内真气狂乱冲撞奇经八脉，眼见其神识尽失举杖欲击顶自绝，只静坐观变而不出手干预。"
      }
    }
  },
  "update": {
    "段延庆": {
      "状态": "走火入魔、经脉逆乱"
    }
  },
  "后续事件": {
    "天龙第三十一回06-虚竹闭目掷子自填一大片": "段延庆神识狂乱欲以铁杖自击天灵气绝之际，场边忽有一名少林虚字辈小和尚闭目趋前，胡乱掷下一枚白子救人解局。"
  },
  "参与人物": [
