    "月": 12,
    "日": 2,
    "时": 11
  },
  "事件引子": "你听说郭襄行出三十余里腹中饥饿坐在路旁——忽听马蹄声响，一乘马自东而西奔来，马上坐着个极高极瘦的年老僧人……",
  "后续事件": {
    "事件名": "神雕第三十七回08-杨过问黄药师南海神尼真相大白",
    "描述": "金轮法王携郭襄北去。而在南边宜城酒楼中，杨过终于见到了黄药师……"
  },
  "事件详情": "郭襄行出三十余里腹中饥饿却找不到饭店——襄阳城郊百姓早已十室十空。正坐在路旁石上发愁时一乘马自东而西奔来，马上坐着个极高极瘦的年老僧人。老僧折返问她找谁——郭襄说找'没有右臂的青年男子'。老僧正是金轮法王，心中暗惊却现喜色自称'珠穆朗玛大师'是郭靖的过命交情，谎称郭靖已死兼程赶来祭拜竟泪流满面骗得郭襄信任。郭襄说出自己身份后法王大喜——当真天降之喜。路上遇到大头鬼和长须鬼樊一翁——二鬼认出金轮法王叫郭襄快过来。法王身形略晃欺近二鬼双掌齐下——这十余年他在蒙古苦练'龙象般若功'已冲破第九层达第十层境界震古烁今，每一掌具十龙十象大力。大头鬼举臂一格手臂立即折断脑门中掌当场毙命。樊一翁功力远为深厚——使一招托天势双手举起撑持仍被千斤重力压在背上扑地便倒。樊一翁喷血纵起舍命抱住法王双腿叫郭襄快逃——被法王抓住背心提起摔出气绝身亡。郭襄又惊又怒凛然道'恶和尚姑娘随你去便是'——将二鬼尸身放在马背送其归家。法王赞道'将门虎女不愧乃父'携郭襄北去。",
  "事件概要": "郭襄落入金轮法王掌控，大头鬼与樊一翁战死，襄阳方面失去她的确切行踪。",
  "insert": {
    "金轮法王": {
      "人物经历": {
        "神雕第三十七回07-郭襄遇金轮法王二鬼遇害": "襄阳城外遇郭襄，诈称珠穆朗玛大师骗其信任；大头鬼被识破后一掌击毙，樊一翁舍身护郭襄被摔死。其龙象般若功练至第十层，携郭襄北去，欲双掌败杨过小龙女雪耻。"
      }
    },
    "郭襄": {
      "人物经历": {
        "神雕第三十七回07-郭襄遇金轮法王二鬼遇害": "在路边遇到极高极瘦的老僧自称珠穆朗玛大师——谎称是父亲过命交情骗得信任答应带她去找杨过。路上遇大头鬼长须鬼——二鬼认出法王叫自己快逃却被法王突下杀手双双毙命。又惊又怒凛然道'恶和尚你恁地歹毒'——面对法王毫无惧色。将二鬼尸身绑在马上送归家乡。被法王携着北去"
      }
    },
    "樊一翁": {
      "人物经历": {
        "神雕第三十七回07-郭襄遇金轮法王二鬼遇害": "与大头鬼在道上遇到郭襄和金轮法王同行——认出法王后叫郭襄快过来。法王突然欺近双掌齐下——功力虽远较大头鬼深厚使托天势双手撑持仍被千斤重力压倒喷血。见郭襄不肯独自逃命舍身扑上牢牢抱住法王双腿铁圈般死不松手——叫'姑娘快逃'后被法王抓住背心掷出气绝毙命。为护郭二小姐壮烈赴死"
      }
    },
    "大头鬼": {
      "人物经历": {
        "神雕第三十七回07-郭襄遇金轮法王二鬼遇害": "与长须鬼樊一翁在道上遇到郭襄和金轮法王同行——认出法王后叫郭襄快过来不要上当。法王倏袭时举臂一格手臂立即折断——脑门跟着中掌连哼也没哼一声当场毙命。天生神力仍挡不住法王十龙十象的掌力"
      }
    }
  },
  "update": {
