      "状态": "诓骗郭襄得手后击杀大头鬼长须鬼二鬼携郭襄北去。龙象般若功已练至第十层——震古烁今前无古人。志在找杨过小龙女双掌败之以雪当年之耻",
      "功法": {
        "龙象般若功": {
          "掌握程度": "出神入化（冲破第九层达第十层境界——震古烁今前无古人。每一掌击出均具十龙十象的大力。自知再求进境此生已属无望但既已自信天下无敌手便练到第十一层也已多余。当年败在杨过小龙女剑下引为生平奇耻如今功力倍增趁蒙古皇帝御驾亲征扈驾南来要双掌击败杨龙夫妇以雪当年之耻）"
        }
      }
    },
    "郭襄": {
      "所在位置": "大宋/襄阳/郊野",
      "状态": "被金轮法王诓骗后识破其真面目——但二鬼已为护她而丧命。面对法王凛然无惧被其携着北去不知押往何处"
    },
    "樊一翁": {
      "状态": "被金轮法王摔出气绝身亡——为护郭二姑娘舍命而死。尸身被郭襄放在马上送回家乡。一生忠义最终为护友人之女壮烈牺牲",
      "所在位置": "大宋/襄阳/郊野"
    },
    "大头鬼": {
      "状态": "被金轮法王一掌击毙——手臂折断脑门中掌当场身亡。尸身被郭襄放在马上送回。外型丑陋却义气深重——护主殒命"
    }
  },
