      }
    },
    "全冠清": {
      "人物经历": {
        "天龙第三十回01-萧峰率十八骑现身遭群雄围逼": "眼见局势因契丹铁骑闯入骤变，当即拔剑厉声高呼煽动群雄结阵诛杀契丹贼首，妄图借天下群豪之手除掉萧峰，却被其雄浑浩瀚的内力断喝震慑得心胆俱裂，不敢率先上前。"
      }
    },
    "阿紫": {
      "人物经历": {
        "天龙第三十回01-萧峰率十八骑现身遭群雄围逼": "双目失明受制于人，忽闻山道上熟悉的狂飙马蹄声与那声威震全场的豪迈断喝，顿知姐夫萧峰已然赶来少室山相救，狂喜惶急之下拼命挣扎求援。"
      }
    },
    "萧峰": {
      "人物经历": {
        "天龙第三十回01-萧峰率十八骑现身遭群雄围逼": "为探寻阿紫安危身披锦袍率燕云十八骑长驱直入少林，见中原群雄拔刃合围，傲然勒马按枪环视四方，运起磅礴内力沉声喝阻全场，凛然不惧天下英雄围逼。"
      }
    }
  },
