      }
    },
    "萧峰": {
      "人物经历": {
        "天龙第三十九回02-耶律洪基下旨命萧峰领兵伐宋": "奉旨入宫觐见结义兄长，未料耶律洪基开门见山展露吞宋野心，更当殿颁旨强令自己挂帅充当南征先锋，心神巨震下登时深陷契丹君命与故土养育深恩的两难深渊。"
      }
    }
  },
  "update": {},
  "后续事件": {
