{
  "事件地点": "蒙古/襄阳城外/忽必烈大营/王帐",
  "触发条件": {
    "类型": "时间",
    "年": 1244,
    "月": 11,
    "日": 23,
    "时": 10
  },
  "事件结束时间": {
    "年": 1244,
    "月": 11,
    "日": 23,
    "时": 11
  },
  "事件引子": "忽必烈设下盛大筵席，酒肉满几。帐门开处走进四个人来——当先一人身材高瘦脸无血色形若僵尸乃是湘西名宿潇湘子。其后是来自天竺的矮黑高手尼摩星、回疆力士马光佐、波斯大贾尹克西。",
  "后续事件": {
    "事件名": "神雕第十六回10-周伯通闯帐夺牛肉戏弄众人",
    "描述": "金轮法王筷子争肉正大显神威之际，忽听得远处有人高声呼叫郭靖——此人内力之厚身法之快均是世上少见，瞬息之间已至帐前。"
  },
  "事件详情": "酒过三巡天竺高手尼摩星忍耐不住要见识蒙古第一国师的武功。金轮法王夹了一大块牛肉语带机锋说'这块是盘中最大最肥的牛肉了老衲原也不想吃它只是偶尔伸筷偶尔夹着在佛家称为缘法'——暗指国师之位。马光佐不明其意伸筷去夹，法王筷子横出轻轻一碰马光佐手臂剧震筷子落地。马光佐五根手指牢牢捏住筷子再去夹——喀喇一声筷子断为四截如刀斩一般。尼摩星五指如铁爪猛往肉上抓去——法王横出筷子快如闪电颤了几颤分点他手心手腕手背虎口中指指尖五处穴道，尼摩星手掌急翻缩回——二人瞬间已交换数招。尹克西笑嘻嘻伸筷——法王筷子被他内劲激得微微一荡，法王索性将筷子前送让他夹着劲力传到他筷上再向他手臂撞去，尹克西运劲还击却被法王以巧取胜——内劲忽发即收牛肉重又交回法王筷上。最后法王转向潇湘子——潇湘子筷子突然抢出夹住牛肉借势回夺拉回半尺，法王运劲回夺牛肉一寸一寸移回。潇湘子额头汗珠涌出强弱之势已分。",
  "事件概要": "忽必烈帐中群雄借筷争肉较技，蒙古阵营诸高手与杨过的关系由此铺开。",
  "insert": {
    "潇湘子": {
      "人物经历": {
        "神雕第十六回09-忽必烈大宴筷子争肉斗五高手": "首次在忽必烈王帐赴宴。听尼摩星出言挑战金轮法王——接口帮腔说西藏武功传自天竺可不大相信。金轮法王夹牛肉语带机锋——他不接话只与尼摩星交换眼色表示不服。最后出手与法王以牛肉较劲——筷子突然抢出夹住牛肉借势回夺拉回半尺，却被法王运劲一寸寸移回。额头汗珠涌出强弱之势已分——颓然坐下只得认输"
      },
      "关系网": {
        "杨过": "初识/20（见他年纪幼小只道是金轮法王的徒子徒孙，没放在心上。后见杨过以一指之力接住周伯通飞盘才大为惊骇不敢轻视）",
        "周伯通": "听闻名号/30（听尹克西说出老顽童名号后肃然起敬——素闻其名。但在帐中被他以矛头戏弄险些性命不保——惊骇之下忍不住脸上变色）"
      }
    },
    "尼摩星": {
      "人物经历": {
        "神雕第十六回09-忽必烈大宴筷子争肉斗五高手": "尼摩星天竺人，首赴忽必烈王帐宴。闻金轮法王为蒙古国师，不服，欲试其武。见法王以筷断马光佐之筷，即五指如爪抓肉。法王以筷点其穴，翻掌闪避，数招未分胜负，方知法王内力深厚，不敢再轻视。"
      },
      "关系网": {
        "杨过": "初识/20（见他年纪幼小只道是金轮法王徒子徒孙，更没放在心上。后见杨过以一指接住周伯通飞盘才大为震动不敢轻视）",
        "金轮法王": "不服转为重视/45（初时不信西藏武功传自天竺之说——对潇湘子接口帮腔。亲自与法王以武功较劲后不敢再小觑——法王出筷快捷无伦自己能在间不容发之际缩手避开也着实了得）"
      }
