    "日": 24,
    "时": 11
  },
  "事件引子": "你听说郭二小姐正等在芍药亭中暗自心焦之际，墙头上忽地跃下一个大头矮身的古怪人物——神雕大侠的消息终于到了。",
  "后续事件": {
    "事件名": "神雕第三十六回04-耶律齐大战蓝天和连胜群雄",
    "描述": "郭襄随大头鬼和神雕赶往大校场时，校场上耶律齐正与贵州苗人蓝天和展开一场龙争虎斗。"
  },
  "事件详情": "郭襄正在芍药亭中暗自心焦，忽听得擦的一声轻响，墙头上跃下一人——大头矮身形相甚是古怪。郭襄一见便跳起身来喜道大头鬼叔叔，他也来了么。大头鬼走进芍药亭中躬身施礼神态异常恭谨，郭襄笑道你怎地跟我这般客气。大头鬼道神雕大侠命我来跟郭姑娘说……郭襄登时眼眶便红了道大哥哥说有事不能来看我么可是他是答应过的。心中一急竟要流下泪来。大头鬼连连摇动那颗大头说不是——神雕大侠要亲自给姑娘预备三件生日礼物，是以今日要到得迟了些。郭襄破涕为笑心花怒放说已收了那么多好东西不用再费心了。大头鬼摇头说第一件已预备好啦，第二件神雕大侠正带领兄弟们办这时候多半已齐备，第三件礼物须在大校场丐帮大会中亲手交给姑娘。郭襄叹道我倒宁可他早些来别费事办礼物了。大头鬼嘘溜溜吹声口哨，墙外黑黝黝扑进一件庞然大物来——正是那头神雕。郭襄一见神雕便扑过去要揽它颈项如见久别重逢的好友一般。神雕先是傲然昂立侧首斜睨，郭襄说偏偏要你睬我便纵身而上抱住神雕头颈，终于令神雕无可奈何如庄严的父亲遇到顽皮可爱的女儿。当下大头鬼、郭襄和神雕二人一雕奔往大校场。不久黄蓉也暗中跟到，心想杨过公然要到大校场来，事先又作了周密布置，待会定要大闹一场。",
  "事件概要": "郭襄随大头鬼与神雕赴校场待收寿礼，杨过将在众目睽睽下现身贺寿的布局也随之坐实。",
  "insert": {
    "郭襄": {
      "人物经历": {
        "神雕第三十六回03-大头鬼传讯带郭襄赴校场": "在芍药亭中见大头鬼跃入大喜。听大头鬼转达杨过的话——说要亲自预备三件生日礼物所以晚到，心中先是失望流泪继而破涕为笑心花怒放。说宁可他早些来别费事办礼物。随大头鬼和神雕奔往大校场，途中抱住神雕头颈与它亲热"
      }
    },
    "大头鬼": {
      "人物经历": {
        "神雕第三十六回03-大头鬼传讯带郭襄赴校场": "奉神雕大侠之命从墙头跃入郭府后花园向郭襄传话。神态异常恭谨躬身施礼。告知杨过要亲自预备三件生日礼物——第一件已备好第二件正在办第三件须在大校场亲手交给姑娘。吹口哨唤来神雕，带郭襄奔往大校场"
      }
    },
    "神雕": {
      "人物经历": {
        "神雕第三十六回03-大头鬼传讯带郭襄赴校场": "被大头鬼口哨声唤入郭府后花园。见郭襄扑来先是傲然昂立侧首斜睨，被郭襄抱住头颈后无可奈何——如庄严的父亲遇上了又顽皮又可爱的女儿。随大头鬼和郭襄奔往大校场，途中郭襄说要请它喝酒"
      }
    },
    "黄蓉": {
      "人物经历": {
        "神雕第三十六回03-大头鬼传讯带郭襄赴校场": "在假山石后目睹大头鬼与郭襄对话和神雕现身。心中只想杨过公然要到大校场来事先又作了周密布置待会定要大闹一场。暗中跟到大校场准备应对"
      }
    }
  },
  "update": {
    "郭襄": {
