    },
    "大头鬼": {
      "所在位置": "大宋/襄阳/大校场",
      "状态": "奉神雕大侠之命带郭襄来到大校场。对丐帮知宾弟子询问冷冷回道'我没名字甚么也不懂得的郭二姑娘带我来我便来了'"
    },
    "神雕": {
      "所在位置": "大宋/襄阳/大校场",
      "状态": "随郭襄大头鬼来到大校场。躯体雄伟形相丑怪群雄无不啧啧称奇。旁人见它威猛模样谁也不敢坐近"
    },
    "黄蓉": {
      "所在位置": "大宋/襄阳/大校场",
      "状态": "暗中跟到大校场。心中只想杨过公然要到大校场来事先又作周密布置待会定要大闹一场"
    }
  },
