  "事件引子": "雁门关外狂沙漫天，宋辽数十万铁骑拔刀肃立，两军阵前杀气直冲霄汉。",
  "事件详情": "雁门关外黄沙漫天，宋辽两军数十万铁骑严阵以待，杀气直冲霄汉。面对生灵涂炭的滔天兵祸，萧峰怀揣救民水火之决绝动机，携段誉、虚竹如天降神兵般直插敌阵，施展盖世武功生擒大辽皇帝耶律洪基。在两军阵前，萧峰紧扣辽帝腕脉，厉声迫其立下“终辽帝一生绝不南侵一兵一卒”的止战誓言。耶律洪基震慑于其神威，当众折断狼羽响箭立誓退兵，但临行前厉声质问萧峰身为契丹子孙却胁迫君主，死后有何面目见列祖列宗。这番言语如万刃诛心，令萧峰在忠义难全的绝境中陷入极度撕裂。面对解救大宋万民与背叛母国大义的终极冲突，萧峰断然作出舍生取义的抉择，他俯身拾起地上折断的半截铁箭，双臂运起十成内力，反手决绝地狠狠刺入自己胸膛。滚烫热血喷涌而出染红脚下沙石，萧峰气绝倒地，随即伴着阿紫的悲哭坠入万丈深渊绝壁。辽帝依誓勒马北撤，宋辽滔天战火因这一剑而彻底熄灭，一代大侠萧峰以肉身寂灭完成了对天下苍生的最高救赎。",
  "事件概要": "萧峰携段誉、虚竹直插敌阵生擒辽帝，迫其折箭立誓永不南侵。耶律洪基依誓罢兵却当众质问其不忠不义，萧峰深陷忠义难全的绝境，断然拾起半截断箭自插胸膛舍身止战，随阿紫长眠绝壁，终熄两朝兵祸。",
  "insert": {
    "萧峰": {
      "人物经历": {
        "天龙第五十回05-萧峰舍身止战长眠雁门绝壁": "与二位义弟直插中军生擒辽帝至阵前，严词迫其折箭立誓终生不犯大宋；面对皇兄诛心叱责愧对列祖列宗之语，深感忠义难全、天地难容，决意拾起地上断箭运劲贯入胸膛舍身止战，长眠于雁门绝壁。"
      }
    },
    "段誉": {
      "人物经历": {
        "天龙第五十回05-萧峰舍身止战长眠雁门绝壁": "施展凌波微步与二哥突入万马重围生擒辽帝，助大哥迫使其折箭立誓退兵；未料大哥遭辽帝诛心质问后陷入死境，猝不及防间目睹大哥以断箭刺胸自戕，悲痛欲绝扑救不及。"
      }
    },
    "虚竹": {
      "人物经历": {
        "天龙第五十回05-萧峰舍身止战长眠雁门绝壁": "运转逍遥派绝顶武学与三弟并肩杀入敌阵俘获辽帝，交由大哥迫使其立下退兵盟誓；正喜天下苍生免遭涂炭，突见大哥在辽帝厉声责斥下决然拾箭贯胸，惊骇悲恸之下阻拦未及。"
      }
    },
    "耶律洪基": {
      "人物经历": {
        "天龙第五十回05-萧峰舍身止战长眠雁门绝壁": "两军阵前猝遭段誉、虚竹突袭生擒并受制于萧峰，震慑于其神威被迫折箭立誓永不犯宋；获释归阵后当众厉声叱骂萧峰背叛母国无颜见宗祖，未料萧峰竟当场贯胸自戕，震动惊怒之下依誓勒马班师北撤。"
      }
    },
