  },
  "事件详情": "李莫愁俏生生立于窑外，声若银铃地笑道要将两个女娃娃不论死活都抛出来，否则一把火烧了破窑。武三通急跃出洞，见她十年过去竟仍是肌肤娇嫩、宛如昔日好女，不由大感诧异。武三通见她拂尘一动，猛想起自己兵刃留在窑中，见洞边长着棵碗口粗细的栗树，当即双掌齐推将树干从中击断，横持树干叫道'李姑娘，十年不见，你好啊'。李莫愁十年未闻人唤她'李姑娘'，心中一动，少女时与陆展元的旖旎风光涌向心头，但随即想起此生孤凄全因何沅君，柔情蜜意瞬间化为无穷怨毒。她拂尘一起便往武三通头顶拂去，既快又劲。武三通左手舞动树干狂扫，右手一阳指变幻莫测难闪难挡。李莫愁忽来忽往进退如电，竟跃上树梢挥拂尘凌空下击。此后数十招中她始终如粘附在栗树上一般，顺着树干抖动之势寻隙进攻。武三通越舞越感吃力，树干沉重加上李莫愁数十斤分量，自己却打她不着，只得奋力将树干越舞越急，欲以猛转之势将她甩下树来，却始终不能如愿。",
  "事件概要": "李莫愁追到破窑，武三通与她正面开战，众人藏身之处彻底暴露，再无安稳转圜余地。",
  "insert": {
    "武三通": {
      "人物经历": {
        "神雕第二回02-李莫愁追至窑外武三通断树迎战": "跃出窑洞见李莫愁俏立当地，惊异她十年不见仍是年轻貌美。双掌击断碗口粗细的栗树横持为兵刃，仍以旧日称呼叫她'李姑娘'。李莫愁拂尘攻来，武三通左手舞树狂扫、右手一阳指护身，二人激斗数十回合。李莫愁跃上树梢如影附形，武三通渐感吃力，奋力猛转树干欲将她甩下"
      }
    },
    "李莫愁": {
      "人物经历": {
        "神雕第二回02-李莫愁追至窑外武三通断树迎战": "追踪至破窑外，声若银铃地威胁要烧窑杀女。见武三通出洞，微笑赞他'好力气'。因武三通仍以'李姑娘'旧日称呼唤她，少女时的温馨旖旎涌向心头，随即想起被何沅君夺爱之恨，柔情化为怨毒。拂尘疾攻武三通，施展轻功跃上栗树树梢，如粘附树上一般随树干抖动寻隙进攻，占尽上风"
      }
