  },
  "事件引子": "恶客遁走后的小镜湖竹舍复归宁静，堂内备下薄酒款待恩公，酒气微醺间却暗伏机锋。",
  "事件详情": "段延庆与云中鹤败退逃离后，段正淳与阮星竹对乔峰在危难关头施以援手的救命之恩感激涕零，双双躬身向乔峰再三拜谢，并盛情相邀乔峰进入竹舍设宴叙谈。竹舍酒席之上，众人推杯换盏，但乔峰心中始终记挂着为父母报仇的大事，意图借机查证段正淳是否正是当年的带头大哥。乔峰目光如炬，紧紧盯着段正淳出言试探道：“段王爷，三十年前雁门关外，有一件血海深仇之事，不知王爷可还记得？”段正淳生平风流多情、在外欠下诸多情债，骤然听闻三十年前之问，浑然没有联想到雁门关的辽宋血案，反而误以为乔峰所指乃是自己年轻时在江南欠下的风流孽债——即当年遗弃阮星竹致使私生女阿朱与阿紫流落民间的旧事。段正淳心中大感惭愧与痛悔，长叹一声后沉痛低头坦承道：“当年造下的孽债，段某自知罪孽深重，无颜以对，悔之晚矣！”段正淳的痛切悔过，令乔峰彻底认定义父生母之死正是段正淳一手铸成，致命的冤仇误解就此无可挽回地形成。",
  "事件概要": "段正淳与阮星竹设宴叩谢乔峰退敌解危之恩。席间乔峰借三十年前旧案出言试探，段正淳误将雁门关惨案当作当年遗弃阮星竹与骨肉的风流情孽，沉痛认罪自责。乔峰闻言彻底坐实其带头大哥身份，致命仇怨无可挽回地铸成。",
  "insert": {
    "乔峰": {
      "人物经历": {
        "天龙第二十一回05-乔峰竹舍试探引段正淳误认": "受段氏夫妇设席拜谢入舍对饮，借机出言追问三十年前雁门关旧事以试虚实；见段正淳神色痛悔低头认罪、自承罪孽深重无颜以对，心头悲愤激荡，彻底认定义父生母惨死实为此人一手铸成。"
      }
    },
    "段正淳": {
      "人物经历": {
        "天龙第二十一回05-乔峰竹舍试探引段正淳误认": "与阿阮在竹舍备酒盛情款待救命恩公，推杯换盏间骤闻乔峰问及三十年前之事，误以为是指当年在江南辜负阿阮、致使亲生骨肉流落的风流孽债；惭愧悔恨之下当场垂首坦承罪愆，全然不知对方所指乃是雁门关血仇。"
      }
    },
    "阮星竹": {
      "人物经历": {
        "天龙第二十一回05-乔峰竹舍试探引段正淳误认": "随段郎在舍中摆酒叩谢豪侠援手解围之恩，席间听闻恩公突提三十年前旧事逼得段郎痛切忏悔当年风流负心之过，心中幽怨怜惜交加，浑未料到推杯换盏间已埋下滔天杀机。"
      }
    }
  },
  "update": {},
