      }
    },
    "段誉": {
      "人物经历": {
        "天龙第三十回08-少室山三侠力克强敌威震武林": "击溃慕容复后踏步回到大雄宝殿台阶前，与萧大哥、虚竹二哥并肩而立，见大哥昂藏神威喝退各派群雄，满腔热血激荡，深感三兄弟金兰同心足以不惧天下强敌。"
      }
    },
    "玄慈": {
      "人物经历": {
        "天龙第三十回08-少室山三侠力克强敌威震武林": "立于大殿前目睹萧峰三兄弟各挫强敌、金兰并肩之盖世神威，见其一声断喝令数千群雄骇然后退，深知大势已定，遂合十长叹一声以化解干戈，冷眼静观少室山杀局消散。"
      }
    },
    "慕容复": {
