      }
    },
    "鸠摩智": {
      "人物经历": {
        "天龙第十二回02-阿朱易容老仆瞒过番僧": "端坐主位静候设席，见一名慕容氏老仆身形佝偻、颤巍端茶入内奉奉，语声沙哑迟暮且毫无内家真气迹象，自忖不过一介凡俗老迈仆役，浑未识破其乃先前红裳少女假扮。"
      }
    },
    "段誉": {
      "人物经历": {
        "天龙第十二回02-阿朱易容老仆瞒过番僧": "身受要穴禁锢端坐席间，见一名白发苍苍、神态衰朽的老仆步履蹒跚入内端茶侍奉，全未辨出其神形步态之下竟是方才离席的红裳少女所化。"
      }
    }
  },
  "update": {},
  "后续事件": {
    "天龙第十二回03-阿朱席间奉茶暗解穴道": "阿朱以老仆身份侍立席旁，正待借递盏斟茶之机靠近受制的段誉暗施援手。"
