      }
    },
    "耶律涅鲁古": {
      "人物经历": {
        "天龙第二十五回02-叛军突袭伏击围困辽帝": "依密谋率数百死士伏击猎场，下令强弓药箭连环齐射全歼辽帝近卫，见堂兄坠马中箭重创，遂命死士持毒刃踏雪合围，欲毕其功于一役将其诛杀。"
      }
    }
  },
  "update": {
