  },
  "事件结束时间": {
    "年": 1238,
    "月": 8,
    "日": 17,
    "时": 1
  },
  "事件引子": "中夜，杨过趁柯镇恶熟睡悄悄溜出客店，赶往七八里外铁枪庙探望重伤的欧阳锋；欧阳锋断定柯镇恶迟早会循迹而来。",
  "后续事件": {
    "事件名": "神雕第二回14-柯镇恶中毒返店决心东行桃花岛",
    "描述": "杨过赶回客店，次日清晨柯镇恶双手乌黑中毒归来，众人决定乘船东行前往桃花岛"
  },
  "事件详情": "杨过与柯镇恶同睡一房到得中夜悄悄起身，听得柯镇恶鼾声如雷睡得正沉，打开房门溜出墙外，用预先藏好的肉骨头止住狗吠，辨明方向向西南行七八里来到铁枪庙前。推开庙门大叫'爸爸，我来啦！'只听欧阳锋哼了一声——他躺在神像前的蒲团之上神情委顿呼吸微弱，与郭靖所受之伤相若却因年迈精力远不如。杨过从怀里取出七八个馒头递上，欧阳锋吃后精神一振。原来欧阳锋昨夜去而复返探视杨过时被柯镇恶察觉引发大战，杨过在混乱中悄悄随欧阳锋而去，初时追赶不上，后欧阳锋伤势发作步履艰难被杨过赶上扶他在道旁休息。杨过怕不回客店黄蓉等人会来找寻反累义父，与欧阳锋约定了在铁枪庙会面后独自守在大路旁与郭靖等会合，到半夜方来探视。欧阳锋道姓郭的七日之内难以复原，黄蓉要照料丈夫不敢轻离，眼下只担心柯镇恶一人——他今晚不来明日必至。杨过小脑袋转了许多念头，在供桌上取过四只烛台拔去残烛放在门口，又搬了一只铁香炉爬上去放在庙门顶上。他四下察看见东西偏殿各吊着一口三人合抱也抱不起来的千斤大铁钟，心想可在钟架上躲避。正在此时笃笃笃的铁杖击地声传来——柯镇恶果然到了。杨过忙吹灭烛火，守在欧阳锋身旁要跟老瞎子拼上一拼。柯镇恶撞开庙门，头顶铁香炉砸下，同时左脚踏中烛台铁扦刺破靴底脚心剧痛。他铁杖挥起打飞香炉在地下一滚，肩头又被另一只烛台铁扦刺入肉里，鲜血立涌。柯镇恶听准欧阳锋呼吸之声踏步向前，要等他先行发招再判断他伤势轻重。两人相对僵持，柯镇恶耳听沉重呼吸脑中顿现结义兄弟声音似在齐声催他下手，大吼一声挥杖盖下。欧阳锋气息不济伸出的手臂软垂，只得以打滚躲避。柯镇恶使开降魔杖法一招快似一招，接连三杖都击在欧阳锋身上，虽被卸去九成劲道仍打得他皮开肉绽。欧阳锋行险扑入柯镇恶怀里抓住胸口肉搏，抽出柯镇恶腰间屠牛刀刺去却被一拳打翻，迷糊中挥手将尖刀掷出——当的一声嗡响竟刺入殿上铁钟。杨过站在钟旁险些被刺中脸颊，急忙爬上钟架以刀柄撞钟掩盖两人呼吸声。柯镇恶辨不清方位挥杖不住击钟，前声未绝后声又起。欧阳锋想趁机从后殿溜出却被柯镇恶灵敏耳力分辨出来。二人绕着铁钟兜圈子，杨过见义父气力不加，心生一计——先掷鞋诱柯镇恶分心，随即持屠牛刀猛砍吊钟横梁。数刀急砍之下横梁吃不住巨钟重量折断，千斤大铁钟夹着疾风对准柯镇恶顶门直砸下来。柯镇恶百忙中铁杖直竖撑住钟边乘隙滚出，但铁杖断为两截，铁钟在肩头猛力一撞将他抛出山门跌得头破血流。柯镇恶不明变故以为殿中躲着怪物，爬起来一跷一拐地走了。杨过从钟架上爬下大喜，但欧阳锋知道柯镇恶必定再来。杨过依计将欧阳锋安置在另一口大钟之下——先放了盆清水和馒头，再斩断横梁让铁钟落下将欧阳锋罩住。欧阳锋将在钟下用功七日元功一复就能自己掀钟出来。杨过又将另一口钟用血毒涂遍以防柯镇恶触摸中毒。用断刀在钟边挖了个通气孔，伏在地下对准洞孔与欧阳锋道别。欧阳锋微弱声音道'好孩子，我不怕毒，毒才怕我。你自己小心，我定来接你'。杨过悄立半晌恋恋不舍，这才快步奔回客店。",
  "事件概要": "杨过夜赴铁枪庙智助欧阳锋退柯镇恶，彻底暴露自己偏向义父，也与柯镇恶结下新怨。",
  "insert": {
    "杨过": {
      "人物经历": {
        "神雕第二回13-杨过铁枪庙智助欧阳锋退柯镇恶": "杨过半夜溜出客店，以肉骨头止住狗吠，赴铁枪庙给义父欧阳锋送馒头。他巧布陷阱，用烛台、香炉伤柯镇恶，又爬上钟架撞钟掩护义父，更掷鞋诱敌、刀砍横梁以巨钟砸伤柯镇恶，逼其头破血流逃走。事后将欧阳锋罩入钟内，备下清水馒头、涂毒防柯、通气防闷，临别恋恋不舍而去。"
      }
    },
    "柯镇恶": {
      "人物经历": {
        "神雕第二回13-杨过铁枪庙智助欧阳锋退柯镇恶": "柯镇恶夜半寻仇铁枪庙，中杨过连环陷阱，脚心被烛扦刺破，头肩被香炉砸中，肩头又中一扦鲜血直流。他以降魔杖法连击欧阳锋却劲力被卸，搏斗中打翻刺刀的欧阳锋。追击绕钟时杨过机关断横梁，千斤巨钟砸下，他铁杖断为两截，被钟撞出山门，头破血淋，以为怪物作祟，一跷一拐而去。"
      }
    },
    "欧阳锋": {
      "人物经历": {
        "神雕第二回13-杨过铁枪庙智助欧阳锋退柯镇恶": "欧阳锋与郭靖两败俱伤躲入铁枪庙，杨过携馒头夜探。柯镇恶寻仇，欧阳锋欲同归于尽却气息不接，遭三杖皮开肉绽，屠牛刀被击飞。后依杨过计藏千斤铁钟下，备清水馒头运功七日自复元。"
      }
    }
  },
