  "事件引子": "雁门关前朔风呼啸，古道苍凉肃杀，万丈绝壁如刀削般壁立千仞。",
  "事件详情": "雁门关前，朔风呼啸，天地肃杀，入目皆是古道的苍凉与衰败。乔峰步履沉重地踏着碎石黄土，悄然肃立于当年父母饮恨殉难的万丈绝壁之下。面对眼前高耸入云、险峻如刀削般的悬崖峭壁，乔峰心中泛起无限伤感与酸楚。他缓缓仰望险峰，双目凝视着石壁上那块显眼的平滑之处——那正是当年父亲留下的契丹遗书被中原武人以利刃硬生生刮去字迹的地方。乔峰情难自禁，缓缓抬起颤抖的右手，以指掌轻柔抚摸着冰冷粗粝的平滑石壁，指尖摩挲着刀刮斧削的斑驳痕迹。三十年前那场惨绝人寰的伏击血案、母亲惨死的哀嚎以及父母双亡的凄楚命运，如惊涛骇浪般在乔峰脑海中翻涌激荡，令他心潮剧烈起伏。面对这片被岁月抹去文字却抹不掉血泪的绝壁，乔峰悲从中来，虎目含悲，独自承受着父母惨逝的无尽凄凉与身世凄迷的巨创。狂风卷起他的衣袍，乔峰在绝壁之下久久伫立沉浸于极度的哀思与祭奠之中，形成了对当年惨烈旧事的深切缅怀。",
  "事件概要": "乔峰重返雁门关绝壁之下，仰望生父当年所留遗书被削平的石壁。他以指掌摩挲粗粝刀痕，念及父母惨死与身世巨变，在呼啸寒风中悲从中来，久久伫立缅怀当年惨案。",
  "insert": {
    "乔峰": {
      "人物经历": {
        "天龙第二十六回02-乔峰抚摩绝壁旧痕悲从中来": "肃立于雁门关绝壁之下，仰望当年生父留下遗书却被中原武人刮平的石壁；抬手轻抚冰冷粗粝的刀刮旧痕，忆及生母惨嚎与父母殉难之痛，虎目含悲迎风伫立，满心皆是身世凄迷的巨创与哀思。"
      }
    }
  },
  "update": {},
  "后续事件": {
    "天龙第二十六回03-乔峰隐伏山石目睹辽兵屠戮": "乔峰在绝壁下缅怀旧事方毕，忽闻关外马蹄杂沓、隐隐传来兵戈杀戮之声，遂敛息隐伏于山石后探查动静。"
  },
  "参与人物": [
    "乔峰"
  ]
}

