428682.content:
{
  "事件地点": "大宋/大胜关/大胜关郊野/树林",
  "触发条件": {
    "类型": "时间",
    "年": 1244,
    "月": 11,
    "日": 2,
    "时": 8
  },
  "事件结束时间": {
    "年": 1244,
    "月": 11,
    "日": 2,
    "时": 9
  },
  "事件引子": "你听说大胜关树林中一场恶斗尚未结束，一个青衫少女突然现身，竟懂得桃花岛的奇门阵法...",
  "后续事件": {
    "事件名": "神雕第十五回02-程英茅屋照料杨过暗露心事",
    "描述": "程英将重伤的杨过带回荒山茅屋悉心照料，杨过在昏迷中将她错认为小龙女"
  },
  "事件详情": "石阵之中，金轮法王被巨石撞中背心，摇晃站起后脸色惨白仰天凄笑，伸出大手便往黄蓉背上抓去。杨过被掌力震伤胸臆趴在地上无力站起，仍横棒挥出挡开这一抓，却喷出一口鲜血。郭芙手提长剑护在母亲身前，金轮法王铁轮微摆撞飞其长剑。正当法王要推开郭芙去拿黄蓉的危急关头，林中跃出一个面目可怖的青衫人影，伸手接住半空落下的长剑，三个起伏已奔到乱石堆中。这女子相貌虽丑声音却甚是娇嫩，自称'无名幼女'，俯身推动岩石挡在法王与黄蓉之间。她口中连喝二十八宿方位——'角木蛟变亢金龙'、'心月狐转房日兔'、'毕月乌移奎木狼'、'女土蝠进室火猪'，叫得头头是道与黄蓉主持阵法时一般无异。郭芙与二武大喜，奋力移动岩石，眼见又要将金轮法王困住。法王背上内伤着实不轻，无力再起脚挑石，铁轮虚晃吓退武修文后缓步退出石阵。他呆立半晌心中思潮起伏：'难道老天当真护佑大宋，教我大事不成？'抚胸长叹转头便走，走出十余步铁轮落地身子摇晃。达尔巴大惊抢上扶住，将师父托上马背，一行人向东而去。青衫少女缓步走到杨过身旁，弯腰察看伤势，夜色已深她直凑到杨过脸边。杨过昏迷中见一对温柔怜惜的目光，只当是小龙女，当即张臂抱住她身子叫道：'姑姑，过儿受了伤，你别走开了不理我。'那少女又羞又急，微微一挣杨过胸口剧痛不禁'啊唷'一声。那少女不敢强挣，柔声解释不是他姑姑。杨过凝视她眼睛不住哀求，突然间神志清明惊觉眼前之人并非小龙女，失望已极便昏了过去。那少女见他伤势极重，扶着他后腰半拖半拉走出石阵，又慢慢走出林外。瘦马甚有灵性奔近身来，少女将杨过扶上马背，却不与他同乘，牵了马缰步行而去。",
  "事件概要": "程英在石阵中救下重伤杨过，使他暂脱追杀，也把自己重新卷入这场旧缘。",
  "insert": {
    "程英": {
      "人物经历": {
        "神雕第十五回01-程英石阵现身救杨过": "程英寻外出不归的陆无双，遇黄蓉布乱石阵斗金轮法王。她随黄药师学过阵法，接住郭芙长剑喝令二十八宿方位变阵，逼退法王。察杨过伤时被他抱持误作小龙女。后扶他上瘦马，牵回荒山茅屋救治。"
      }
    }
  },
  "update": {
    "杨过": {
      "所在位置": "大宋/襄汉之间/荒山区域/茅舍",
      "状态": "重伤昏迷（先被金轮法王一掌击飞胸臆受伤，又勉力挥棒格开法王抓向黄蓉之手导致大口喷血。昏迷中将程英误认为小龙女，抱住她哀求别走。神志短暂清明后彻底昏了过去。被程英扶上瘦马带回茅屋）",
      "人物经历": {
        "神雕第十五回01-程英石阵现身救杨过": "与黄蓉法王三人同时受伤倒地——最后一幕是被金轮法王一掌击飞"
      },
      "关系网": {
        "程英": "救命恩人/70（长安道上示警、客店盗驴引开李莫愁、武关玉箫挡拂尘——如今又在石阵中现身逼退金轮法王，将自己从鬼门关前救了回来。这是他第四次受程英之恩，感激无尽）"
      }
    },
    "金轮法王": {
      "状态": "重伤东归（背上被巨石撞中内伤着实不轻，强运内力护住一时虽不发作实则已无力再战。铁轮虚晃吓退武修文后缓步退出石阵，走出十余步铁轮落地身子摇晃，已无力上马靠达尔巴托腰送上马背。心中思潮起伏感慨天佑大宋中原武林英才辈出。一行人向东而去）"
    },
    "达尔巴": {
