        "天龙第四十一回07-两代高手一路搏杀转战藏经阁": "深知平地硬拼久战难敌萧氏父子，遂虚晃一指逼退萧峰，携复儿提气急遁后山并破窗撞入藏经阁，借幽闭狭室与纵横书架周旋死斗。"
      }
    },
    "慕容复": {
      "人物经历": {
        "天龙第四十一回07-两代高手一路搏杀转战藏经阁": "在萧远山压迫下险象环生，趁父亲逼退萧峰之机全力施展轻功跟随后山，破门撞进藏经阁内，背水一战拔剑与二萧在乱卷飞舞中拼死搏杀。"
      }
    },
    "萧远山": {
      "人物经历": {
