    "时": 12
  },
  "事件结束时间": {
    "年": 1245,
    "月": 2,
    "日": 2,
    "时": 13
  },
  "事件引子": "裘千尺命人打开大厅铁门——八名弟子提着渔网护卫。大厅中一灯黄蓉武三通耶律齐诸人都坐在一角静候。裘千尺待椅子着地举手说道这里除了黄蓉母女三人其余一概不究给我走罢。",
  "后续事件": {
    "事件名": "神雕第三十一回08-公孙止从天而降夺走丹药杨过破门而入",
    "描述": "绿萼双手捧着瓷瓶走向黄蓉——正要递到时屋顶突然破裂一人从空跃落夺走瓷瓶。杨过等人也在这时破门而入。"
  },
  "事件详情": "裘千尺带绿萼重回大厅命开铁门——八名弟子提着渔网左右护卫。黄蓉鉴貌辨色见裘千尺眉间隐有重忧——料想谷中或有内变便出言试探。黄蓉提出交易：不避不让任裘千尺连打三枚枣核钉——不论死活都须赐赠解药救杨过，自己若死了朋友们仍然助她退内敌。郭芙急忙阻拦说妈怎可不用兵器格打——黄蓉微笑说不必。裘千尺心想这等便宜事太过不近人情——但黄蓉低声告知内敌将至双方须并肩应敌。裘千尺虽心中一动但善念一瞬即过——冷冷的道任你百般花言巧语老妇人铁石心肠不改初衷。黄蓉衣袖一拂站到大厅正中距裘千尺三丈——说来罢。第一枚枣核钉疾射黄蓉小腹——悍猛无伦破空如尖啸。黄蓉早将郭芙断剑剑头藏在衣袖之中——弯臂以剑头挡住发出轻微金铁之声被一声大叫掩盖过去。第二枚射向胸口同样以袖中剑头挡住假装摇摇晃晃。裘千尺见黄蓉中两钉居然不倒心下骇然——第三枚射向咽喉要使铁钉透喉而过。黄蓉双膝微曲张口运气喷出一股真气欲减弱枣核钉来势——功力不如裘千尺深厚铁钉来势只略略一缓。千钧一发之际张口急咬硬生生将铁钉咬住——震得满口牙齿生疼满口流血倒退两步。一仰头波的一声将枣核钉喷入横梁。裘千尺叹服黄蓉气概——答应依言给药但要绿萼来取。黄蓉在全神贯注间忽听一灯口诵佛号夹带密语——原来一灯以天耳通将裘千尺对绿萼的耳语全数听去并用佛号传达给黄蓉。裘千尺让绿萼揭开第五块青砖——砖下有两瓶，她低声命绿萼取西首假药给黄蓉，东首藏真药。绿萼心中已决定舍命取真药救杨过——伸手在砖底泥中一掏果有两瓶并列，摸了东首瓷瓶出来。裘千尺以为绿萼取出的是西首假药——道咱们信守诺言丹药交给郭夫人。绿萼双手捧着瓷瓶走向黄蓉——心中酸楚暗道杨郎啊杨郎今日我舍却性命取真药给你这番苦心你未必知道罢。",
  "事件概要": "黄蓉以硬受三枚枣核钉的代价换得交药之机，一灯识破裘千尺调包，公孙绿萼也已将真正的绝情丹递向黄蓉。",
  "insert": {
    "黄蓉": {
      "人物经历": {
        "神雕第三十一回07-黄蓉受三枚枣核钉换取绝情丹一灯识破假药绿萼换真药": "黄蓉为取绝情丹受裘千尺三枚枣核钉，袖中剑挡两枚，第三枚张口咬住，满口出血，裘千尺叹服给药。一灯以天耳通告之东真西假，黄蓉借问伤势听全密语，凭智慧勇气换得生机。"
      }
    },
    "裘千尺": {
      "人物经历": {
        "神雕第三十一回07-黄蓉受三枚枣核钉换取绝情丹一灯识破假药绿萼换真药": "黄蓉甘受三枚枣核钉换解药，裘千尺疑诈，仍冷拒。三钉射出，黄蓉中而不倒，末钉咬住喷入横梁，裘千尺服其气概，允给药，命绿萼揭第五块青砖取药，又密嘱取西首假药，不知一灯天耳通听去告黄蓉。"
      }
    },
    "公孙绿萼": {
      "人物经历": {
        "神雕第三十一回07-黄蓉受三枚枣核钉换取绝情丹一灯识破假药绿萼换真药": "公孙绿萼奉母命以匕首撬开青砖取药，母密嘱东真西假、命取西首假药与黄蓉。她为杨过暗取东首真药，双手捧与黄蓉。黄蓉见她望杨过深情焦虑，恍然其所递乃真药。"
      }
    },
    "一灯大师": {
      "人物经历": {
        "神雕第三十一回07-黄蓉受三枚枣核钉换取绝情丹一灯识破假药绿萼换真药": "在大厅屋角闭目静坐——数十年潜修耳聪目明远胜常人。以天耳通将裘千尺对绿萼的耳语一字不漏听去——知道砖下有两瓶东首真药西首假药，裘千尺命女儿取西首假药给黄蓉。佛家有救人之德岂能见死不救——口诵佛号时将机密夹在佛号之中传递给黄蓉。黄蓉借询问伤势为掩护听全了密语"
      }
    },
    "郭芙": {
      "人物经历": {
        "神雕第三十一回07-黄蓉受三枚枣核钉换取绝情丹一灯识破假药绿萼换真药": "阻拦母亲不让她不避不让受枣核钉——说适才长剑被枣核钉击断知道这暗器力道强劲无比，不肯让血肉之躯去抵挡。黄蓉微笑拒绝后——郭芙过去拉母亲衣袖说穿上软猬甲就不怕了。黄蓉坚持不用后只得退在一旁——见母亲以袖中剑头挡住两钉方才明白。见母亲满口流血急急上前询问伤势"
      }
    }
  },
