  "事件引子": "万仞冰崖绝顶寒风怒号，泛黄画卷散落雪泊，两位龙钟宗师气息奄奄，肃杀悲凉笼罩风雪绝壁。",
  "事件详情": "残酷的情感真相如惊雷般彻底粉碎了二人苦守一生的痴念，天山童姥抓着那幅滑落雪中的泛黄画卷，神情状若疯癫。她用尽残存的全部生命力，仰首对着呼啸的风雪苍穹发出一阵阵凄厉、苍凉而又绝望至极的癫狂大笑，声音在空旷的冰谷间回荡不绝：“不是她！不是她！哈哈，原来不是她！”在这一连三声声嘶力竭的狂笑悲呼中，童姥周身气机骤绝，一口气未能提上来，当场仰面栽倒气绝身亡。李秋水亲眼看着死去的宿敌与那幅浸染风雪的画像，心中翻江倒海的怨毒与仇恨刹那间化作无尽的空虚与悲凉。两行浑浊的泪水顺着她干瘪的面颊滚滚滑落，李秋水凄然长叹道：“争了一辈子，恨了一辈子，到头来竟是这般下场……”李秋水心结彻底消解，眼中的执念尽数化为坦然与释怀。李秋水颤巍巍地双手合十于胸前，向着身旁的虚竹微微点头示谢，随即缓缓阖上双目，溘然长逝随童姥而去。至此，名震武林近百载的两位逍遥派绝世宗师同归于尽，双双魂断缥缈峰冰崖之上。",
  "事件概要": "天山童姥惊悉无崖子毕生挚爱非李秋水，极度绝望下向苍穹连声狂呼“不是她”，真气断绝气绝身亡；李秋水目睹宿敌暴毙与画卷真相，一生执念与怨毒化为乌有，凄然长叹释怀心结，合十向虚竹致谢后安然阖目长逝。名震天下的逍遥二宗同归于尽，双双魂断冰崖。",
  "insert": {
    "虚竹": {
      "人物经历": {
        "天龙第三十五回06-大笑悲叹二宗同归于尽冰崖": "亲眼目睹童姥死死攥着雪中画卷发出凄厉癫狂的大笑，高呼‘不是她’后当场仰面气绝；又见李师叔滚落浑浊泪水长叹恩怨皆空，合十向自己点头致谢后亦溘然阖目长逝，面对二位长辈瞬间双双毙命冰崖，心中悲悯震撼难言。"
      }
    },
    "天山童姥": {
      "人物经历": {
        "天龙第三十五回06-大笑悲叹二宗同归于尽冰崖": "紧抓滑落雪中的泛黄画卷陷入癫狂，用尽周身残存精血仰首对天风凄厉狂笑，连声悲呼‘不是她！哈哈，原来不是她！’，胸中一口气未能提上来，气机骤绝，仰面栽倒魂断冰崖。"
      }
    },
    "李秋水": {
      "人物经历": {
        "天龙第三十五回06-大笑悲叹二宗同归于尽冰崖": "亲睹宿敌狂笑毙命与雪中画卷，心头积聚数十年的怨毒瞬化为空虚悲凉，老泪纵横长叹一生相争尽付流水；心结顿解之下合十向虚竹微微致意，平静释怀地合上双目溘然长逝。"
      }
    }
  },
  "update": {
