  "事件详情": "杏子林中微风拂动，草木萧萧，数百名丐帮弟子与各路中原武林豪杰屏息肃立，四周气氛凝重压抑。马夫人康敏一身缟素白衣，显得分外凄楚柔弱，她眼含泪水、面带悲容，当着在场所有武林同道之面，缓步走至场中。为了将潜藏多年的帮门绝密彻底公之于众，康敏当众从怀中取出一封前任帮主汪剑通临终前亲笔写就的绝密遗书。这封信函封存多年，系汪帮主生前最为机密与慎重的交代，关乎整个中原武林的安危与丐帮根基。在全场群雄惊疑不定的目光注视下，康敏双手捧着信笺，迈步走到丐帮秉公执法的执法长老白世镜面前，神情凄切地将遗书郑重交予白世镜手中，恳请其当众主持公道。白世镜神色凝重地伸出双手接下遗书，绝密信件正式完成流转，杏子林内群豪无不屏气凝神，一场震动天下的身世风暴随之拉开序幕。",
  "事件概要": "马夫人康敏身披缟素走至场中，在群雄注视下从怀中取出前任帮主汪剑通生前封存的绝密遗书，凄然恳请秉公裁决。执法长老白世镜神情凝重当众接下遗书，丐帮尘封多年的身世隐秘与帮门剧变由此拉开序幕。",
  "insert": {
    "康敏": {
      "人物经历": {
        "天龙第十六回01-康敏当众出示汪帮主绝密遗书": "缟素垂泪步入林中，当着众豪杰之面自怀中取出先帮主汪剑通的绝密遗书，悲凄交加地递予执法长老白世镜，恳请其秉公彻查先夫死因与帮门隐秘。"
      }
    },
    "白世镜": {
      "重要物品": {
        "汪剑通绝密遗书": "前帮主汪剑通临终亲笔绝密信函，密封多年关乎丐帮根本与隐秘"
      },
      "人物经历": {
        "天龙第十六回01-康敏当众出示汪帮主绝密遗书": "见马夫人悲戚走近并出示汪帮主生前所留绝密手书，在全场群雄逼视下深吸一口气，肃然伸手将信件接下以待公议。"
      }
    }
  },
