  "事件引子": "少林广场一侧阴风呼啸、寒霜遍地，游坦之嘶吼如狂，挥起冰蚕毒掌直扑萧峰。",
  "事件详情": "少室山前另一侧，萧峰独身迎战丐帮帮主庄聚贤（游坦之）。游坦之满腔仇恨混杂着对阿紫的畸恋，双目赤红，运起融合了少林《易筋经》与千年冰蚕奇毒的阴寒内劲。他疯狂嘶吼着连环挥出“冰蚕神掌”，惨白冰雾所过之处，脚下青砖尽皆凝结出寸厚冰霜，刺骨毒冻如排山倒海般直逼萧峰要害。面对这等至阴邪异的狂暴攻势，萧峰神色冷峻毫无惧意，丹田真气如烈火沸腾，将“降龙十八掌”催动至十成巅峰。伴随着震彻天际的嘹亮龙吟，萧峰双掌沉稳推出，至刚至阳的正道掌力如惊涛骇浪般正面迎向冰蚕极寒。阴阳两股绝顶内劲在半空中轰然对撼，气浪炸裂如春雷炸响，狂暴劲风将四周巨石生生掀飞。游坦之武功招式浅薄，终究敌不过萧峰身经百战的浑厚内力，护体寒劲在层层叠叠的纯阳掌风逼压下迅速瓦解崩溃。萧峰抓住破绽当头一掌刚猛压落，雄浑掌力透体而下，只听得两声清脆刺耳的骨裂声，游坦之双腿腿骨被当场生生震断。游坦之狂喷鲜血惨叫扑地，骨断筋折彻底瘫痪落败。",
  "事件概要": "游坦之挟仇恨与畸恋狂催千年冰蚕阴寒毒劲，双掌激荡惨白冰霜猛攻萧峰。萧峰凛然不惧，将降龙十八掌催至十成巅峰正面迎撼，至刚阳劲瞬间震碎极寒气浪并当头压落，生生震断游坦之双腿腿骨，令其吐血扑地彻底瘫痪溃败。",
  "insert": {
    "萧峰": {
      "人物经历": {
        "天龙第三十回07-萧峰运降龙神掌震断游坦之双腿": "面对庄聚贤裹挟至阴奇毒的冰蚕神掌，毫无惧色运起十成降龙掌力正面迎击，以至刚至阳的龙吟掌风彻底震溃其阴寒护体真气；旋即看准破绽当头猛压，浑厚掌力透体而下当场将其双腿腿骨震断，干脆利落击溃强敌。"
      }
    },
    "游坦之": {
      "人物经历": {
        "天龙第三十回07-萧峰运降龙神掌震断游坦之双腿": "满腔仇恨混杂着夺回阿紫的痴念，双目赤红狂运冰蚕神掌连环猛攻，不料萧峰十成降龙掌力刚猛无匹，护体寒劲瞬间被纯阳掌风层层撕裂摧垮；当头雄浑掌力透体压落，双腿腿骨应声生生折断，狂喷鲜血瘫倒在青霜残石间彻底溃败。"
      }
    }
  },
  "update": {
    "游坦之": {
      "状态": "重伤（双腿骨折）"
    }
  },
  "后续事件": {
    "天龙第三十回08-少室山三侠力克强敌威震武林": "庄聚贤双腿折断瘫地溃败，少林山门前战端未歇，虚竹与段誉亦各自挺身迎战宿敌。"
  },
  "参与人物": [
    "萧峰",
    "游坦之"
  ]
}

