{
  "事件地点": "大宋/豫鄂/荒野区域/破庙",
  "触发条件": {
    "类型": "时间",
    "年": 1244,
    "月": 10,
    "日": 20,
    "时": 8
  },
  "事件结束时间": {
    "年": 1244,
    "月": 10,
    "日": 20,
    "时": 9
  },
  "事件引子": "杨过行到正午一路上不断遇见化子，不少都身负武功，心下琢磨丐帮之事...",
  "后续事件": {
    "事件名": "神雕第十一回08-王十三引杨过大胜关陆家庄英雄大宴",
    "描述": "次日王十三招呼杨过一同上路赴大胜关陆家庄英雄大宴"
  },
  "事件详情": "杨过行到正午一路上不断遇见化子，瞧那些人的模样不少都是身负武功。他对丐帮本无好感，但因钦佩洪七公不自禁对丐帮有了亲近之意。行到申牌时分忽听空中雕鸣啾啾两头白雕飞掠而过，听得化子说'黄帮主到啦'又提郭大侠。杨过听到郭靖与黄蓉的名字微微一惊，随即心下冷笑：'从前我在你家吃闲饭给你们轻贱戏弄，那时我年幼无能吃了不少苦头。此刻我以天下为家还倚靠你们什么？'心念一转：'不如装作潦倒不堪前去投靠，且瞧他们如何待我。'于是寻了一个僻静所在将头发扯得稀乱，在左眼上重重打了一拳面颊上抓了几把——左眼登时青肿脸上多了几条血痕。他本就衣衫不整，更把衣裤撕得七零八落在泥尘中打了几个滚，配上这匹满身癞疮的丑马，果然是一副穷途末路奄奄欲毙的模样。来到一座破旧大庙前只见两头白雕栖息在庙前松树上——武氏兄弟一个托盘子另一个抓起肉块抛上去喂雕。杨过见武敦儒神色剽悍举手投足精神十足，武修文则轻捷灵动没一刻安静，果然是英雄年少人才出众。杨过上前打了一个躬结结巴巴道：'两两位武兄请了，别来别来安好。'武敦儒还了一礼却认他不出。忽听庙门口一个银铃似的声音叫武敦儒买马鞭——杨过转头只见一个少女穿着淡绿衫子从庙里快步而出，双眉弯弯脸如白玉颜若朝华，正是郭芙。杨过只向她瞧了一眼不由得自惭形秽便转过了头不看。武修文也即抢上哥儿俩同时尽力巴结。郭芙与武氏兄弟三人自顾说话，对坐在地下吃饭的杨过眼角也没瞥上一眼。",
  "事件概要": "杨过改装潦倒混入破庙，暗中与郭芙、武氏兄弟重逢，也为赴英雄宴埋下线头。",
  "update": {
    "杨过": {
      "所在位置": "大宋/豫鄂/荒野区域/破庙",
      "状态": "乔装潦倒混入丐帮群中（将头发扯得稀乱、左眼打青脸抓血痕、衣衫撕得七零八落——配着癞疮丑马扮作穷途末路的叫化模样。混在数百化子中并不显眼）",
      "人物经历": {
        "神雕第十一回07-杨过乔装潦倒混入破庙逢郭芙武氏兄弟": "杨过得知郭靖黄蓉到来，忆起幼时在桃花岛被轻贱戏弄，决意乔装潦倒前去投靠试探，遂扯乱头发、打青左眼、撕烂衣衫、泥中打滚。他到破庙前见武氏兄弟喂雕、郭芙颈挂明珠光彩照人，只一眼便自惭形秽。三人自顾说话进庙，对坐地吃饭的杨过视而不见。杨过筷子插在碗中，心中百感交集。"
      },
      "性格": "聪明机灵，狡猾惫懒，自尊心极强且敏感叛逆。自幼失去父母，饱尝人世冷暖。得小龙女真心相待后对她敬爱赤诚——溪边因完颜萍眼波蓦然醒悟才真正领会姑姑对自己的一往情深，懊丧欲死更决心走遍天涯也要寻她回来今生今世不负她。重情重义，守约守信——为守洪七公三日之约宁可饿死华山也不肯失信，以尾生抱柱自励。对义父欧阳锋愈久愈亲。离开古墓后仍留恋红尘，但为小龙女甘愿隐居山谷年余。遇事机变百出。对陆无双、完颜萍的感情皆因她们与小龙女的相似而起——借相似的眼波嗔怒之色以慰对姑姑的刻骨相思。凡事要在人前逞强好胜，决意处处胜过旁人。遭遇世人轻贱时常自伤自怜，看似轻佻浮脱实则内心血性男儿——可以命守诺不畏生死，大事当头豁得出去。美食当前也敢尝天下至奇之物（如蜈蚣）。在华山窄道上以'魁星踢斗势'一夫当关时只觉英雄之气充塞胸臆——虽衣衫褴褛而豪气干云。华山二老逝后更添一层世事浮云之慨——下山时觉别人看重也好轻视也好于我又有何干系，小小年纪竟愤世嫉俗玩世不恭起来。见郭芙骄美自惭形秽——却又因被冷落而百感交集，自卑与骄傲在胸中翻滚。故意装得越是寒酸被人轻视心中越是得意。",
      "关系网": {
        "郭芙": "自卑且暗生注意/-40（在破庙初见已长成颜若春花的美貌少女——只瞧了一眼便自惭形秽转过头去。郭芙却认不出他眼角也没瞥一眼——杨过筷子插在碗中听着蹄声远去心中百感交集不知是愁是恨）",
        "武敦儒": "旧怨/-50（见其神色剽悍举手投足精神十足——身穿紫酱色锦袍腰束绣花英雄绦果然是英雄年少人才出众。武敦儒没认出他只是还礼应付）",
        "武修文": "旧怨/-50（见其轻捷灵动东奔西走没一刻安静——身穿宝蓝色绸袍腰束绣花英雄绦果然是英雄年少人才出众。武修文忙着巴结郭芙对他全然不理）"
      }
    },
    "郭芙": {
      "人物经历": {
        "神雕第十一回07-杨过乔装潦倒混入破庙逢郭芙武氏兄弟": "在破庙中出来叫武敦儒买软些的马鞭——武敦儒急忙撇下杨过迎上将鞭子递上。与武氏兄弟三人走进后院取了包裹兵刃出破庙上马而去，对坐在地下吃饭的狼狈少年（杨过）眼角也没瞥上一眼。"
      },
      "关系网": {
        "杨过": "已不识得/-30（杨过故意扮成穷困落魄之状混在数百人之中——郭芙已全不认识他。只把他当作路边陌生的潦倒化子一眼掠过）"
      }
    },
    "武敦儒": {
      "人物经历": {
        "神雕第十一回07-杨过乔装潦倒混入破庙逢郭芙武氏兄弟": "在破庙前与弟弟武修文一个托盘子一个抓肉块抛喂双雕。杨过上前打躬结结巴巴说话时还了一礼上下打量却认他不出。郭芙出来叫买马鞭时急忙撇下杨过迎上去从怀中掏出马鞭献上。随后与郭芙和弟弟进庙取包裹出庙上马而去。"
      }
    },
    "武修文": {
      "人物经历": {
        "神雕第十一回07-杨过乔装潦倒混入破庙逢郭芙武氏兄弟": "在破庙前与哥哥武敦儒喂双雕。郭芙出来时也即抢上尽力巴结。三人自顾说话对着坐在地下吃饭的杨过眼角也没瞥上一眼。随后取包裹兵刃上马而去。"
      }
    }
  },
  "参与人物": [
    "杨过",
    "洪七公",
    "郭靖",
    "黄蓉",
    "武敦儒",
    "武修文",
    "郭芙"
  ]
}

