  "事件详情": "隐伏在竹林暗处的乔峰目睹段正淳一方命悬一线，念及段正淳乃当世闻名之英雄豪杰，加之生平极度痛恨恶人逞凶为非作歹，胸中侠义之气激荡，遂决定悍然出手相助。乔峰长啸一声，自青翠竹林之中飞身纵出，气势犹如猛虎下山。他当即施展出威震武林的“降龙十八掌”，挥掌激荡出浑厚如狂涛巨浪般的掌风，后发先至，瞬间逼退了正欲扑向阿紫施暴的云中鹤，稳稳将阿紫从魔爪下解救出来。紧接着，乔峰毫不停歇，顺势反手轰出一记刚猛无俦的掌力，与段延庆自半空中疾刺而来的精钢细杖凌空硬拼。只听轰然一声惊天动地的巨响，气浪狂卷，段延庆那柄坚硬无比的精钢双杖竟被乔峰狂暴无匹的浑厚掌力震得当场齐齐折断；段延庆整个人如遭重锤猛击，倒飞出数丈之外，胸中气血翻涌难平，骇然失色。段延庆深知乔峰掌力神勇盖世、绝非人力所能抗衡，自知难敌，冷哼一声后携同狼狈的云中鹤仓皇退走，小镜湖之围遂解。",
  "事件概要": "乔峰见段正淳遇险且恶徒逞凶，悍然自竹林纵出施展降龙十八掌，后发先至震退云中鹤救下阿紫，旋即凌空对掌震断段延庆精钢双杖并将其击飞重创。段延庆深骇其神力不可匹敌，遂携云中鹤仓皇遁走，小镜湖之危顿解。",
  "insert": {
    "乔峰": {
      "人物经历": {
        "天龙第二十一回04-乔峰施降龙掌震退段延庆": "见段正淳遇险且恶徒肆虐，胸中侠气难抑，自竹林飞身纵出长啸破空，施展降龙十八掌挥出磅礴掌风逼退云中鹤救下阿紫，紧接着反手一掌与半空中扑来的段延庆凌空硬拼，以狂暴无匹的浑厚掌力当场震断其精钢双杖并将强敌震飞退走。"
      }
    },
    "段正淳": {
      "人物经历": {
        "天龙第二十一回04-乔峰施降龙掌震退段延庆": "力竭难支危急存亡之际，忽见一名威猛大汉自林中长啸跃出，使出至刚至猛的降龙十八掌逼退云中鹤救下阿紫，更反掌震断大仇敌段延庆的精钢细杖将其重创击退，惊骇于此人通天神勇之余，满心皆是绝处逢生之庆幸。"
      }
    },
    "段延庆": {
      "人物经历": {
        "天龙第二十一回04-乔峰施降龙掌震退段延庆": "正全力围攻段正淳，忽遭一名魁伟壮汉自竹林破空杀出，凌空一掌刚猛无俦如怒海狂涛，不仅自身精钢双杖被其沛然真力生生震断，更受巨力猛击倒飞数丈、气血翻涌，深知来者掌力盖世绝非人力所能抗衡，唯有一声冷哼携同云中鹤仓皇退走。"
      }
    },
    "云中鹤": {
      "人物经历": {
        "天龙第二十一回04-乔峰施降龙掌震退段延庆": "正欲飞身扑抓阿紫施暴，忽闻平地惊雷般的长啸，一道狂暴无匹的浑厚掌力如狂涛巨浪般后发先至，当场被强劲掌风逼得踉跄倒退，紧接着惊见老大段延庆亦被其一掌震断双杖击飞重创，心惊胆战之下急忙随老大狼狈逃离竹舍。"
      }
    },
    "阿紫": {
      "人物经历": {
        "天龙第二十一回04-乔峰施降龙掌震退段延庆": "眼见青袍恶徒扑至身前避无可避，忽逢竹林中纵出一名神威凛凛的威猛豪杰，凌空一记浩大掌风后发先至震退恶汉将自己救下，复见其顺势反手一掌震断另一凶残强敌的钢杖，彻底化解危局，惊魂甫定之余不禁美目异彩涟涟。"
      }
    }
  },
