  "事件引子": "残灯摇曳，腥气弥漫的马宅内室重归死寂，唯余窗外呼啸冷风与地上未凉的尸身血泊。",
  "事件详情": "康敏凄惨暴毙气绝，追查雁门关带头大哥的唯一线索就此灰飞烟灭，破败狼藉的马宅内室再次重重陷入死一般的寂静。乔峰失魂落魄地伫立在刺鼻的血泊之前，高大威武的身躯因极致的悲痛而剧烈颤抖。他缓缓伸手探入怀中，极度珍惜地取出了阿朱生前亲手为他缝制的那只贴身荷包与一块素色旧帕。乔峰那双斩将搴旗、布满厚茧的粗糙大手此时微微发颤，一遍又一遍轻柔抚摸着荷包上细密熟悉的针脚与飞针走线，睹物思人，无边无际的悔恨与痛楚如海啸般将他彻底吞噬。乔峰脑海中如走马灯般疯狂闪回当年雁门关外断桥之畔，阿朱依偎在他怀中巧笑嫣然、许下“塞上牛羊空许约”时的温柔情景，那是他们二人曾万分憧憬的远离中原武林纷争、并辔策马驰骋大漠的宁静余生。然而命运弄人，自己竟受蛇蝎毒妇玩弄，在青石桥暴雨之夜亲手将挚爱毙于掌下，曾经的海誓山盟终究化作了永世难偿的凄凉空诺。英雄泪如决堤之水滚滚滑落，大颗大颗砸在染血的遗物之上，乔峰仰天发出沉痛悲咽，最终深吸一口气将遗物郑重收回怀中贴身安放，在绝望深渊中强自克制哀恸。",
  "事件概要": "康敏暴毙使追查带头大哥的线索彻底断绝，内室重归死寂。乔峰失魂落魄伫立血泊前，取抚阿朱生前遗留的荷包素帕，悲忆塞上牛羊之约与青石桥错杀惨剧，悔恨交加下热泪滚落、仰天悲咽，终强按断肠剧痛收存遗物。",
  "insert": {
    "乔峰": {
      "人物经历": {
        "天龙第二十三回08-抚遗物悲忆塞上牛羊之约": "见康敏暴毙令线索全断，独自失魂伫立于血泊之前，探怀取出阿朱亲手缝制的荷包与旧帕抚摸垂泪，痛忆雁门关塞上牛羊之誓与青石桥错杀之惨，仰天悲咽后强抑断肠剧痛收好遗物。"
      }
    }
  },
  "update": {},
  "后续事件": {
    "天龙第二十三回09-乔峰携阿紫启程北上求医": "追查带头大哥线索既断且大仇得报，乔峰强敛悲恸，准备带上重伤的阿紫离开洛阳启程北上求医。"
  },
  "参与人物": [
    "乔峰"
  ]
}

