  "事件引子": "牟尼堂内檀香幽微，诸僧闭目静候，忽闻堂外脚步沉雄，吐蕃国师已合十登门。",
  "事件详情": "未过多久，吐蕃国师大轮明王鸠摩智昂然步入天龙寺牟尼堂。他身披僧袍，合十施礼，言语之间温文尔雅、佛理精通，然而眉宇与目光之中却隐隐透出睥睨群雄的霸道威压。鸠摩智开门见山重提借阅《六脉神剑经》之事，遭到本因等高僧的断然拒绝。为彰显自身武力威慑全场，鸠摩智从容运功，当着天龙寺众僧之面施展中原少林派的七十二绝技。只见他指法变幻莫测，信手拈来间接连使出“拈花指”、“多罗叶指”与“无相劫指”，指风呼啸凌厉无匹，劲气破空激射，刚柔并济中蕴含着震人心魄的深厚功力。少林三大绝技在他手中施展得淋漓尽致，牟尼堂内气流剧震，令在场的高僧们无不大吃一惊。鸠摩智借此展现出自身深不可测的绝顶修为，既意在逼迫天龙寺屈服交出经书，也彻底击碎了和平交涉的可能，堂内气氛瞬间紧绷至一触即发。",
  "事件概要": "吐蕃国师鸠摩智步入牟尼堂重提强借经书，遭本因断然拒绝。鸠摩智从容运功，接连施展少林拈花指、多罗叶指与无相劫指，劲气破空激射以武力震慑全场。天龙寺众僧虽惊叹其少林绝技深湛，但誓死护经绝不退让，堂内剑拔弩张，恶斗势在必行。",
  "insert": {
    "本因": {
      "人物经历": {
        "天龙第十回06-鸠摩智牟尼堂显少林绝艺": "见吐蕃国师鸠摩智昂然入堂求借神剑经，当即严词予以回绝；随后见其从容施展拈花、多罗叶与无相劫三门少林绝艺，指力凌厉浑厚且转换由心，心下大为惊骇，暗凛来人武功深不可测。"
      }
    },
    "鸠摩智": {
      "人物经历": {
        "天龙第十回06-鸠摩智牟尼堂显少林绝艺": "昂步踏入牟尼堂重提换阅《六脉神剑经》之议，遭天龙寺住持本因当面拒绝；为挫天龙寺锐气并彰显自身神威，当场信手演练少林派拈花指、多罗叶指与无相劫指，指风激荡威慑全场，决意以绝顶修为逼其就范。"
      }
    }
  },
  "update": {},
  "后续事件": {
    "天龙第十回07-六僧结神剑阵力战火焰刀": "鸠摩智显露少林绝技威逼无果，当即催动火焰刀真气强夺经卷；枯荣与本因等六僧当即各占阵位运转剑气迎敌。"
  },
  "参与人物": [
    "本因",
    "鸠摩智"
  ]
}

