    "时": 13,
    "分": 15
  },
  "事件引子": "幽闭阴暗的石室中药香弥漫，狂暴的燥热与急促的娇喘在死寂中悄然蔓延。",
  "事件详情": "厚重如铁的幽闭石室之中，阴阳和合散的药性彻底发作，药力如烈火般在四肢百骸间汹涌翻腾。段誉与木婉清双双面红耳赤，浑身燥热难当，神智逐渐被汹涌的欲火吞噬。木婉清神智陷入昏沉狂乱，受强劲春药驱使，不由自主地扑入段誉怀中，娇喘连连地紧紧攀住段誉，哀声啼求道：“段郎……我好难受……抱紧我……”并不断伸手拉扯段誉的衣衫。段誉同样欲火焚身、筋脉燥痛，体内如万蚁噬咬，痛苦不堪。在伦理巨浪的冲击下，段誉脑海中恪守的纲常名教与圣贤训诫迸发出强烈的警醒。他深知二人乃同父异母的骨肉至亲，若在此刻沦为禽兽之行，不仅二人万劫不复，更会让父母蒙羞、家族蒙难。危急时刻，段誉狠心猛力咬破自己的舌尖，借着钻心剧痛强行唤回一丝清明。他死死抱住冰冷的石柱，盘膝坐地，苦苦运转《北冥神功》内力与狂暴的药性相抗衡，同时紧闭双目，口中反复高声诵念《金刚经》以求心神宁静。任凭木婉清如何撕扯哀求，段誉始终咬牙谨守最后一道道德底线，宁死不屈，在极度痛苦中硬生生抗住奇毒侵蚀，未损木婉清半分清白之躯。",
  "事件概要": "阴阳和合散药性彻底发作，木婉清神智昏沉受药力驱使扑向段誉哀声撕扯。段誉虽欲火焚身、筋脉燥痛，但恪守骨肉伦常，咬破舌尖强唤清明，死死抱住石柱运起北冥神功相抗，高声诵念金刚经凝神，任凭撕求硬抗药性，力保木婉清清白未失。",
  "insert": {
    "段誉": {
      "人物经历": {
        "天龙第九回02-段誉诵经运功苦抗春药": "察觉体内阴阳和合散药性汹涌如焚，见婉妹神智狂乱扑来攀扯啼求，唯恐陷入骨肉相残的伦常大祸，狠心咬破舌尖强唤清明；遂死死抱住冰冷石柱盘膝坐地，苦苦运起北冥神功抗御烈性春药，并紧闭双目高声诵念《金刚经》，拼死谨守清白底线。"
      }
    },
    "木婉清": {
      "人物经历": {
        "天龙第九回02-段誉诵经运功苦抗春药": "遭体内奇毒反噬而神智陷入昏乱狂乱，周身燥热如焚难当，迷乱中不由自主扑入段郎怀中攀扯其衣衫啼哭哀求抱紧，虽欲火炽盛难遏，却依稀感知对方抱柱诵经运功苦抗，未受半分逾矩冒犯。"
      }
    }
  },
  "update": {},
  "后续事件": {
    "天龙第九回03-保定帝发一阳指破门受阻": "段誉与木婉清在石室中苦苦抵御药性之际，保定帝等人已闻讯疾驰赶赴石室之外，欲以纯阳指力强破重门相救。"
  },
  "参与人物": [
    "段誉",
