      }
    }
  },
  "update": {
    "杨过": {
      "所在位置": "大宋/终南山/活死人墓",
      "状态": "以计策将李莫愁封入石棺之中。虽身中五毒神掌之毒心跳头痛随时能晕倒，但大敌已除强自支撑。以欧阳锋所授之法先将自身毒质逼出大半，然后伸左掌与小龙女右掌相抵助她驱毒——只须再有一顿饭时分便可毒质尽除",
      "关系网": {
