{
  "事件地点": "大宋/河南府/马宅/内室",
  "触发条件": {
    "类型": "时间",
    "年": 1092,
    "月": 3,
    "日": 16,
    "时": 23,
    "分": 50
  },
  "事件结束时间": {
    "年": 1092,
    "月": 3,
    "日": 17,
    "时": 0,
    "分": 20
  },
  "事件引子": "马宅卧房内残瓦狼藉、幽光昏暗，恶毒叫骂与阴冷杀气在逼仄房中翻涌对峙。",
  "事件详情": "紧随乔峰纵身跃入屋内的阿紫天性阴鸷残忍，眼见康敏非但抵死不招，反而肆意妄为地出言恶毒羞辱已故的阿朱与乔峰，眸中杀机大盛，当即决定施展星宿派最令人闻风丧胆的阴毒酷刑彻底击垮其心智。阿紫嘴角噙着一抹残忍的冷笑，自腰间锦囊中取出一小瓷瓶粘稠的花蜜，欺身而上运指如电封住了康敏周身大穴，随即用指尖将香甜黏腻的蜜汁细致均匀地涂抹在康敏平日最引以为傲的雪白娇颜与修长玉颈之上。紧接着，阿紫自随身竹筒内倒出了数百只专以吸食活人血肉为生的剧毒“腐骨黑蚁”。成群的黑蚁嗅到扑鼻蜜香顿时彻底疯狂，如潮水般争先恐后地爬满康敏的眼窝、鼻翼与面颊，顺着毛孔疯狂钻咬撕扯皮肉。康敏瞬间遭受万蚁噬骨的钻心剧痛，在地上痛苦翻滚，喉中发出撕心裂肺的凄厉哀嚎，整张面孔眨眼间皮开肉绽、污血脓水横流。阿紫深知此女一生视容颜胜过性命，纯粹的肉体摧残尚不足以使其精神绝望，遂冷笑着从妆台上顺手抄起一面擦得雪亮刺目的八角菱花铜镜，一把硬生生扭住康敏满是毒蚁的脑袋，将冰冷的铜镜强行推至其眼前，逼迫这恶毒妇人睁眼直视自己被毁的可怖鬼相。",
  "事件概要": "阿紫见康敏抵死不招且恶语羞辱阿朱与乔峰，顿起杀机施展星宿恶刑。她封住康敏穴道，在其面颈涂抹花蜜引腐骨黑蚁疯狂噬咬撕肉；复顺手抄起菱花铜镜强逼其直视毁容惨相，欲彻底摧垮其心智逼问带头大哥真名。",
  "insert": {
    "阿紫": {
      "人物经历": {
        "天龙第二十三回06-阿紫施蚁刑以铜镜逼供": "见恶妇抵死不招且肆意羞辱亡姐与姐夫，心生恶念施展门派酷刑；运指封其周身大穴，在其面颈涂抹花蜜引数百腐骨黑蚁撕咬皮肉，更抄起菱花铜镜硬扭其头颅逼其直视毁容惨相，欲彻底击碎其心智以逼出口供。"
      }
    },
    "康敏": {
      "人物经历": {
        "天龙第二十三回06-阿紫施蚁刑以铜镜逼供": "正肆意出言羞辱讥嘲，猝不及防被紫衣少女封禁大穴；眼睁睁任由其在面颈涂抹甜腻花蜜并引剧毒黑蚁钻肉啃噬，痛极哀嚎却无法脱逃，更遭铜镜强推至眼前逼视自己血肉横流的可怖鬼相，精神陷入绝望狂乱。"
      }
    },
    "乔峰": {
      "人物经历": {
        "天龙第二十三回06-阿紫施蚁刑以铜镜逼供": "见阿紫愤然出手以星宿派毒蜜蚁刑惩戒恶妇，虽觉手段过于残忍阴鸷，但痛惜阿朱惨死且急于追查带头大哥下落，遂冷眼按捺未加阻拦，静立房中紧盯逼供结果。"
      }
    }
  },
  "update": {
    "康敏": {
      "状态": "重伤毁容"
    }
  },
  "后续事件": {
    "天龙第二十三回07-康敏照镜见毁容惊骇暴毙": "康敏被迫睁眼直视铜镜中血肉模糊的狰狞鬼相，平生最自负的容颜彻底尽毁，心神遭遇毁灭性重创。"
  },
