      }
    },
    "陆立鼎": {
      "人物经历": {
        "神雕第一回03-陆家庄夜来不速客": "见女儿陆无双摔断腿骨、武敦儒头破血流，又见借宿妇人出手利落点穴接骨，心生疑虑。小道姑飞身上屋喝令全庄自尽，陆立鼎气得全身发颤。武三娘出手击退小道姑后，陆立鼎双指钳住银针中毒，幸得武三娘及时解毒救治，施礼称谢。"
      }
    },
    "陆二娘": {
