  "事件详情": "鸠摩智在大理成功生擒段誉后，为尽快赶赴江南姑苏以全昔日之约，一路之上日夜兼程，沿途不断雇车换马，以惊人速度自西南大理向东南江南疾驰。此时段誉周身穴道受制，内力与肢体皆被禁锢，只觉浑身酸软、动弹不得，唯有一颗神智依然清晰。在颠簸的囚途马车之中，段誉心中虽极度忧虑自身的生死未卜，更挂念着钟灵与木婉清二女如今究竟下落何方、是否安好，但在强敌严密看管与穴道被封的处境下，他自知反抗无从谈起，只能无可奈何地听凭鸠摩智摆布。鸠摩智一路严防段誉脱逃，二人历经数千里的长途跋涉，终于顺利跨越关山，于这日安然抵达江南常熟境内。这一阶段的奔波不仅使段誉彻底沦为受制于人的阶下囚，也让两人的行迹从大理边陲彻底转移至江南水乡地界，为后续太湖之行奠定了直接的空间情境。",
  "事件概要": "鸠摩智生擒段誉后日夜兼程换马疾驰，奔赴姑苏以践焚经旧诺。段誉周身要穴受制、动弹不得，虽满心忧虑自身安危并挂念钟灵与木婉清，却难脱强敌严密看管。二人千里跋涉跨越关山，终安然抵达江南常熟，为后续太湖之行奠定情境。",
  "insert": {
    "鸠摩智": {
      "人物经历": {
        "天龙第十一回01-鸠摩智生擒段誉疾驰赴江南": "生擒段誉后唯恐夜长梦多，当即雇车换马、日夜兼程由大理疾驰赶赴江南，誓要将这活剑谱带至慕容先生墓前焚化践诺；一路严加看管防范其脱逃，历经关山跋涉终安然抵达常熟境内。"
      }
    },
    "段誉": {
      "人物经历": {
        "天龙第十一回01-鸠摩智生擒段誉疾驰赴江南": "周身要穴被封致使内力与肢体皆遭禁锢，颠簸于囚车之中浑身酸软、动弹不得；心虽万分担忧自身生死并牵挂钟灵与木婉清安危，奈何强敌看守严密反抗无从，只能任由鸠摩智一路挟持运抵江南常熟。"
      }
    }
  },
  "update": {},
  "后续事件": {
    "天龙第十一回02-鸠摩智常熟雇舟载段誉入太湖": "二人抵达常熟境内，陆路已尽而水网纵横，鸠摩智遂押解段誉前往渡口寻觅舟楫，准备改走水路深入太湖。"
  },
  "参与人物": [
    "鸠摩智",
    "段誉"
  ]
}

