586744.content:
{
  "事件地点": "大宋/襄阳/大校场",
  "触发条件": {
    "类型": "时间",
    "年": 1259,
    "月": 10,
    "日": 24,
    "时": 22
  },
  "事件结束时间": {
    "年": 1259,
    "月": 10,
    "日": 24,
    "时": 23
  },
  "事件引子": "你听说城西大校场上丐帮大会正在进行，第三件寿礼揭开后竟是金轮法王二弟子达尔巴——他认出台上何师我正是叛师师弟霍都，怒挥金杵冲上台去……",
  "后续事件": {
    "事件名": "神雕第三十七回02-霍都假死偷袭郭芙黄药师杨过现身",
    "描述": "霍都被达尔巴飞杵击杀后装死不动，郭芙上前用剑削其假面时霍都突然暴起发动临死一击……"
  },
  "事件详情": "青灵子等八位武林名宿将布袋中擒来之人放出——正是金轮法王二弟子达尔巴。青灵子用藏语告知达尔巴台上何师我即叛师师弟霍都，并将黄金杵还给他。达尔巴怒吼跃上台挥杵猛攻，何师我赤手空拳只得以小巧身法闪避。丐帮弟子欲上台应援却被青灵子、西山一窟鬼、史氏兄弟等二十三人团团围住。青灵子趁乱拔起何师我插在台边的铁棒，运掌劈碎棒身露出内藏的碧绿竹棒——正是丐帮失落的打狗棒。群丐骇然惊呼。郭靖黄蓉不明杨过用意袖手旁观静观其变。黄蓉与朱子柳旁观之下，从何师我的武功身法、刻意隐藏兵刃的异常举动，以及脸上以胶水面粉涂抹的伪装，推断出何师我正是霍都——十六年前在终南山叛师脱逃的金轮法王弟子，潜伏丐帮十余年按部就班升至五袋弟子，暗杀鲁有脚夺得打狗棒藏于铁棒之中。达尔巴与霍都激斗数百合不分胜负，突使师父所传飞掷金杵绝技——第十八下猛喝双掌推杵平射而出，砰的一声正中霍都胸口致其毙命。达尔巴收起金杵大哭三声，盘膝念诵往生咒后纵下高台，向青灵子交还金杵——青灵子不接叫其回西藏从此不可再到中原。达尔巴合十飘然而去。",
  "事件概要": "霍都身份与弑师夺棒旧案当众败露，达尔巴清理师门击毙霍都，打狗棒重归丐帮。",
  "insert": {
    "达尔巴": {
      "功法": {
        "飞掷金杵": {
          "掌握程度": "初窥门径（十余年中追随师父左右，师父又传了他深湛武功——这飞掷金杵之技正是从师父五轮飞砸的功夫中变化出来。金杵重达五十余斤脱手飞掷势道凌厉之极，掷到第十八下猛喝双掌推杵平射而出当场击杀霍都清洗师门）"
        }
      },
      "人物经历": {
        "神雕第三十七回01-达尔巴揭穿霍都清理师门": "达尔巴被青灵子等八高手擒至襄阳，闻台上何师我乃叛师师弟霍都，怒提黄金杵上台激斗，数百合后以师传飞杵绝技第十八下击杀霍都。哭三声念往生咒，还杵青灵子，奉神雕侠命返西藏，不再入中原。"
      }
    },
    "霍都": {
      "人物经历": {
        "神雕第三十七回01-达尔巴揭穿霍都清理师门": "霍都伪装何师我混入丐帮，暗杀鲁有脚夺打狗棒藏铁棒中。丐帮大会青灵子召达尔巴揭穿，劈棒露棒。黄蓉朱子柳断其潜伏十余年。达尔巴掷金杵中胸，霍都毙命，临死装死图同归于尽。"
      }
    },
    "青灵子": {
      "人物经历": {
        "神雕第三十七回01-达尔巴揭穿霍都清理师门": "以藏语告知达尔巴台上何师我即叛师师弟霍都将金杵还他。纵身上台拔起何师我铁棒挥掌劈碎露出打狗棒，双手横持恭恭敬敬交予郭襄。率西山一窟鬼史氏兄弟共二十三人团团围住高台阻住旁人上台干扰，确保达尔巴与霍都公平对决"
      }
    },
    "黄蓉": {
      "人物经历": {
        "神雕第三十七回01-达尔巴揭穿霍都清理师门": "与郭靖袖手旁观静观其变。见何师我危急仍不取兵刃心中起疑，认出他脸上凹凹凸凸的疮疤是用胶水蜂蜜调面粉石膏涂抹伪装。与朱子柳当众推演出霍都潜伏丐帮十余年、暗杀鲁有脚夺打狗棒、藏棒于铁棒之中的全部阴谋。感叹霍都如此工于心计也算得是个人杰，但想作丐帮之主却把黄蓉忒也瞧得小了"
      }
    },
    "朱子柳": {
      "人物经历": {
        "神雕第三十七回01-达尔巴揭穿霍都清理师门": "看何师我与达尔巴激斗良久忽地省悟——认出十七年前大胜关英雄大会上与自己激斗数百合的霍都的武功身法。与黄蓉默契配合推演出霍都伪装何师我的全部真相——假脸是用胶水面粉涂抹、兵刃是去掉扇面的折扇骨"
      }
    },
    "郭靖": {
      "人物经历": {
        "神雕第三十七回01-达尔巴揭穿霍都清理师门": "与黄蓉识得达尔巴却猜不透杨过用意——但想前两件礼物于襄阳大大有利第三件不该有敌意，夫妇俩袖手不动静观其变"
      }
    },
