    "时": 12,
    "分": 45
  },
  "事件引子": "晨曦微明，山脚下的废弃农舍残垣蛛网、破败寂寥，深山追兵的呼喝声终于渐次远去。",
  "事件详情": "神农帮追兵在后穷追不舍，段誉一心只求保全负伤的木婉清性命，不顾自身内力浅薄，背负着她在崇山峻岭与绝壁险峰之间拼尽全力疾奔。段誉将刚习得不久的“凌波微步”运转至极致，步法变幻莫测、迅疾如风，终于在崎岖的山野险径中彻底甩脱了后方所有的神农帮追兵。天色渐明破晓之时，二人一路奔行至无量山山脚下一座荒僻隐蔽的废弃破旧农舍前。段誉见四周暂时安全无虞，便小心翼翼地将重伤体虚的木婉清搀扶进农舍屋内坐下歇息。为了缓解木婉清的痛楚，段誉未作停歇，随即在农舍附近寻来甘甜清冽的泉水，取水轻柔细致地为木婉清清洗擦拭身上的创口血迹，动作极尽体贴呵护。木婉清见段誉一路舍命相救，此刻又如此温柔体贴地照料自己，原本冷傲戒备的心防彻底消融，身上创伤疼痛稍得缓解的同时，心中对段誉的柔情与爱意愈发深种，二人在这处破败农舍中暂时获得安宁与疗伤喘息的契机。",
  "事件概要": "段誉运转凌波微步背负木婉清疾奔突围，终在崇山险径中甩脱神农帮追兵，避入山脚破旧农舍。段誉悉心取来清冽泉水为重伤的木婉清擦洗创口血迹，极尽温存体贴；木婉清心防尽融、爱意深种，二人于荒僻废屋中暂获宁息。",
  "insert": {
    "段誉": {
      "人物经历": {
        "天龙第六回01-段誉负妹脱险农舍疗伤": "拼尽全力运转凌波微步背负婉妹在崇山间奔驰，终甩脱神农帮追兵并避入山脚废农舍；顾不得自身疲惫，忙在近处寻来清泉轻柔擦拭其伤口血污，见其痛苦稍解始感宽慰。"
      }
    },
    "木婉清": {
      "人物经历": {
        "天龙第六回01-段誉负妹脱险农舍疗伤": "伏于段誉背上随其险脱追兵避入废农舍，伤重无力难以动弹；见段誉不顾劳顿寻水细心擦拭自身创口、极尽温存体贴，心中戒备尽化为深情依恋，创痛亦随之大减。"
      }
    }
  },
  "update": {
    "木婉清": {
      "关系网": {
        "段誉": "缔结婚盟/95"
      }
    }
  },
  "后续事件": {
    "天龙第六回02-风波恶率众围困废农舍": "二人在破败农舍中歇息疗伤，屋外却忽有强敌破空逼近之声响起，杀机再度迫近。"
  },
  "参与人物": [
    "段誉",
    "木婉清"
