  "事件引子": "你在市镇粮食店前看到一个黄衣道姑左手抱着婴儿右手掏银两买米。那婴儿身上的襁褓是湖绿色缎子，绣着一只殷红小马——好眼熟的花样。",
  "后续事件": {
    "事件名": "神雕第二十七回04-黄蓉李莫愁斗智斗力棘藤布阵智夺郭襄",
    "描述": "黄蓉跟踪李莫愁进入树林，一场斗智斗力的较量即将展开。"
  },
  "事件详情": "黄蓉走到卖苹果的担子前，捡了十来个大红苹果正要递给果贩银子，忽听身后一个女子清脆明亮的声音说道：'给秤二十斤白米，一斤盐，都放在这麻袋里。'黄蓉侧头斜望，见是个黄衣道姑站在粮食店前。那道姑左手抱着个婴儿，右手伸入怀中取银两。婴儿身上的襁褓是湖绿色的缎子，绣着一只殷红的小马——正是黄蓉亲手缝制之物。黄蓉一见这襁褓登时心头大震双手发颤，手中银子落入箩筐。这婴儿若不是她亲生女儿郭襄却又是谁？只见那道姑侧过半脸来容貌甚美，眉间眼角却隐隐含有煞气，腰间垂挂一根拂尘——正是江湖上大名鼎鼎的赤练仙子李莫愁。黄蓉又惊又喜忍不住要流下泪来，细看女儿眉目娇美神姿秀丽，虽是个极幼的婴儿已是美人胎子无疑。李莫愁付了银钱取过麻袋一手提了便即出镇。黄蓉见事机紧迫不及去招呼郭芙，心想李莫愁阴毒绝伦若强行抢夺必伤孩儿性命，于是不即不离跟随在后。眼见她沿大路向西而行折而向南走进一座树林，黄蓉展开轻功从树旁绕了过去赶在前头突然窜出迎面拦住，笑道：'这位想必是赤练仙子李道长了，幸会幸会！'",
  "事件概要": "黄蓉确认郭襄落入李莫愁之手并锁定去向，夺回女儿的追踪行动由此转入正面交涉。",
  "insert": {
    "黄蓉": {
      "人物经历": {
        "神雕第二十七回03-黄蓉遇李莫愁识郭襄追踪入林欲救女": "黄蓉在市镇买苹果，闻女声见黄衣道姑抱婴儿，认出襁褓是亲手所缝湖绿缎绣红马，知婴儿乃女儿郭襄，道姑即赤练仙子李莫愁。即尾随其后入林，绕至前路拦住道姑，以礼相见称久仰。"
      }
    },
    "李莫愁": {
      "人物经历": {
        "神雕第二十七回03-黄蓉遇李莫愁识郭襄追踪入林欲救女": "左手抱着婴儿右手取出银两在小市镇粮食店前买白米和盐。被黄蓉从身后认出——黄蓉一眼便认出了婴儿身上湖绿缎子绣着殷红小马的襁褓是她亲手所制。李莫愁浑然不觉抱着婴儿提麻袋出镇，折向南走进树林，忽见一个美貌少妇从前方窜出迎面拦住，心下一惊。"
      }
    },
    "郭襄": {
      "人物经历": {
        "神雕第二十七回03-黄蓉遇李莫愁识郭襄追踪入林欲救女": "被李莫愁抱在怀中到小市镇买粮。身上湖绿缎子绣殷红小马的襁褓是母亲黄蓉亲手缝制，正是这个襁褓让黄蓉认出了亲生女儿。黄蓉细看她眉目娇美神姿秀丽，虽极幼已是美人胎子，长得甚是壮健肥白可爱。"
      }
    }
  },
