  "事件引子": "冷风掠过苏州荒郊的乱坟残碑，枯草摇曳间，隐隐传来孩童嬉闹与含混嘶哑的呼喝。",
  "事件详情": "土丘荒冢之巅，杂草在冷风中瑟瑟摇曳，昔日名震江湖的“南慕容”慕容复正孤身端坐于枯石残碑之上。历经复国绝望、少室山惨败与连番心神重创，他已彻底神智失常、疯癫成狂，唯靠虚妄的帝王美梦麻痹自我。此刻他身上披着一件戏班遗弃的破旧褪色大红蟒袍，头顶歪斜地戴着一顶用粗糙黄纸糊成的简陋皇冠，形容枯槁却硬撑着不可一世的帝王神态。他眼神涣散空洞，颤巍巍从怀中掏出一个油污的粗布纸包，抓起一把把廉价劣质的麦芽杂糖，傲然向土坡下的孩童挥洒，口中含混嘶哑地宣诏：“众卿平身！朕的大燕中兴指日可待，待打下江山，尔等皆封王拜相、享尽荣华！”围聚坡下的乡野村童争抢着沾满泥灰的甜糖，嬉笑着纷纷跪倒在烂泥草丛中，敷衍地频频磕头，齐声怪腔怪调地高喊：“大燕皇帝万岁万岁万万岁！”慕容复见状狂喜抚掌，陶醉在虚妄的君临天下幻象中，将一包残糖尽数散出，彻底沦为荒野中令人扼腕叹息的疯癫痴人。",
  "事件概要": "慕容复经少室山等重创心神崩溃彻底疯癫，头戴黄纸简冠、身裹破戏蟒袍端坐荒冢残碑。他将怀中劣质麦芽糖向坡下村童挥洒，虚妄宣诏封王拜相；村童争抢泥糖敷衍磕头高呼万岁，慕容复抚掌狂喜，彻底沉迷于复国君临的幻梦中。",
  "insert": {
    "慕容复": {
      "人物经历": {
        "天龙第四十七回04-慕容复戴纸冠受拜分发糖果": "身披破戏袍、头戴粗糙纸冠端坐荒冢石碑，抓出怀中麦芽杂糖洒向坡下村童，含混嘶哑宣诏众卿平身并许以王相厚禄，见群童争食跪拜高呼万岁，抚掌大喜，沉醉于君临天下的虚妄美梦中。"
      }
    }
  },
  "update": {
    "慕容复": {
      "状态": "疯癫成狂",
      "外貌": "形容枯槁，身披破旧褪色大红蟒袍，头戴歪斜黄纸皇冠，眼神涣散空洞"
    }
  },
  "后续事件": {
    "天龙第四十七回05-阿碧含泪守炉烹茶相伴疯主": "慕容复在土丘残碑前狂喜散尽残糖，荒冢下方的草棚旁隐隐升起烹茶微烟并传来幽幽啜泣。"
  },
  "参与人物": [
    "慕容复"
  ]
}

