      }
    },
    "段誉": {
      "人物经历": {
        "天龙第四十五回02-鸠摩智井底走火入魔狂暴失控": "见吐蕃国师双目猩红、状若疯魔般在井底狂击乱劈，急忙展臂将王姑娘护在身后；冷不防被其合身扑倒扼住颈项陷入窒息绝境，生死一线间本能抬手扣住对方腕部穴道奋力抗衡。"
      }
    },
    "王语嫣": {
      "人物经历": {
        "天龙第四十五回02-鸠摩智井底走火入魔狂暴失控": "蜷缩在阴暗泥淖中，目睹鸠摩智神智尽失、如妖魔般咆哮轰击井壁，眼见段公子舍命挡在自己身前却被狂僧扑倒死死扼住咽喉，惊骇欲绝却无力施援。"
      }
    }
  },
  "update": {
    "鸠摩智": {
      "状态": "走火入魔、经脉逆乱"
    }
  },
  "后续事件": {
