  "事件引子": "你听说襄阳城外荒谷深处有一个隐秘山洞，据说洞中埋葬着一位绝世剑客...",
  "后续事件": {
    "事件名": "神雕第二十三回03-武三通荒谷夜哭述往事",
    "描述": "杨过拜别神雕回洞后，在荒谷中遇到一个披头散发的大汉正掩面大哭"
  },
  "事件详情": "神雕咬住杨过衣角引他前行，足步迅捷异常直入深谷。来到一个大山洞前，神雕在山洞前点了三下头叫了三声，回头望着杨过，似是向洞中行礼。杨过心想洞中定住着前辈高人，便在洞前跪倒拜了几拜说道：'弟子杨过叩见前辈，请恕擅闯洞府之罪。'待了片刻洞中并无回答，神雕拉他衣角踏步便入。洞中其实甚浅，行不到三丈已抵尽头，除石桌石凳外并无别物。杨过见洞角一堆乱石高起极似坟墓，一抬头见洞壁上隐约有字，打火点燃枯枝抹去青苔，现出三行字来——'纵横江湖三十余载，杀尽仇寇，败尽英雄，天下更无抗手，无可奈何，惟隐居深谷，以雕为友。呜呼，生平求一敌手而不可得，诚寂寥难堪也。'落款是'剑魔独孤求败'。杨过将这寥寥数语反复念了数遍，既惊且佩，体会到其中的寂寞难堪之意——这位前辈奇士只因天下无敌只得隐居深谷，武功深湛精妙到了不可思议的地步。他低回良久，在洞中察遍找不到其他遗迹，料是神雕衔石堆坟将他埋葬。杨过对这位前辈异人越来越仰慕，不自禁在石墓前跪倒拜了四拜。",
  "事件概要": "杨过得知神雕所守乃独孤求败遗冢，对剑魔遗志心生敬慕，也与这处洞府正式结缘。",
  "insert": {
    "杨过": {
      "人物经历": {
        "神雕第二十三回02-神雕引杨过入独孤求败洞府": "杨过随神雕入深谷山洞，见乱石坟冢，壁有字迹。拂去青苔，乃剑魔独孤求败留书：纵横江湖三十余载，求一敌手而不可得，寂寥难堪。杨过反复念诵，惊佩并于墓前跪拜四拜，对其武功与心境神往。"
      }
    },
    "神雕": {
      "人物经历": {
        "神雕第二十三回02-神雕引杨过入独孤求败洞府": "在洞前向故主独孤求败坟墓点头鸣叫行礼后引杨过入洞。见杨过对石墓恭敬跪拜似乎心中欢喜，以翅轻拍其肩表示赞许"
      }
    }
  },
  "update": {
    "杨过": {
      "状态": "在独孤求败洞府中缅怀前辈风烈无限神往。神雕对故主坟墓行礼的忠诚、杨过对独孤求败遗言的感悟令他对这位素未谋面的剑魔生出深厚敬仰。洞中肃穆的气氛令杨过暂时忘却了自身的生死之患"
    },
    "神雕": {
      "所在位置": "大宋/襄阳城外/独孤剑冢荒谷/洞府",
      "状态": "在洞府中守护独孤求败坟墓",
      "关系网": {
        "杨过": "新友/85"
      },
      "身份": {
        "剑魔遗友": "剑魔独孤求败生前之友，守护其坟墓数十年的异兽神雕，居于襄阳城外荒谷深洞之中。今引杨过入洞拜谒故主"
      }
    }
  },
  "参与人物": [
    "神雕",
    "杨过"
  ]
}

