    "分": 15
  },
  "事件引子": "雁门关外残阳如血，狂风卷席黄沙漫天，千军散尽的荒原上残旗猎猎、折戟沉沙。",
  "事件详情": "雁门关外残阳如血，狂风卷起漫天沙尘，千军散尽后的荒原上残旗猎猎、折戟沉沙。自宋哲宗初年至绍圣末年，跨越半个世纪的武林浩劫与天下纷争至此走向终局。昔日少室山群雄合围的刀光剑影、聚贤庄惨烈的掌力轰鸣，以及中原豪杰、大理段氏、大辽铁骑与西夏武士之间的血火交锋，皆在天地肃杀中归于沉寂。面对苍茫大地与累累白骨，幸存的武林名宿与各方势力在惨痛代价面前彻底丧失了争霸动机，纷纷收敛兵刃、退出纷争。这场席卷宋、辽、大理、西夏四国的宏大乱局，在无数英雄喋血与爱恨纠葛的冲刷下，迎来最终的宿命转折。刀枪入库，恩怨两消，昔日争夺《易筋经》、六脉神剑与天下霸权的血雨腥风尽数化作历史尘埃。全书宏阔画卷在此全面收束定格，不仅确立了宋辽边境暂得休养生息的和平闭环，更彻底终结了由玄慈、萧远山、慕容博上一代仇怨延宕至今的因果死结，为后续诸位主角的人生归宿提供了无可逆转的历史盖棺定论。",
  "事件概要": "雁门关外千军散去，席卷宋辽与大理西夏的半世纷争终归沉寂。累累白骨与惨痛代价使各方势力尽敛干戈，由玄慈、萧远山与慕容博延宕数十载的仇怨死结彻底消弭。两代恩怨两消，全书纷扰画卷定格收束，宋辽边境终得休养生息。",
  "insert": {
    "萧远山": {
      "人物经历": {
        "天龙第五十回01-五十年风云如梦全书落幕": "立于黄沙漫天的塞外荒原，目睹千军退去、白骨蔽野之惨景，感悟半生血海深仇终随峰儿之志化为尘土，默运佛法长叹合十，胸中杀伐戾气荡然无存。"
      }
    },
    "慕容博": {
      "人物经历": {
        "天龙第五十回01-五十年风云如梦全书落幕": "伫立于残阳斜照的雁门关外，遥望折戟沉沙的古战场，深知穷兵黩武复兴大燕终是镜花水月，彻底斩断数十年争霸执念，心如古井不波。"
      }
    }
  },
  "update": {},
  "后续事件": {
