  "事件引子": "雁门关外乱石嶙峋，凄风呼啸回荡在削平的石壁前，空旷山道间忽有轻促脚步声踏破死寂。",
  "事件详情": "就在乔峰面对光秃石壁仰天长啸、陷入举目皆敌与万念俱灰的至暗绝境之时，身后空旷的山道上忽然传来了阵阵轻柔而急促的脚步声。乔峰心中一凛，霍然回首望去，赫然见到在烂漫山花掩映之下，伫立着一位身着红裳、容貌清秀温婉的少女。那少女俏脸挂满泪珠，目光中交织着无尽的关切、思念与痛惜，正是大病初愈便跨越千里关山苦苦寻觅至此的阿朱。阿朱看清眼前正是自己日夜悬心的乔大爷，再也无法克制内心的激动与悲喜，张开双臂飞奔向前，一头扑入乔峰温暖宽阔的怀抱之中泣不成声。阿朱泪流满面地倾诉寻觅的千辛万苦，面对世间汹汹浊流，她毫不动摇地深情告白：纵然天下人都视乔峰为契丹恶贼、天下群雄皆欲除之而后快，自己也无怨无悔，甘愿一生一世追随服侍乔大爷，至死不渝。这番患难与共、生死相随的赤诚之言，宛如破开重重黑夜的炽热暖阳，瞬间融化了乔峰冰封绝望的心灵。",
  "事件概要": "乔峰抚平壁悲啸陷于绝境之际，伤愈寻至的阿朱飞奔扑入其怀中痛哭。面对天下皆敌的凶险狂澜，阿朱倾诉千里追寻之苦，誓愿生死相随服侍一生；赤诚深情化解了乔峰心头冰霜与孤愤，二人患难相依定下同行之约。",
  "insert": {
    "乔峰": {
      "人物经历": {
        "天龙第十九回06-阿朱现身绝壁飞扑相拥诉深情": "正当抚摸削平石壁万念俱灰、悲愤长啸之时，回首惊见红衫阿朱踏花而来并飞奔扑入怀中痛哭；听闻其不顾世人唾骂甘愿生死相随的赤诚告白，胸中冰封与绝望顿被融化，深感患难得此知己生平无憾。"
      }
    },
    "阿朱": {
      "人物经历": {
        "天龙第十九回06-阿朱现身绝壁飞扑相拥诉深情": "大病初愈后千里关山苦寻乔大爷，终在雁门关绝壁前得见其萧索身影，情难自禁飞奔扑入其怀中泣不成声；纵知天下皆视其为契丹仇敌，亦当面坚决立誓一生一世追随服侍、至死不渝。"
      }
    }
  },
  "update": {
    "乔峰": {
      "关系网": {
        "阿朱": "生死知己/90"
      }
    },
    "阿朱": {
      "关系网": {
        "乔峰": "生死相随/95"
      }
    }
  },
  "后续事件": {
    "天龙第十九回07-乔峰阿朱定盟携手追查真凶": "绝壁前定盟相守后，乔峰与阿朱收拾悲郁心绪，决定并肩南下追查当年雁门关惨案带头大哥与杀母真凶。"
  },
  "参与人物": [
    "乔峰",
    "阿朱"
  ]
}

