  "事件引子": "冰洞内寒气砭骨、冷雾弥漫，童姥盘坐于平整冰石之上，目光如电紧盯面前局促不安的小僧。",
  "事件详情": "在寒气逼人的万年冰洞深处，天山童姥向惊骇万分的虚竹说明了自身变小的惊人原委：她所修炼的逍遥派至高神功“八荒六合唯我独尊功”每三十年必须返老还童一次，当前正值功力尽失、体魄退化为幼童的极度虚弱期，每日午时唯有生饮活禽走兽的新鲜温热之血方能逐日重聚真气。童姥在察觉虚竹左手中指佩戴着掌门信物七宝指环，且体内流淌着师弟无崖子苦修七十年的精纯纯阳真气后，当下以逍遥派大师伯身份自居，声色俱厉地强逼虚竹恪尽师门晚辈之责。为了抢在万仙攻山与宿敌寻仇前恢复神功，童姥严令信守佛门清规戒律的虚竹每日必须走出冰洞，在雪岭间猎杀活鹿并取新鲜鹿血供其生饮运功。虚竹深陷佛门“不杀生”戒律与拯救尊长性命的两难痛苦冲突中，数度合十苦求无果，最终在童姥分筋错骨狠辣威逼与同门大义重压下含泪妥协，每日猎鹿取血，使童姥得以维系生机并正式开启漫长凶险的功力复原进程。",
  "事件概要": "天山童姥道出返老还童神功之秘，严令生饮活血以聚真气。她察觉虚竹身负无崖子内力与掌门指环，遂以大师伯之尊严逼其恪尽同门之责。虚竹深陷佛门戒律与救护长辈两难，数度苦求无果后只得含泪妥协，每日出洞猎鹿取血，助童姥维系生机开启功力复原。",
  "insert": {
    "虚竹": {
      "人物经历": {
        "天龙第三十三回07-童姥迫虚竹捕杀鹿血助练功": "惊闻童姥竟需生饮温热兽血方能恢复神功，见其以逍遥派尊长自居严厉喝令，深陷杀生破戒与拯救师伯的两难煎熬；几番叩首苦求遭拒且受分筋错骨惩戒，万般无奈下含泪违戒出洞猎鹿取血供其饮用。"
      }
    },
    "天山童姥": {
      "人物经历": {
        "天龙第三十三回07-童姥迫虚竹捕杀鹿血助练功": "向丑和尚明示神功返老还童之秘与每日饮血之急，察其指戴七宝指环且怀师弟精纯真气，遂摆出大师伯威严施展狠辣手段相逼，迫使迂腐小僧含泪破戒雪岭猎鹿，生饮热血以聚真气复原功力。"
      }
    }
  },
  "update": {},
