  "事件引子": "石壁前群豪肃立屏息，珍珑棋局黑白交错、杀气森森，久久无人敢上前应战。",
  "事件详情": "眼见群豪面面相觑无人敢应，段誉为博王语嫣青睐，亦恐他人陷入凶险，率先排众而出，步至石壁珍珑之前。他自幼精研弈理、佛法浸润，意欲以仁厚棋道在杀伐棋势中辟出一条生路。段誉凝神静气，指尖拈起一枚温润白子，提气飞身直点石壁“去位七七路”。起初十余手，他以“慈悲为怀、兼济四方”之法灵动布子，白子如清流盘旋，妙手连发，数次化解黑子凶猛围剿。苏星河频频颔首，执黑子针锋相对，黑龙长躯翻卷，连施“倒脱靴”与“金鸡独立”等杀招，招招直逼白子软肋。石壁上黑子如铁骑合围，将白子两块重兵死死截断，局势急转直下，陷入绝境。苏星河沉声喝道：“段世子，欲救大局，速斩左翼十子弃车保帅！”段誉望着石壁上苦苦支撑的己方孤子，心中大恸。他天性仁善，佛心深种，视棋子如活生生之生灵，宁可自身受困亦不忍痛下杀手将同袍弃之于死地，悬空的手指颤抖不休，迟迟无法落子杀伐。白子因犹豫不决而尽失先机，全盘气路彻底被黑子封死绞杀，段誉额角渗汗、心绪烦乱，长叹一声将手中白子掷回竹篓，躬身认负道：“晚生心存妇人之仁，破不得这等杀戮之局。”随即气血翻涌、步履微乱地退回阵中，首战宣告告负。",
  "事件概要": "段誉为护群豪并博王语嫣青睐，率先登场对弈。他以慈悲棋道巧化杀着，却遭苏星河黑子合围切断重兵。面对弃子保帅之抉择，段誉心怀仁善不忍杀伐同袍，终致气路断绝尽失先机，长叹掷子认负退场。",
  "insert": {
    "段誉": {
      "人物经历": {
        "天龙第三十一回02-段誉心怀仁善弃子认负": "为免旁人涉险并博王姑娘青睐，率先离阵登崖对弈；起手以佛家慈悲之法连解凶势，不料遭黑子截断两路大军，终因不忍弃子自残痛下杀手，全盘气路遭困只得掷子认负退归阵中。"
      }
    },
    "苏星河": {
      "人物经历": {
        "天龙第三十一回02-段誉心怀仁善弃子认负": "见大理世子率先破局，执黑施展倒脱靴等杀招截断其两路重兵；见其秉性过于仁善、不肯断尾求生以致先机尽失，虽赞其慈悲心性，仍坐视其白子困死、首战落败。"
      }
    },
    "王语嫣": {
      "人物经历": {
        "天龙第三十一回02-段誉心怀仁善弃子认负": "立于阵中见段誉自告奋勇登崖对弈，初见其棋路精妙化解黑子合围，暗暗称奇；待见其面对死局因不忍弃子而错失生机、掷子认负退下，心下亦为这珍珑杀局的凶险莫测暗自担忧。"
      }
    }
  },
  "update": {},
  "后续事件": {
    "天龙第三十一回03-慕容复执念入魔欲自刎": "段誉败阵退归阵中，珍珑杀局凶险愈发慑人，慕容复按捺不住复国野心，毅然离众上前接续对弈。"
  },
  "参与人物": [
    "段誉",
    "苏星河",
    "王语嫣"
  ]
}

