      }
    },
    "天山童姥": {
      "人物经历": {
        "天龙第三十四回05-童姥掠入绝色女子破其色戒": "见虚竹仍执迷佛法，遂夜潜西夏皇宫潜入内寝掳得绝色女子，褪其罗裳置于小和尚衾被中并暗渡燥热真气；隐于暗处冷眼旁观二人云雨缠绵，见其童身彻底告破，冷笑其终难逃逍遥门径。"
      }
    },
    "银川公主": {
      "人物经历": {
        "天龙第三十四回05-童姥掠入绝色女子破其色戒": "于深宫寝殿沉睡中骤遭神秘高手制伏掳掠，醒转时身处奇寒冰窖且寸缕不存，惶恐战栗下本能依偎紧贴身旁温热男子；神思恍惚迷乱间与其交欢缠绵、失却处子之身，宛如置身一场销魂迷梦。"
      }
    }
  },
  "update": {
    "银川公主": {
      "所在位置": "西夏/灵州/皇宫/地底深冰窖"
