  "事件详情": "鸠摩智被震退数步后大惊失色，但他乃当世绝顶智者，心念电转间立时恍然大悟：图谱虽毁，但眼前这个年轻书生举手投足间能发出纯正无匹的少商剑气，分明已将整部《六脉神剑经》全数记于脑中，其本身便是一部活生生的剑谱！鸠摩智当机立断，绝不恋战，身形化作一道鬼魅般的残影暴起突袭，以不可思议的身法瞬间绕开保定帝与天龙寺众僧的阻截。在众人不及回援的电光石火之间，鸠摩智施展出精妙绝伦的擒拿绝技，掌指如电精准拂中段誉周身大穴，当场制住段誉的行动与真气。鸠摩智一把抄起受制无法动弹的段誉，足尖点地施展绝顶轻功破空而去，向东疾驰遁走。保定帝与天龙寺众高僧大惊之下急忙飞身追赶，却终因稍慢一步而追赶不及，段誉再度身陷强敌魔掌，被鸠摩智一路挟持着强行押往姑苏。",
  "事件概要": "鸠摩智惊悉段誉已将六脉神剑经尽数熟记于心，当机立断暴起突袭，以鬼魅身法绕过保定帝与天龙寺众僧防线，电光石火间拂穴生擒段誉。众僧施救不及，鸠摩智挟持段誉破空向东遁走，强行押往姑苏。",
  "insert": {
    "段誉": {
      "人物经历": {
        "天龙第十回10-鸠摩智生擒段誉押往姑苏": "刚以少商剑逼退强敌尚未来得及回气，骤见黄影如鬼魅般穿透防线欺近，周身要穴已被对方指力精准拂中，行动与真气当场被封；随即身不由己被鸠摩智抄起提摄掠出堂外，眼见伯父与众僧追赶不及，心知再度沦为人质，满怀焦灼惊骇。"
      }
    },
    "鸠摩智": {
      "人物经历": {
        "天龙第十回10-鸠摩智生擒段誉押往姑苏": "被剑气震退后瞬间恍然大悟段誉身负整部神剑经，决意将其充作活剑谱生擒；当即施展绝顶身法绕开保定帝与天龙寺众僧阻截，出手如电精准拂中段誉周身大穴将其彻底制住，随即提人破空向东飞遁，将追赶不及的众僧抛于身后。"
      }
    }
  },
  "update": {
    "段誉": {
      "状态": "受制"
    }
  },
  "后续事件": {
    "天龙第十一回01-鸠摩智生擒段誉疾驰赴江南": "鸠摩智挟持生擒的段誉向东飞遁而去，段誉再度身陷险境，天龙江湖的宿命波澜就此向江南蔓延。"
  },
