{
  "事件地点": "大宋/陕南/荒野",
  "触发条件": {
    "类型": "时间",
    "年": 1244,
    "月": 10,
    "日": 12,
    "时": 8
  },
  "事件结束时间": {
    "年": 1244,
    "月": 10,
    "日": 19,
    "时": 8
  },
  "事件引子": "杨过信步下山来到陕南一处荒野之地，纵目平野忽听身后有马发声悲嘶...",
  "后续事件": {
    "事件名": "神雕第十一回07-杨过乔装潦倒混入破庙逢郭芙武氏兄弟",
    "描述": "杨过一路南行至汉水之畔遇丐帮帮众聚集，改装潦倒混入破庙遇郭芙与武氏兄弟"
  },
  "事件详情": "杨过自华山绝顶安葬二老后信步下山，不辨东西南北，心想大地茫茫就只自己孤身一人。不一日来到陕南一处荒野之地，放眼望去尽是枯树败草，朔风肃杀。突然间西边蹄声隐隐烟雾扬起，数十匹野马狂奔而东在里许之外掠过。杨过见众野马纵驰荒原自由自在，不自禁也感心旷神怡——正得意间忽听身后有马发声悲嘶。转过身来只见一匹黄毛瘦马拖着一车山柴缓缓走来——那马瘦得胸口肋骨高高凸起、四条长腿肌肉尽消宛似枯柴，毛皮零零落落生满了癞子，满身泥污杂着无数血渍斑斑的鞭伤。一个莽汉坐在车上嫌马走得慢不住手挥鞭抽打。杨过受人欺侮多了，见这瘦马如此苦楚，这一鞭鞭犹如打在自己身上一般，胸口一酸泪水几乎夺目而出。双手叉腰站在路中怒喝那汉子，莽汉挥鞭往杨过头顶抽来时被杨过夹手夺过倒转马鞭卷住头颈拉下马来夹头夹脸抽打了一顿。那瘦马模样虽丑却甚有灵性，见莽汉被打纵声欢嘶伸头过来在杨过腿上挨挨擦擦显得甚是亲热。杨过拉断了挽索拍拍马背指着远处马群奔过后留下的烟尘说：'你自己去罢再也没人欺侮你了。'那马前足人立长嘶一声向前直奔——可惜身子虚弱只奔出十余丈前腿一软跪倒在地。杨过见着不忍跑过去托住马腹喝一声'起'将马托了起来。眼见此马遭逢坎坷不禁大起同病相怜之心，抚着马背说：'马啊马啊，以后你随着我便了。'此后数日精心喂养，第二日见马精神健旺这才骑了缓缓而行。这癞马初时脚步蹒跚不是失蹄就是打蹶，哪知却是越走越好——七八日后食料充足精力充沛竟是步履如飞。杨过说不出的喜欢更是加意喂养。",
  "事件概要": "杨过安葬洪七公与欧阳锋后南下，并救下一匹瘦马作伴，重新踏上孤身行路。",
  "insert": {
    "杨过": {
      "重要物品": {
        "瘦黄马": "在陕南荒野所救的一匹受虐瘦马——毛皮生癞满身鞭伤模样丑陋，实则是一匹千里良驹。极有灵性——见到酒便嘶鸣讨要，喝了十余碗仍兴犹未尽。行路乘着酒意洒开大步驰得犹如癫了一般迅捷无比。更有一副逞强好胜的脾气——只要见到道上有牲口在前非发足超越不可，不论牛马骡驴总要赶过了头方肯罢休。杨过与它同病相怜意气相投，一人一马成了好友"
      }
    }
  },
  "update": {
    "杨过": {
      "所在位置": "大宋/陕南/荒野",
      "状态": "携瘦马南游（在陕南荒野救下一匹受虐瘦马后始有坐骑相伴。那马虽丑却是千里良驹——乘酒意奔驰时迅捷无比。一人一马意气相投成了好友。他本来情怀郁闷——途中调马为乐究是少年心性没几日便开心起来。自此一路向南来到汉水之畔）",
      "性格": "聪明机灵，狡猾惫懒，自尊心极强且敏感叛逆。自幼失去父母，饱尝人世冷暖。得小龙女真心相待后对她敬爱赤诚——溪边因完颜萍眼波蓦然醒悟才真正领会姑姑对自己的一往情深，懊丧欲死更决心走遍天涯也要寻她回来今生今世不负她。重情重义，守约守信——为守洪七公三日之约宁可饿死华山也不肯失信，以尾生抱柱自励。对义父欧阳锋愈久愈亲。离开古墓后仍留恋红尘，但为小龙女甘愿隐居山谷年余。遇事机变百出。对陆无双、完颜萍的感情皆因她们与小龙女的相似而起——借相似的眼波嗔怒之色以慰对姑姑的刻骨相思。凡事要在人前逞强好胜，决意处处胜过旁人。遭遇世人轻贱时常自伤自怜，看似轻佻浮脱实则内心血性男儿——可以命守诺不畏生死，大事当头豁得出去。美食当前也敢尝天下至奇之物（如蜈蚣）。在华山窄道上以'魁星踢斗势'一夫当关时只觉英雄之气充塞胸臆——虽衣衫褴褛而豪气干云。华山二老逝后更添一层世事浮云之慨——下山时觉别人看重也好轻视也好于我又有何干系，小小年纪竟愤世嫉俗玩世不恭起来。见瘦马受苦触景生情——以同病相怜之慨救下瘦马视如同命之交。",
      "人物经历": {
        "神雕第十一回06-杨过华山葬双雄救瘦马结伴南行": "杨过华山安葬二老后孤身南行，于陕南见一黄毛瘦马拖车被莽汉鞭打，怜马受欺便夺鞭痛打莽汉，拉断挽索纵马。因马坎坷生同病相怜之心，收留并精心喂养，马伤愈后步履如飞、极有灵性且嗜酒逞强。杨过觉此千里良驹屈于村夫，与其脾气相投，人马成友，郁闷渐消，一路向南至汉水畔。"
      }
    }
  },
  "参与人物": [
    "杨过"
  ]
}

