      "状态": "受伤（额头被剑锋削破）",
      "人物经历": {
        "神雕第二回04-杨过抱李莫愁被制神秘石子救场": "见李莫愁闯窑，急纵身挥剑拦住。李莫愁侧掌推剑，剑锋反削破她额头。又见李莫愁掳走二女，却已无法再战"
      }
    },
    "柯镇恶": {
