  },
  "事件结束时间": {
    "年": 1092,
    "月": 3,
    "日": 24,
    "时": 22,
    "分": 15
  },
  "事件引子": "厚重宫门紧闭如山，城头辽军箭雨礌石狂暴倾泻，破空呼啸与金铁交鸣震耳欲聋。",
  "事件详情": "在段誉与虚竹重创外围辽军大将后，南京皇宫那厚重如山、铜汁灌注的坚固城门依然死死闭合，阻断了通往地牢的去路。丐帮弟子与少林高僧见状奋勇当先，誓要在辽国大军回援合围前破开门户。丐帮帮众在长老率领下呼啸上前，以长棍齐施、内劲合一之势狂轰城门；少林派多位神僧与武僧齐宣佛号，各运浑厚少林内功，施展刚猛霸道的少林拳掌与降魔杵法直击门枢。尽管城头辽军拼死向下攒射强弓硬弩、泼洒滚木礌石，但少林与丐帮豪杰浑然不顾自身安危，以舍生忘死的昂扬气势硬生生顶着狂风暴雨般的反击，合力施展排山倒海的雄浑掌力连续重击。只听得轰隆一声巨响，坚不可摧的皇宫大门被硬生生砸开击碎，门框轰然倒塌！城内残余守军惊骇欲绝、四散溃逃。少林高僧与丐帮群雄一马当先，引着联军主力如潮水般长驱直入，直扑幽深阴暗的南京地牢深处。",
  "事件概要": "铜汁浇灌的厚重城门阻断解救去路，少林高僧与丐帮群雄舍生忘死抢攻城下，合力施展浑厚内劲狂轰门枢。一声巨响下坚门粉碎坍塌，残余守军惊溃，联军主力如潮破门长驱直入扑向地牢。",
  "insert": {
    "段誉": {
      "人物经历": {
        "天龙第四十回04-少林丐帮合力砸破皇宫城门": "见皇宫厚重坚门阻隔前路且城头箭矢滚石如雨，心忧结义大哥安危，脚踏凌波微步掩护身旁群豪；待目睹少林诸僧与丐帮群雄合力狂轰砸塌城门，当即与二哥虚竹并肩引兵长驱直入冲向地牢。"
      }
    },
    "虚竹": {
      "人物经历": {
        "天龙第四十回04-少林丐帮合力砸破皇宫城门": "见铜汁铁铸的巨大宫门阻断去路，急于营救义兄萧峰，见少林长辈师兄与丐帮豪杰舍生忘死合力攻破城门，遂运足北冥真气护体，紧随破门群雄直扑皇宫阴暗地牢深处。"
      }
    }
  },
  "update": {},
  "后续事件": {
    "天龙第四十回05-段誉虚竹运功破牢营救萧峰": "皇宫正门既破，少林丐帮引大军扫荡残敌，段誉与虚竹当先疾掠，直奔关押萧峰的阴森石牢。"
  },
  "参与人物": [
    "段誉",
    "虚竹"
  ]
}

