  },
  "事件引子": "牟尼堂内檀香骤散，双方谈辞决裂，无形剑气与炽热刀劲已在狭小殿堂间蓄势待发。",
  "事件详情": "双方言语交锋无果，终因经书归属彻底决裂，牟尼堂内瞬间爆发出惊天动地的大决战。枯荣禅师率领本因、本观、本相、本参以及化名本尘的保定帝同时发难，六僧依循方才演练的剑阵方位各出一指，将六路无形剑气交织汇聚成密不透风的六脉神剑阵。大厅之中嗤嗤破空之声不绝于耳，无形剑气纵横激荡，有如道道碧烟横空飞掠，声势极为骇人。面对天下无双的神剑阵，鸠摩智面无惧色，内力全开之下施展出独门神功“火焰刀”。只见他双掌翻飞，掌缘泛起炽热无比的无形刀气，刀气纵横劈斩，狂暴无伦，更兼配合少林绝艺层层推进。双方内力与招式激烈碰撞，气浪翻滚如潮，激斗惊心动魄。然而鸠摩智内功实在深不可测，激战数十回合后，炽热的火焰刀气竟逐渐将六位高僧配合未纯的剑阵压制落入下风。",
  "事件概要": "双方借经谈判决裂，枯荣率天龙寺六僧各出一指，结成六脉神剑阵齐攻强敌。大厅内嗤嗤破空激荡，剑气如碧烟横空。鸠摩智催动绝学火焰刀，无形掌风炽热狂暴，凭借深不可测的雄浑内力以一敌六，激战数十回合终将配合未纯的剑阵压入下风。",
  "insert": {
    "本因": {
      "人物经历": {
        "天龙第十回07-六僧结神剑阵力战火焰刀": "眼见番僧恃强索经，当即依仗商阳剑路纵跃出手，以灵动莫测的食指剑气配合诸僧交织成阵；岂料对方双掌运化炽热无形刀气霸道绝伦，硬生生顶住六脉围攻，激战中顿感自身剑网受其狂暴内力层层压制。"
      }
    },
    "本观": {
      "人物经历": {
        "天龙第十回07-六僧结神剑阵力战火焰刀": "见商谈破裂，当即催发中冲剑大开大阖之势，引中指剑气与同门合围绞杀；不料鸠摩智的火焰刀气炽热如焚、刚猛无匹，数十回合对拆下气浪汹涌翻腾，渐觉己方剑阵配合生疏难挡强敌狂攻。"
      }
    },
    "本相": {
      "人物经历": {
        "天龙第十回07-六僧结神剑阵力战火焰刀": "依阵法催动无名指关冲剑，以内劲凝出古朴拙滞的无形剑气封堵番僧进路；交手中只觉对方掌缘吐出的无形刀风狂暴炙热，重重掌影逼得经气难以施展，心惊于其内功深不可测。"
      }
    },
    "本参": {
      "人物经历": {
        "天龙第十回07-六僧结神剑阵力战火焰刀": "暴喝声中振臂出招，运化少泽剑轻灵奇巧的指力自侧翼急袭，与同门各路剑气相生相护；然而鸠摩智催动火焰刀气纵横劈斫、势如狂涛，硬碰之下气血翻涌，眼见剑阵已被炽烈劲风死死压制。"
      }
    },
    "枯荣": {
      "人物经历": {
        "天龙第十回07-六僧结神剑阵力战火焰刀": "面壁端坐运转少冲剑气参与合围，引指风协同五僧化成六脉神剑阵死守门户；交手渐久察知鸠摩智火焰刀内劲浑厚至极且招式层出不穷，己方仓促成阵终显滞涩，深知此战再斗下去恐难保图谱周全。"
      }
    },
    "鸠摩智": {
      "人物经历": {
        "天龙第十回07-六僧结神剑阵力战火焰刀": "见天龙寺拒不交经，傲然全开内力施展平生绝学火焰刀，双掌翻飞劈出狂暴炽热的无形刀气；面对六僧仓促拼凑的六脉神剑阵从容进逼，以雄深内劲层层拆解分化，激战数十回合终将合围剑网尽数压入下风。"
      }
    }
  },
  "update": {},
  "后续事件": {
