737830.content:
{
  "事件地点": "大宋/河南府/聚贤庄/正厅",
  "触发条件": {
    "类型": "时间",
    "年": 1092,
    "月": 3,
    "日": 16,
    "时": 14,
    "分": 15
  },
  "事件结束时间": {
    "年": 1092,
    "月": 3,
    "日": 16,
    "时": 14,
    "分": 45
  },
  "事件引子": "聚贤庄大厅内刀剑森然如林，数十道杀气腾腾的目光齐刷刷逼视着步入的魁伟身影。",
  "事件详情": "面对大厅内数百柄森然对准自己的冰冷兵刃，乔峰全然不顾自身凶险，只一心系于垂死的阿朱身上。他小心翼翼地将气息微弱的阿朱抱入大厅，轻柔稳妥地交托到薛慕华神医手中，随后当着全天下英雄的面，神色恳切地向薛神医抱拳行礼。乔峰朗声恳求道：“薛先生，此女乃无辜之人，乔某今日来此，只求薛先生施展回春妙手救她一命。乔某的一条性命，任由天下英雄处置！”言语之间满是舍生取义的决绝。薛神医此前虽对乔峰所谓“弑父弑母弑师”的恶名痛恨入骨，但身为一代名医，在目睹乔峰甘愿以自身性命为注换取无辜女子一线生机的惊天担当与英雄气魄后，心灵亦受到极大的震动。经过短暂的思想博弈与医者本能的驱使，薛神医当即打破对立成见，郑重允诺必当全力以赴救治阿朱。阿朱就此被妥善交接安顿在薛神医处，使得乔峰终于放下了最大的后顾之忧，得以全心面对接下来的武林审判与生死决局。",
  "事件概要": "面对群雄兵刃相向的森严杀阵，乔峰全然置自身生死于度外，抱拳将重伤濒死的阿朱郑重托付给薛慕华，誓愿以命换医。薛慕华震慑于其舍身救人的豪迈气魄与医者本能，摒弃成见应允施救。后顾之忧既解，乔峰得以全心直面天下群雄的死生决局。",
  "insert": {
    "乔峰": {
      "人物经历": {
        "天龙第十八回04-乔峰托付阿朱换取医治": "无视大厅内森然相对的漫天兵刃，小心翼翼将濒死的阿朱交托于薛神医，当众抱拳恳求其施以回春妙手并愿舍自身性命任凭群雄处置；见薛神医震动之下慨然应允施救，心头悬着的万钧巨石终于落地，得以毫无挂碍直面生死死局。"
      }
    },
    "阿朱": {
      "人物经历": {
