  "事件引子": "水榭正门杀声震天，群豪刀剑齐出结阵合围，两道迅疾身影破空抢入战圈。",
  "事件详情": "就在水榭四人陷入生死绝境的紧要关头，慕容氏麾下得力家臣——绰号“江南一阵风”的风波恶与结义兄弟公冶乾闻得庄外警讯，风驰电掣般及时赶赴水榭护主。二人见水榭内凶徒肆虐、小姐受困，当即怒喝一声拔出随身兵刃，毫不犹豫地挺身杀入敌阵，以刚猛凌厉的攻势奋勇迎战来犯强敌。风波恶身法迅捷如风，挥刀猛砍猛杀，公冶乾则掌力沉雄、策应周密，二人合力瞬间将冲在最前面的数名匪徒逼退，暂时稳住了水榭正门的阵脚。然而聚集在水榭内外的群豪人数实在太多，不仅有各门派的成名高手，更有成群结队的亡命巨盗。各派强敌依仗人多势众，结成严密的合围战阵轮番猛攻，刀光剑影层层叠叠。风波恶与公冶乾虽武艺精湛且拼死搏杀，但在源源不断的群起围攻之下内力急剧损耗，招式逐渐被压制，两人很快便陷入了群豪布下的重重铁桶包围之中，局势再度转入极度凶险的苦战。",
  "事件概要": "听香水榭危在旦夕之际，风波恶与公冶乾闻讯赶至护主，拔刃奋力迎战来犯强敌。二人刀掌齐施力退先头匪徒，却因各派强敌依仗人多结阵轮番合围，内力急剧损耗，招式逐渐受制，终陷入重重铁桶包围之中，局势险象环生。",
  "insert": {
    "风波恶": {
      "人物经历": {
        "天龙第十三回04-风波恶公冶乾赶赴力战受困": "闻得警讯飞驰赶赴水榭护主，见庄内凶徒肆虐，当即拔刀猛劈震退当先匪徒；怎奈来敌甚众且结阵轮番围攻，自身刀法渐受牵制、内力大耗，登时陷入苦斗重围之中。"
      }
    },
    "公冶乾": {
      "人物经历": {
        "天龙第十三回04-风波恶公冶乾赶赴力战受困": "与风波恶闻警飞驰回援水榭，见强敌肆虐当即挥掌迎战，力挫数名冲前匪徒；然而各路敌手人多势众、攻势层层叠叠，自身掌力在车轮鏖战中渐感滞涩，终与四弟双双陷入铁桶合围。"
      }
    }
  },
  "update": {},
  "后续事件": {
    "天龙第十三回05-语嫣出言指点风波恶破软鞭": "风波恶在重围中遭使软鞭的强敌猛攻压制、险象环生，水榭内的王语嫣见状凝神观战，准备出声点拨其招式破绽。"
  },
  "参与人物": [
    "风波恶",
    "公冶乾"
  ]
}

