  "事件引子": "藏经阁内书架森然，慕容博方才仆地气绝，残存掌风犹自回旋，空气中杀意与死寂交织。",
  "事件详情": "眼见慕容博瞬间毙命于老僧掌下，萧峰心头大骇，误以为这神秘老僧乃是手段狠辣、滥杀无辜之徒。为了护卫父亲周全并讨还公道，萧峰怒发冲冠，丹田内力如怒涛狂涌，奋起平生全部神力，轰出一记十成威力的“降龙十八掌”，刚猛绝伦的霸道掌力排空而出，直击扫地老僧胸口！这一记当世至刚至强的降龙掌力结结实实轰在老僧胸膛之上，掌力澎湃雄浑，打得老僧身形剧震倒退数步，肋骨当场断裂，嘴角亦溢出殷红鲜血。然而老僧借着这股狂暴的反震之势顺势反手一掌，轻柔无匹地正中萧远山顶门。萧远山根本来不及闪避，双目一闭，同样气息断绝，重重倒地气绝身亡！老僧虽承受萧峰至强一击受创吐血，却成功顺势击杀萧远山，使得两位纠缠三十年的宿敌在瞬息之间双双毙命倒地，阁内父子死别，场面惨烈至极。",
  "事件概要": "见慕容博暴毙，萧峰惊怒之下催动十成降龙掌力直轰老僧胸膛，震断其肋骨并迫其吐血；老僧却借反震之势顺势反拍萧远山顶门，致其立毙当场。三十年宿敌双双倒地气绝，阁中局势骤变。",
  "insert": {
    "萧峰": {
      "人物经历": {
        "天龙第四十二回05-萧峰出掌伤僧老僧顺毙远山": "见慕容博猝死老僧掌下，大骇之下恐生父遭难，怒发冲冠催动平生神力轰出十成降龙掌力，虽震裂老僧肋骨迫其吐血，却惊见对方借反震之势反掌击杀父亲，心胆俱裂、悲痛欲绝。"
      }
    },
    "扫地老僧": {
      "人物经历": {
        "天龙第四十二回05-萧峰出掌伤僧老僧顺毙远山": "承受萧峰十成威力的至刚降龙掌力直击胸膛，虽肋骨断裂受创吐血，仍借其雄浑反震之力反手一掌按落萧远山顶门，当场断其气息以解宿怨。"
      }
    },
    "萧远山": {
      "人物经历": {
        "天龙第四十二回05-萧峰出掌伤僧老僧顺毙远山": "正为慕容博之死与峰儿刚猛掌力所惊，猝不及防间被受创借力的老僧轻柔一掌印上顶门，登时眼前发黑、生机尽绝，重重仆地气绝身亡。"
      }
    }
  },
  "update": {
    "萧远山": {
      "状态": "气绝身亡"
    }
  },
  "后续事件": {
    "天龙第四十二回06-二子悲痛扑尸老僧携尸飞遁": "萧远山随之气绝仆地，萧峰与慕容复眼见生父双双毙命，悲愤欲绝扑向遗体，受创的老僧则从容立于阁中。"
  },
  "参与人物": [
    "萧峰",
    "扫地老僧",
    "萧远山"
  ]
}

743801.content:
{
  "事件地点": "大理/云南/无量山/绝壁石台",
  "触发条件": {
    "类型": "时间",
    "年": 1092,
    "月": 3,
    "日": 16,
    "时": 12,
    "分": 30
  },
  "事件结束时间": {
    "年": 1092,
    "月": 3,
    "日": 16,
    "时": 13,
    "分": 0
  },
  "事件引子": "断魂崖绝壁孤台云雾迷离，悬空石台上唯闻风声呼啸，二人惊魂方定相对而坐。",
  "事件详情": "在云雾缭绕的孤绝崖台上，木婉清缓缓睁开双眸，凝视着眼前满脸关切的段誉，心中下定决意。她忽然抬起玉手，缓缓解开长久覆于面庞上的黑色轻纱。黑纱悄然滑落，露出了一张白皙娇艳、清丽绝俗的面容，其双眸若秋水澄澈，唇若熟樱点缀，容颜之倾绝宛如月中仙子降世。段誉乍见其真容，不由自主地看得痴呆，发自肺腑地由衷赞叹道：“木姑娘，你真美，宛如天仙下凡！”木婉清双颊登时泛起一丝羞红，随即正色告知段誉，其师当年曾立下严厉毒誓：此生绝不可让男子见到真面目，若有男子得见其容，要么立施杀手将其诛灭，要么便只能以身相许嫁其为妻。木婉清念及此前在万劫谷与悬崖边缘段誉舍命相护的情深义重，宁死亦不愿伤他性命，遂当场认段誉为夫，郑重探询其是否愿娶。段誉闻言虽大感震惊，但见木婉清情真意切且姿容倾国，心头怦然而动，当即肃然整肃衣冠，拱手应承绝不辜负姑娘深情。黑纱除落，二人在此绝境中正式定立婚约盟誓，木婉清满脸娇羞依恋。",
  "事件概要": "绝壁石台上木婉清感念段誉舍命相护，决然解下黑纱展现倾城真容。她道出师尊严誓，若男子见其面貌非杀即嫁，段誉为其绝世容光与深情所动，肃容承诺誓不相负。二人于万丈死境中定下白首盟誓，情定终身。",
  "insert": {
    "段誉": {
      "人物经历": {
        "天龙第五回02-木婉清解黑纱定立婚盟": "凝神守候身侧见木婉清决然揭除黑纱，惊艳于其绝俗脱尘之仙颜，由衷激赏赞叹；闻听其转述师门见容非杀即嫁之森严毒誓，深为对方以死相护、以身相托之至情所撼，当即庄重整衣躬身应承，定下此生不负之婚盟。"
      }
    },
    "木婉清": {
      "人物经历": {
        "天龙第五回02-木婉清解黑纱定立婚盟": "感念段誉患难相扶、舍生共死之赤诚深情，决然于孤台除下面纱以倾国真容示之；肃然道出师门绝不可使男子见容、见者非杀即嫁之誓言，见其倾慕之余慨然肃立许诺迎娶，心生娇羞依恋，在绝境中与段郎缔定白首之约。"
      }
    }
  },
  "update": {
    "段誉": {
      "关系网": {
        "木婉清": "缔结婚盟/90"
      }
    },
    "木婉清": {
      "外貌": "身穿一袭黑裙，长发披肩，揭除黑纱后容颜白皙娇艳、清丽绝俗，双眸澄澈如秋水，唇若熟樱点缀，身姿轻盈苗条",
      "关系网": {
        "段誉": "缔结婚盟/90"
      }
    }
  },
  "后续事件": {
    "天龙第五回03-困守孤台段誉忆及神功": "定下婚盟后二人困守孤绝石台难以攀越，木婉清伤重体虚难支，段誉苦思脱困之策，忽忆起怀中所携的逍遥派帛卷神功。"
  },
  "参与人物": [
    "段誉",
    "木婉清"
  ]
}

743820.content:
{
  "事件地点": "大理/云南/无量山/剑湖宫大厅",
