  "事件引子": "树林中传来两个女子交手的声音——一个手持淡黄竹棒，一个挥舞拂尘。当今武林女流高手中声名最响的两位，竟在襄阳城郊狭路相逢。",
  "后续事件": {
    "事件名": "神雕第二十七回05-杨过飞入棘阵劫郭襄抢红马北上终南山",
    "描述": "黄蓉回林发现棘藤圈中郭襄已影踪不见——原来杨过趁二人出林相斗之际已将婴儿抱走。"
  },
  "事件详情": "黄蓉与李莫愁初次见面互道久仰，言笑晏晏中各自严加提防。黄蓉见到李莫愁怀中婴儿便笑问是谁家的孩子，李莫愁竟说这是她师妹小龙女的私生女儿，父亲乃是杨过。黄蓉虽善于作伪却也忍不住满脸红晕心下大怒，随即平静如常说想抱抱孩子。李莫愁见她神色有异猛地警觉向后跃出。黄蓉如影随形窜上，李莫愁将麻袋中白米和盐劈面打去阻其来势。黄蓉纵身跃起，抽出竹棒使打狗棒法抢攻。李莫愁怀抱婴儿转动不灵，六七招便落下风，心想抱着婴儿决计非她敌手，于是将郭襄放在几株大树间的柔软长草上。黄蓉趁此空隙割来许多生满棘刺的长藤，绕着郭襄在大树间缠了一道又一道——布下桃花岛九宫八卦神术的棘藤阵。李莫愁想入内抱婴儿却无论如何走不进去，几次转身都被绕出藤圈之外。黄蓉将女儿置于万无一失之地后心中再无牵挂，挥竹棒与李莫愁在林中激斗。李莫愁不敌打狗棒法认输后却不肯离去。黄蓉舍棒用掌邀她比掌——以怀中苹果收去冰魄银针再诱李莫愁双掌拍中苹果，令其掌心被自身毒针刺伤中毒。随即以落英神剑掌与兰花拂穴手交互为用步步进逼，掌来时如落英缤纷指拂处若春兰葳蕤。李莫愁毒素上行双臂僵直再也无力抵抗，惨然求黄蓉照料好那女孩儿。黄蓉感其一念之善，喂了三粒解药并说出真相：这女孩儿姓郭名襄是自己与郭靖的亲生女儿，承她养育多日万分感谢。",
  "事件概要": "黄蓉以棘藤阵护住郭襄并重创李莫愁，郭襄暂时脱险，李莫愁则带毒败退失去主动。",
  "insert": {
    "黄蓉": {
      "人物经历": {
