      },
      "关系网": {
        "李莫愁": "初识交手/30（领教了李莫愁的武功和心性——此人虽作恶多端但在女儿身上竟流露真心爱护。感其一念之善饶了性命）"
      }
    },
    "李莫愁": {
      "人物经历": {
        "神雕第二十七回04-黄蓉李莫愁斗智斗力棘藤布阵智夺郭襄": "李莫愁谎称郭襄乃杨过、小龙女私生女，坏师妹名声。林中斗黄蓉，抱婴受制放下，婴被棘藤阵护住。比掌中计，掌击藏针苹果，中己冰魄银针毒，双臂僵直，求黄蓉护婴。服解药方知婴乃黄蓉亲女郭襄。"
      }
    },
