  "事件引子": "太湖水面战船破浪之声隐隐逼近，山庄空寂无援，凌厉杀气已随水风扑面而来。",
  "事件详情": "强敌压境之际，曼陀山庄内部却防备极度空虚，庄主慕容复早已远行不在庄中，而山庄女主王夫人亦外出未归，此时庄内能主事者仅余阿朱、阿碧两个侍女，以及毫无武功的王语嫣和段誉四人，情势可谓千钧一发、危急万分。面对汹涌而来的江湖恶浪，段誉与二女难免心生忧惧，但阿朱展现出临危不乱的过人胆识，她迅速权衡庄内地形，毅然决然地带领王语嫣、阿碧和段誉三人迅速撤离空旷庭院，退入地势险要的水榭之中据险坚守，试图借水榭门户阻滞敌势。然而凶悍的群豪战船瞬间抢滩靠岸，大批武林高手蜂拥登岛破门而入，手持寒光闪烁的数十柄刀枪剑戟如潮水般杀入水榭大厅。四人瞬间被逼入退无可退的死角，数柄兵刃直逼眼前，整座水榭被凶狠的杀伐之气笼罩，众人危在旦夕。",
  "事件概要": "面对汹涌而来的寻仇群豪，曼陀山庄防备极度空虚，主事之人皆不在庄。千钧一发之际，阿朱临危不乱，果敢率领段誉、王语嫣与阿碧撤离庭院，退入水榭据门险守。然而群豪迅速破门抢入大厅，兵刃交错逼近，四人瞬间陷入重重围困的濒死绝境。",
  "insert": {
    "阿朱": {
      "人物经历": {
        "天龙第十三回03-阿朱临危引众退守听香水榭": "察觉强敌大举登岛而庄内空虚，果断在危急关头决断全局，引领王语嫣、阿碧与段公子迅速撤出开阔庭院，退入险要水榭据门死守；眼见群盗破门抢入大厅、兵刃相向，虽陷身退无可退的死角，仍强自镇定伺机周旋。"
      }
    },
    "阿碧": {
      "人物经历": {
        "天龙第十三回03-阿朱临危引众退守听香水榭": "骤见大批凶悍群豪登岛突袭，心惊之余紧随阿朱姐姐引护王语嫣与段公子撤往水榭据险坚守；不料强敌破门如潮杀入厅堂，眼见寒光闪烁的刀枪逼至身前，顿觉惊恐无助、危在旦夕。"
      }
    },
    "王语嫣": {
      "人物经历": {
        "天龙第十三回03-阿朱临危引众退守听香水榭": "面对突如其来的江湖恶浪与汹涌杀气，因身无半点武功而忧惧难安，仓促间只得遵从阿朱调度随众人退避入水榭固守；待见破门而入的群盗兵刃瞬间逼至眼前，退无可退之下心弦紧绷、暗自焦灼。"
      }
    },
    "段誉": {
      "人物经历": {
        "天龙第十三回03-阿朱临危引众退守听香水榭": "忽遇大批江湖凶徒登岛犯庄，自知武艺低微难御强敌，唯恐神仙姐姐受惊受创，急忙护持在侧随阿朱退入水榭据险自保；眼见群恶持械潮涌杀入、数柄利刃已直抵咽喉，身陷绝境之际唯愿拼死护得佳人周全。"
      }
    }
  },
  "update": {},
  "后续事件": {
    "天龙第十三回04-风波恶公冶乾赶赴力战受困": "水榭大厅中四人被逼入死角命悬一线，庄外水域忽闻锐厉啸声与兵刃交击之音，慕容氏家臣闻警破空疾驰赶赴现场解围。"
  },
  "参与人物": [
    "阿朱",
    "阿碧",
