    "分": 45
  },
  "事件结束时间": {
    "年": 1092,
    "月": 3,
    "日": 16,
    "时": 13,
    "分": 30
  },
  "事件引子": "江南常熟水网交错，垂柳拂波，岸边乌篷船轻摇，一派温婉灵秀的水乡风物。",
  "事件详情": "二人行至江南常熟境内，展现在眼前的是一片不同于大理与西域的小桥流水、垂柳依依之景。段誉自幼生长于大理深宫之中，从未得见这般温婉灵秀的江南水乡风物，即便此刻身陷囚途、受制于人，目睹两岸秀美景致时亦不禁暗自赞叹。为了便于水路行进，鸠摩智在常熟当地雇佣了一艘乌篷小船，将穴道受制的段誉带上船舱，沿纵横交错的水道径直向太湖进发。在碧波荡漾的船行途中，鸠摩智神态自若，端坐于船头闭目调息运功，时刻保持防备与充沛内力；段誉则受限于酸软身躯，只得斜倚在船舱木板上，借观赏两岸如画风景来排遣忧思。小船顺水前行了半日时光，前方水面渐渐豁然开阔、烟波浩渺，乌篷船正式由狭窄河道驶入了太湖水域的一片茂密荷塘之中，荷叶田田、清香扑鼻，段誉与鸠摩智的行进路径由此平稳推进至太湖腹地。",
  "事件概要": "鸠摩智押解段誉抵常熟，见水路纵横便雇下乌篷小船入太湖。鸠摩智端坐船头运功调息防备变故，段誉穴道受制斜倚舱内观景排遣忧思。小船顺流航行半日，水面豁然开朗，二人乘舟穿入烟波浩渺的太湖荷塘深处。",
  "insert": {
    "段誉": {
      "人物经历": {
        "天龙第十一回02-鸠摩智常熟雇舟载段誉入太湖": "身受禁锢斜倚于乌篷船舱之中，虽沦为阶下囚却仍不禁为江南灵秀的水乡风物所动；随着小船顺流驶入烟波浩渺的太湖荷荡，只得暗自观景排解心头忧思与无奈。"
      }
    },
    "鸠摩智": {
      "人物经历": {
        "天龙第十一回02-鸠摩智常熟雇舟载段誉入太湖": "押解段誉抵常熟后雇下乌篷小船走水路前往太湖，一路端坐船头闭目运功调息以保内力充沛；沿途严加戒备防其脱逃，驱船稳步驶入烟波浩渺的太湖荷塘腹地。"
      }
    }
  },
  "update": {},
  "后续事件": {
    "天龙第十一回03-太湖荷荡闻歌初逢绿衣少女": "乌篷船穿行于太湖茂密荷荡之中，忽闻水泽深处飘来阵阵吴侬软语的采莲歌声。"
  },
  "参与人物": [
    "段誉",
    "鸠摩智"
  ]
}

