  },
  "事件引子": "行到申牌时分，只见前面黑压压一片大树林，林中隐隐传出呼叱喝骂之声——杨过侧耳听去却是金轮法王与郭芙的声音...",
  "后续事件": {
    "事件名": "神雕第十四回11-杨过引法王入石阵法王破阵三人负伤",
    "描述": "杨过以新学的打狗棒法出阵诱敌，将金轮法王引入乱石阵中困住"
  },
  "事件详情": "杨过摸进树林见黄蓉母女、武氏兄弟四人被金轮法王围攻——武氏兄弟脸上衣上都是血渍黄蓉郭芙头发散乱甚是狼狈。黄蓉以乱石布阵，每每危急时躲到石后金轮法王便须远兜圈子方能追及——看来黄蓉等虽危实安只是无法出阵逃走。金轮法王自负才智过人，约退众人凝思乱石阵奥秘——他想通了五行八卦的变化再入阵擒人方显本事。他怔怔看了半天——刚似瞧出端倪左翼对右翼又不对前锋通了后尾又难索解——呆在当地惊佩不已。郭芙一时大意离了阵法蔽障，被金轮法王抓住点中胁下穴道放在地上。杨过见黄蓉竹棒一摆就要奔出去救女——不及细想猛地跃出抓住郭芙后心向乱石堆扑去。金轮法王铁轮飞出——杨过人在半空使个千斤坠身子直落啪地摔在乱石堆上只跌得目青鼻肿。黄蓉抱女悲喜交集忙伸竹棒引杨过入阵。杨过入阵后瞧这乱石阵前前后后好生佩服——黄蓉的聪明才智天下无双。他与黄蓉谈起黄药师悠然神往——'几时能拜见他老人家一面不枉了这一生'。金轮法王再次攻入——杨过拾黄蓉竹棒使出打狗棒法接战。黄蓉接引杨过入阵后决意将打狗棒法中精微变化一并传授——她说洪七公传了杨过三成杨过自己偷了二成今日再传二成。杨过大喜又假意推辞被黄蓉白了一眼戳破狡狯，跪倒拜谢笑道'郭伯母我幼小之时你曾答应传我功夫今日才传也还不迟'。黄蓉微微一笑将棒法奥妙一一说知。不到半个时辰杨过已领悟十之八九——他聪明颖悟胜过鲁有脚百倍，闻一知十举一反三。黄蓉又将乱石阵的三十六般变化说给他——青龙怎样演为白虎玄武怎生化为朱雀。原来这乱石阵乃是从诸葛亮八阵图中变化出来——黄蓉事起仓促未及布全只稍具规模。杨过虽聪明一时间记得明白的也只十余变。",
  "事件概要": "杨过救下郭芙后得黄蓉尽传打狗棒法，为之后独斗法王添上关键倚仗。",
  "insert": {
    "杨过": {
      "人物经历": {
        "神雕第十四回10-杨过奋身救郭芙黄蓉秘传打狗棒法全诀": "杨过摸进树林见黄蓉以乱石阵御金轮法王，敬佩其才智。郭芙被擒，黄蓉出阵相救，杨过跃出抓住郭芙扑向石堆，铁轮飞来，他悬空坠地撞得目青鼻肿。进阵后黄蓉决意传授打狗棒法精微变化与乱石阵三十六变，杨过跪谢。不到半个时辰，棒法领悟十之八九，又记阵变十余变足以困敌。黄蓉称他舍命相救，杨过胸中舒畅，百死无悔。"
      }
    },
    "黄蓉": {
      "人物经历": {
        "神雕第十四回10-杨过奋身救郭芙黄蓉秘传打狗棒法全诀": "黄蓉以乱石阵抵御金轮法王围攻时，武氏兄弟受伤、郭芙散乱、自己腹中隐痛。郭芙出阵被擒，她心痛欲救之际杨过跃出救人。收女后她引杨过入阵，将打狗棒法精微变化尽数传授，言洪七公传三成、杨过自偷二成、今再传二成，并解说乱石阵三十六般变化，因杨过两度舍命相救郭芙母女而不再如前相待。"
      }
    },
    "郭芙": {
      "人物经历": {
        "神雕第十四回10-杨过奋身救郭芙黄蓉秘传打狗棒法全诀": "在乱石阵中与母亲武氏兄弟一同被金轮法王围攻。一时大意离了阵法蔽障被金轮法王抓住——点中胁下穴道放在地上周身麻痒难当忍不住呻吟。金轮法王故意不点哑穴让她哀声求救。杨过突然跃出抓住她后心向乱石堆扑去——被杨过推入黄蓉怀中脱险。目睹杨过从乱石堆上爬起撞得目青鼻肿"
      },
      "关系网": {
        "杨过": "好奇且微生感激/-5（杨过今日又一次舍命救了自己——撞得目青鼻肿。这已是第二次救命之恩——心中不能再像从前那般敌视他了。虽然嘴上不说但已欠下杨过两条命的恩情）"
      }
    },
    "金轮法王": {
      "人物经历": {
        "神雕第十四回10-杨过奋身救郭芙黄蓉秘传打狗棒法全诀": "金轮法王围攻黄蓉，自负难参乱石阵，惊佩。擒郭芙诱黄蓉出阵，杨过跃救，避过铁轮，以竹棒使打狗棒法接战，金轮绊倒跃出阵。见二人说说笑笑，似不把自己放眼里，定要参透机关再定对策。"
      }
    }
  },
  "update": {
    "杨过": {
      "状态": "乱石阵中得黄蓉真传（奋身救出郭芙后黄蓉以从未有过的方式倾囊相授——打狗棒法全诀和乱石阵变化一一传授。杨过对黄蓉真心感激——那句'难道我还似从前那般待你么'让他胸中暖烘烘极是舒畅。打狗棒法至此已学全——洪七公传招式黄蓉传口诀又传精微变化。虽然乱石阵只记住十余变但已足以拒敌）",
      "所在位置": "大宋/大胜关/大胜关郊野/树林",
      "功法": {
        "打狗棒法": {
          "掌握程度": "炉火纯青（已将洪七公传授的三十六路招式、黄蓉在英雄宴传授的口诀心法、加上今日黄蓉亲传的精微变化全部融会贯通。绊劈缠戳挑引封转八字诀变化精微出神入化。虽即学即用初时难以尽通但领悟极快——闻一知十举一反三。黄蓉说余下三成须凭自己才智体会领悟旁人可传授不来）"
        }
      },
      "关系网": {
        "黄蓉": "世伯母/85（黄蓉授他打狗棒法全诀和乱石阵变化——那份信任与真心让杨过胸中暖烘烘极是舒畅。那句'你若肯来我如何不肯教'更是令杨过百死无悔。从前的隔阂与猜疑至此已大半消解——黄蓉待他已是真心实意的关爱）",
        "郭芙": "自卑且暗生注意/-15（又一次救郭芙——这是第二次。虽舍命相救但纯粹出于侠义心中对她并无男女之情。但郭芙应该逐渐对他的看法有所改变）"
      }
