  "事件引子": "皇城南门外长亭古道柳色青青，内廷仪仗肃整，饯行筵席已备，双辕暖车静候道旁。",
  "事件详情": "听闻王语嫣决意东归姑苏照顾发疯的慕容复，段誉心境澄澈如水，对她的抉择给予了极大的理解与由衷敬重，并未倚仗帝王权势行丝毫强留之举。为了确保王语嫣千里归途安稳无虞，且保其后半生在江南衣食无忧，段誉当即在御前降旨内库，调拨黄金千两、名贵药材数箱以及上好大理织锦绸缎，更特意挑选了四匹温驯健步的良驹与一辆坚固舒适的双辕防震暖车。大理皇城南门外长亭古道旁，仪仗庄重，段誉亲自设下丰盛的饯行酒宴与王语嫣惜别。段誉将装有通关官牒、厚重通兑银票及御用保命金创丹的沉香木匣亲手奉交至王语嫣手中，温和叮嘱道：“王姑娘此去山高水远，表哥若需珍稀药石，大理必倾力相助。”王语嫣眼含热泪接过木匣与资财，躬身深深敛衽道谢。随后，王语嫣在段誉指派的精锐内廷侍卫护卫下登上锦绣车驾，车轮滚滚扬尘东去。二人昔年历经中原江湖腥风血雨的痴缠情结，在这一场庄重体面、互道珍重的赠礼惜别中，迎来了最安宁祥和的圆满终局。",
  "事件概要": "段誉由衷敬重王语嫣东归照顾慕容复之决意，不依权势强留，反在皇城南门长亭设宴饯别，赠予千两黄金、御用丹药与坚实车驾。王语嫣含泪敛衽拜谢，登车在禁卫护卫下扬尘东去，二人昔年痴缠情结体面了却、圆满释然。",
  "insert": {
    "段誉": {
      "人物经历": {
        "天龙第四十八回07-段誉赠予车马重金惜别语嫣": "体谅并由衷敬重王姑娘东归照料表哥的抉择，特降明旨调拨千金药材与坚实暖车，亲于南门长亭设宴饯别；将贮有通关官牒与保命御药的木匣递交其手，温和许下随时相助之诺，目送车驾扬尘东去，心境超然释怀。"
      }
    },
    "王语嫣": {
      "重要物品": {
        "沉香木匣": "段誉亲手赠予的沉香木匣，内贮通关官牒、厚重通兑银票及御用保命金创丹"
      },
      "人物经历": {
        "天龙第四十八回07-段誉赠予车马重金惜别语嫣": "感念段誉不以帝王之尊强留之仁德，在南门长亭酒宴前含泪接过盛有官牒、银票与灵丹的沉香木匣，深深敛衽躬身拜谢；随后登上精锐护卫的锦绣车驾启程东归姑苏，决然辞别大理深宫与往昔情葛。"
      }
    }
  },
  "update": {
