    "月": 11,
    "日": 29,
    "时": 5
  },
  "事件引子": "小龙女离去后，杨过独自被困石室，情花刺遍全身、剧痛一阵紧过一阵；十二时辰的期限正在逼近，他必须设法撑住。",
  "后续事件": {
    "事件名": "神雕第十八回12-公孙止审女挥剑杀女杨过同坠深渊",
    "描述": "公孙绿萼去丹房盗丹迟迟不归。杨过出去寻找发现公孙止正在审问女儿。公孙止挥剑欲杀女——杨过飞身闯入丹房二人同坠深渊。"
  },
  "事件详情": "杨过身上受苦心中伤痛：'前时所受的诸般苦楚与今日相较已全都算不了甚么。这谷主如此狠毒我焉能一死了之任由姑姑落在他手中苦受折磨？何况我父仇未报岂能让那假仁假义的郭靖黄蓉作下恶事不受报应？'思念及此不由得热血如沸激昂振奋。于是咬紧牙关盘膝坐起虽在渔网之中不能坐正姿式还是气沉丹田运起功来。过了两个时辰已是午后，一名绿衫弟子端着四个无酵馒头进来道'谷主今日新婚大喜也让你好好吃一个饱'。杨过伸手取过四个馒头都吃了心想'我既要和这贼谷主厮拚到底便不能作践自己身子'。突然门口绿影一晃又有一名绿衫弟子进来——悄没声走到那人身后伸拳在他背心上重重击落将其打昏——竟是公孙绿萼。她转身关上室门低声道'杨大哥悄声我来救你'。说着解开渔网结子搬开丛丛情花放了杨过出来。她随手摘下一小丛情花塞在那弟子口中令其不能呼救，将他缚入渔网情花堆了个满身伪装成杨过。杨过好生感激知她此举实是身犯奇险。公孙绿萼微微一笑道'你稍待片刻我即时便回'——翩然出室前往丹房盗取绝情丹。",
  "事件概要": "公孙绿萼冒死盗丹相救，杨过也在剧痛中立定报仇与求生之念。",
  "insert": {
    "杨过": {
      "人物经历": {
        "神雕第十八回11-杨过忍痛立志公孙绿萼冒死救情郎": "杨过忍痛立志不向命运低头，誓苦练武功为父母报仇，纵姑姑成为谷主夫人也要救出，决与谷主拼到底。公孙绿萼打昏守卫救出渔网，又冒死入丹房盗解药，杨过感激万分，激动难言。"
      }
    },
    "公孙绿萼": {
      "人物经历": {
        "神雕第十八回11-杨过忍痛立志公孙绿萼冒死救情郎": "公孙绿萼心慕杨过，知他心系龙姑娘。她冒死打晕送饭弟子，救杨过出渔网，独闯丹房盗绝情丹，被父亲擒获。荆杖逼问下宁死不吐药踪，忍辱解衣证无丹，临死低语饶他。"
      }
    }
  },
  "update": {
    "杨过": {
      "所在位置": "大宋/绝情谷/水仙山庄",
      "状态": "被公孙绿萼从渔网中救出——身得自由却仍受情花之毒。心中激荡：'我虽遭际不幸自幼被人欺辱但世上真心待我之人却也不少。'思索自己的时辰八字为何待他好的如此之好对他恶的又如此之恶。等公孙绿萼取丹久不归来越等越是担忧——知她为我甘冒大险我怎可不设法相救",
      "重要物品": {
        "情花毒": "遍身为情花所刺——每过一个时辰疼痛增一分，三十六日后全身剧痛而死。此刻已过两个时辰疼痛已较初时更甚"
      }
    },
    "公孙绿萼": {
      "所在位置": "大宋/绝情谷/绝情谷内/丹房",
      "状态": "已救杨过出渔网。只身前往丹房盗取绝情丹——此去凶险万分。为救杨过不惜背叛父亲身犯奇险——明知一旦被发现后果不堪设想却义无反顾"
    }
  },
  "参与人物": [
    "杨过",
    "郭靖",
    "黄蓉",
    "公孙绿萼"
  ]
}

