      }
    },
    "游坦之": {
      "人物经历": {
        "天龙第四十四回02-阿紫换眼复明嫌丑弃游坦之": "自愿忍受生挖眼珠之奇痛将双目献予阿紫，双腿早折瘫卧在榻下血水残喘；听闻阿紫复明笑语，拼尽残力在泥泞碎石中爬向对方试图触碰裙角表白，未料反被其厌恶斥为丑怪，更遭其凌厉一脚踢断胸口肋骨喷血倒飞，惨遭彻底抛弃于荒山寒泞。"
      }
    }
  },
  "update": {
    "阿紫": {
      "外貌": "约十五六岁年纪，身穿紫色衣衫，身形娇小，一张瓜子脸，双眸清亮复明且灵动有神",
      "状态": "正常",
