      }
    },
    "游坦之": {
      "外貌": "身形消瘦单薄，面容受铁具毁损狰狞如鬼，眼眶化为两个乌黑淌血空洞，浑身血污泥泞",
      "状态": "濒死（双目失明、双腿骨折、肋骨断裂）"
