      },
      "功法": {
        "九阴真经(残篇)": {
          "掌握程度": "初窥门径（从王重阳重阳遗刻中学得部分九阴真经要旨，年余修习已小有所成，但仅为真经一小部分）"
        }
      }
    },
    "小龙女": {
      "人物经历": {
        "神雕第七回08-山谷搭茅屋养伤修炼一年有余": "在终南山脚荒僻山谷中与杨过搭茅屋隐居。不到半月内伤痊愈。数月间先将玉女心经练成，见杨过也功行圆满。重经秘道潜入墓中诵记九阴真经，出来修习一年有余，内功外功俱皆精进。谷中住了年余安稳过活觉得世上更无别事及得上，但知杨过留恋红尘心中烦恼。"
      },
