    "分": 30
  },
  "事件结束时间": {
    "年": 1092,
    "月": 7,
    "日": 15,
    "时": 14,
    "分": 0
  },
  "事件引子": "少林大雄宝殿前群雄哄笑讥诮未绝，忽听盘山古道蹄声如滚滚闷雷破空震响。",
  "事件详情": "就在游坦之当众受辱磕头、丐帮威名扫地、全场群豪陷入鄙夷狂笑的极度混乱之际，少室山险峻的盘山古道上骤然传来一阵如万马奔腾般的沉闷蹄声。蹄声穿云破石，由远及近化作滚滚闷雷，震得整座少林山门大殿青砖嗡嗡作响。只见十八名身披百炼玄铁重铠、手执丈八狼头重矛的契丹精锐铁骑宛如狂暴飓风般冲破山门关卡，势不可挡地直踏入大雄宝殿前广场。为首一人身材高大巍峨如天神下凡，身上披着一袭大辽南院大王的明黄华贵锦袍，浓眉如剑，双目神光电射，顾盼之间雄视全场。坐骑长嘶驻足，萧峰双臂一振飞身飘然下马，周身沉凝如山岳深海般的磅礴霸气瞬间席卷全场，单掌凌空虚按，刚猛雄浑的“降龙十八掌”潜劲如惊涛骇浪般四溢，硬生生将凑上前来的数名星宿派门徒震得倒飞吐血。面对在场数千中原武林豪杰充满仇怨与惊恐交织的复杂目光，萧峰仰天发出一声穿金裂石的长啸，以气吞山河之势强势宣告重返中原武林，将整座少室山的肃杀之气瞬间推向巅峰。",
  "事件概要": "游坦之向丁春秋屈膝受辱引得群雄鄙夷之际，萧峰率十八名契丹玄铁精骑踏破山门、直插大雄宝殿前广场。萧峰飞身下马运降龙掌力重创星宿派门徒，昂然仰天长啸，以气吞山河之势震慑全场，强势宣告重返中原武林。",
  "insert": {
    "游坦之": {
      "人物经历": {
        "天龙第二十九回08-萧峰率燕云精骑踏雷登山": "伏在青石地上忍受群雄唾骂耻笑之际，忽闻雷鸣般的铁蹄震碎山门，抬头赫然见杀父仇人乔峰身披锦袍、率契丹铁骑踏入广场并挥掌震退星宿门人，惊骇与仇恨登时涌上心头。"
      }
    },
    "萧峰": {
      "人物经历": {
        "天龙第二十九回08-萧峰率燕云精骑踏雷登山": "率十八名燕云铁骑破关直驰入少林大雄宝殿前广场，翻身下马运刚猛掌风凌空震飞逼近的星宿派门徒，环视数千神色惊怒的中原群豪，仰天长啸以宣告重归中原武林。"
      }
    }
  },
  "update": {},
  "后续事件": {
    "天龙第三十回01-萧峰率十八骑现身遭群雄围逼": "萧峰长啸震慑全场，直面群雄仇怨惊怒之色，少林英雄大会风云激荡步入最终局。"
  },
  "参与人物": [
    "游坦之",
    "萧峰"
  ]
}

