  "事件引子": "听香水榭内刀光霍霍、呼喝喧嚣，风波恶二人身陷重围，轩窗畔少女静观局势。",
  "事件详情": "在风波恶与公冶乾被重重围困、危在旦夕的生死关头，王语嫣静静倚在水榭的雕花轩窗前，凝眸注视着场中翻飞的刀光剑影。此时伏牛派高手觑准风波恶招式间的空隙，抖动手腕施展出门派绝技“百胜软鞭”，鞭影如毒蛇吐信般卷起呼啸劲风，狠辣无比地直扑风波恶左侧防御薄弱之处。风波恶正被身旁群敌牵制，眼看便要被软鞭缠中受创。值此千钧一发之际，毫无武功内力的王语嫣神色从容，朱唇轻启，发出一声清脆的断喝：“风三哥，避左虚右，进‘兑位’，反手刺他‘天突穴’！”风波恶对表小姐深信不疑，闻声毫不迟疑地依言变招，脚下斜跨兑位避实就虚，手腕一翻，手中长刀化作一道雪亮寒光反向疾刺而出。这一刀精准狠辣，恰好避开软鞭锋芒并直取对方要害破绽，伏牛派高手大惊失色、招式瞬间被破，闷哼一声踉跄暴退数步，风波恶借此精妙指点一举化解左侧危机并将强敌击退。",
  "事件概要": "风波恶与公冶乾陷入群敌重围，伏牛派高手趁隙施展百胜软鞭狠辣袭向风波恶左侧死角。危急之际，倚窗观战的王语嫣出言指点其踏兑位反刺天突穴。风波恶毫不迟疑依言变招，长刀直取要害瞬间破去软鞭攻势，化解险情并击退强敌。",
  "insert": {
    "王语嫣": {
      "人物经历": {
        "天龙第十三回05-语嫣出言指点风波恶破软鞭": "倚在水榭轩窗前密切注视混战，见伏牛派高手的百胜软鞭直扑风波恶左侧死角，当即出言指点其避虚踏兑位刺其天突穴；见风三哥依言变招精准退敌脱险，暗自欣慰所阅武经能解燃眉之急。"
      }
    },
    "风波恶": {
      "人物经历": {
        "天龙第十三回05-语嫣出言指点风波恶破软鞭": "在水榭遭群敌合围苦战且左侧骤露空当，危急间闻听王语嫣清脆提点，毫不迟疑地斜踏兑位反手挥刀疾刺来敌天突穴；一举破去伏牛派百胜软鞭并重挫强敌，心下既惊险又对表小姐神乎其技的指点大为佩服。"
      }
    },
    "公冶乾": {
      "人物经历": {
        "天龙第十三回05-语嫣出言指点风波恶破软鞭": "在水榭正厅与风波恶并肩力抗重重围攻，瞥见其左侧被伏牛派百胜软鞭狠辣突袭命悬一线；突闻轩窗边王语嫣出声指点要穴，见风波恶依计变招化险为夷逼退强敌，自身战意与信心大为振作。"
      }
    }
  },
  "update": {},
  "后续事件": {
    "天龙第十三回06-语嫣道破破绽公冶乾退青城": "风波恶击退伏牛派高手后，合围中的公冶乾亦遭青城派群起猛攻，王语嫣在轩窗畔继续凝神洞察敌招破绽。"
  },
