      }
    },
    "杨过": {
      "人物经历": {
        "神雕第三十回09-入绝情谷大厅兄妹相认裘千尺袭郭芙": "时时留心裘千尺，跃前抽郭芙长剑挡开枣核，剑被断成两截；救人后经提醒方想起情花毒未解，上前求药被拒，朗声我已娶龙氏为妻，死则死矣岂作负义之徒，携小龙女走向厅门，决心自行救天竺僧。"
      }
    },
    "郭芙": {
