  "事件详情": "夜色渐深，小镜湖畔的天空阴云密布、漆黑如墨。天际深处隐隐滚过阵阵沉闷的雷声，紧接着狂风呼啸而起，冰冷刺骨的暴雨如决堤般倾盆而下，整片天地都笼罩在肃杀凄凉的雨雾之中。三更决斗的时辰已然悄然逼近，彻底易容成大理镇南王段正淳模样的阿朱神色平静而凄美。她缓步走到门前，伸手披上一领遮蔽风雨的蓑衣，又紧紧握住了防身的长剑。临行推门之际，阿朱回望幽暗的竹舍室内，胸中涌动着对乔峰无限的深情、依恋与难舍眷恋。然而她深知此去九死一生，但为了化解这桩宿命般的血海深仇，同时保全生父段正淳与至爱乔峰，她的赴死之志已无半分动摇。阿朱神色决然，毅然迈步踏入漫天风雨之中，顶着咆哮的夜风与倾盆暴雨，一步步坚定地走向杀机密布的小镜湖青石桥。她以生父的容貌身形慷慨赴约、从容赴死，青石桥上的凄绝悲剧就此拉开序幕。",
  "事件概要": "三更决斗之期将至，阿朱为化解雁门关血海深仇、两全生父性命与乔峰安危，决意代父受死。她换上蓑衣、按紧佩剑，回望舍内眷恋难舍，终毅然推门踏入漫天风雨，顶着咆哮夜风与倾盆暴雨，以段正淳之容貌从容步向青石桥赴死。",
  "insert": {
    "阿朱": {
      "人物经历": {
        "天龙第二十一回08-阿朱冒暴雨赴青石桥从容就死": "易容成生父段正淳后神色决绝，披上蓑衣并按紧佩剑，推门回望幽暗内室，满心皆是对乔大哥的无限眷恋；为化解两家宿怨保全父亲与至爱，毅然顶着刺骨狂风与倾盆暴雨，一步步从容走向杀机暗伏的小镜湖青石桥迎向死局。"
      }
    }
  },
  "update": {
    "阿朱": {
      "所在位置": "大宋/信阳府/小镜湖/青石桥头"
    }
  },
  "后续事件": {
    "天龙第二十二回01-乔峰青石桥风雨候仇人": "阿朱顶风冒雨孤身踏上凄冷青石桥静候乔峰，一场宿命悲剧无可挽回地拉开序幕。"
  },
  "参与人物": [
    "阿朱"
  ]
}

