  },
  "事件引子": "黑夜树林中，武三通匆忙放下幼子武修文，只抱着武敦儒远去，叮嘱他留在原地等候；父亲迟迟未归，四周愈发难辨方向。",
  "后续事件": {
    "事件名": "神雕第一回07-李莫愁血洗陆家庄",
    "描述": "柯镇恶闻知李莫愁来袭，急忙赶往陆家庄救援。"
  },
  "事件详情": "武三通抱着两个儿子奔入树林，忽然放下幼子武修文，只抱着武敦儒远去，叫声'你等着，我回头再来抱你'。武修文独自在黑暗树林中等候良久，父亲始终不来。他摸索寻路却越走越迷，数次踏入田中，双脚全是烂泥。他急得想哭，忽闻猫头鹰啼声，想起猫头鹰爱数人眉毛根数的传说，忙伸指沾了唾液涂湿眉毛。靠在树干上按住双眉不敢稍动，终于合眼睡去。次日天明被清亮高亢的啼声唤醒，两只极大的白色大鹰在天空盘旋，双翅横展竟达丈许。一个身穿淡绿罗衣、颈挂明珠、肤色白嫩如奶油的秀丽女孩从树后走出，召唤双雕落于身畔。武修文上前搭话，女孩却神色凛然语带轻蔑，称他为'野孩子'。二人追逐嬉闹间女孩使绊将他踢倒，鼻子撞在尖石上鲜血直流。女孩见血惊慌，一名撑着铁拐的盲目跛足老者现身——正是江南七怪之首柯镇恶。他为武修文按穴止了鼻血，问出来历后神色郑重，嘱咐二童原地等候，自己拄杖疾行赶往陆家庄救援。",
  "事件概要": "走失的武修文被郭芙和柯镇恶带回陆家庄，郭靖一行由此与庄中血案接上了线。",
  "insert": {
    "武修文": {
      "人物经历": {
        "神雕第一回06-武修文迷途遇郭芙柯镇恶": "武修文被父武三通遗落黑夜林中，迷路哭泣，夜听猫头鹰啼，天明遇牵双白雕的郭芙，搭话遭轻蔑，被踢倒摔出鼻血。盲跛柯镇恶止其血，问出来历，知敌为赤练仙子李莫愁，神色郑重匆匆赶去救援。"
      },
      "关系网": {
        "郭芙": "初识/20",
        "柯镇恶": "初识/50"
      }
    },
    "郭芙": {
      "人物经历": {
        "神雕第一回06-武修文迷途遇郭芙柯镇恶": "清晨在嘉兴树林中与双雕玩耍，遇到从大理来的迷路少年武修文。嫌其是'野孩子'，语带轻蔑不理他。武修文追来时伸足绊倒他，又朝他臀部猛踢，致其鼻血直流。见血后惊慌失措，被大公公柯镇恶喝破欺人之事，央求柯镇恶不要告诉她爹爹。"
      },
      "关系网": {
        "武修文": "初识/15"
      }
    },
    "柯镇恶": {
      "人物经历": {
        "神雕第一回06-武修文迷途遇郭芙柯镇恶": "带着郭芙和双雕在嘉兴树林中游玩，撞见郭芙欺负武修文。为武修文按穴止住鼻血，一手抓住其手臂时被武修文以小擒拿手巧妙挣脱，不禁'噫'的一声轻呼。问出武修文是大理武三通之子、一灯大师门下后，闻知陆家庄的敌人是赤练仙子李莫愁，登时神色郑重，急拄铁杖赶去救援。"
      }
    }
  },
  "update": {
    "柯镇恶": {
      "所在位置": "大宋/嘉兴府/陆家庄"
    }
  },
