  ]
}

901400.content:
{
  "事件地点": "西夏/天山/缥缈峰/灵鹫宫接天桥",
  "触发条件": {
    "类型": "时间",
    "年": 1092,
    "月": 3,
    "日": 16,
    "时": 14,
    "分": 15
  },
  "事件结束时间": {
    "年": 1092,
    "月": 3,
    "日": 16,
    "时": 14,
    "分": 45
  },
  "事件引子": "绝顶冰崖寒风凛冽，雪泊中枯槁二宗气若游丝，唯余死战过后的凄凉喘息。",
  "事件详情": "瘫倒在冰崖雪泊中的李秋水自知大限将至，强提残存的一丝神智，颤巍巍地从怀中掏出一幅贴身珍藏多年、无崖子当年亲手绘制的神秘女子丝绢画卷，欲以此寄托终生挚爱。一旁气息奄奄的天山童姥见状妒火重燃，拼尽最后一丝力气挣扎着爬上前去，伸手一把将画轴狠狠抢夺过来。童姥颤抖着解开丝带将画卷在雪地上徐徐展平，李秋水亦吃力地侧身凝神看去。只见画中白衣女子绝美出尘、宛若凌波仙子，然而童姥的目光骤然凝固在画中人唇边——在那娇嫩的嘴角旁，赫然点缀着一颗微小却极其清晰的黑痣。童姥猛然抬头死死盯着李秋水苍老干枯的面孔，李秋水嘴角光滑洁净，从未生过任何黑痣。童姥指着画卷嘶哑惊呼，李秋水定睛细看之下亦如遭晴天霹雳，当场僵住。原来这颗标志性的黑痣，正是李秋水当年那一母同胞、年仅十一二岁的亲妹妹李沧海所独有的特征。纠缠争斗了近百年的两位绝世奇女子至此方才痛苦地获知，无崖子一生刻骨铭心、至死不渝深爱的真身，竟是那个懵懂的小妹，数十年的倾轧厮杀瞬间沦为天大的荒诞笑话。",
  "事件概要": "瘫倒在雪泊中的李秋水弥留之际取出无崖子手绘画卷寄托余念，天山童姥妒恨之下拼死抢夺展平。二人细审画卷，惊见画中出尘仙子嘴角生有一颗黑痣，正是李秋水胞妹李沧海独有之特征。纠缠百年的同门生死情仇瞬间沦为荒诞笑话，二人心神俱震陷入绝望。",
  "insert": {
    "天山童姥": {
      "人物经历": {
        "天龙第三十五回05-验看画卷惊悉无崖子至爱真身": "见瘫卧雪中的李秋水掏出师弟手绘画卷，妒火重燃拼尽残力挣扎上前抢夺展开；凝神细看赫见画中仙子嘴角生有一颗清晰黑痣，而李秋水嘴角光洁无瑕，失声惊呼点破师弟毕生挚爱实为当年年幼的小妹李沧海，心神剧震陷入癫狂绝望。"
      }
    },
