      }
    },
    "玄苦": {
      "人物经历": {
        "天龙第十七回06-禅房探师惊见玄苦合十圆寂": "身中至刚绝顶掌力命悬一线，见满身血污的徒儿乔峰扑至榻前，唯神色复杂悲叹数声后双掌合十，就此气绝圆寂。"
      }
    }
