  "事件详情": "正当屋内康敏与白世镜密谋如何借刀杀人、斩草除根之际，后窗棂处骤然响起一声极轻微的破风声，丐帮大智分舵舵主全冠清竟也趁着浓稠夜色如狸猫般翻窗潜入。全冠清的猝然现身，瞬间打破了房内的诡异平衡。白世镜与全冠清昔日皆与康敏暗结私情，此刻在马宅内室狭路相逢，争风吃醋的私怨妒火与唯恐弑副帮主罪证败露的极度恐慌瞬间引爆。白世镜满面煞气，暴喝一声率先发难，双掌真气鼓荡，使出丐帮精妙的“缠丝擒拿手”直取全冠清咽喉要穴；全冠清早有防备，狞笑一声翻手自腰间抽出一柄精钢短匕，脚踩打狗短打步法迅疾游走，招招狠辣地刺向白世镜周身死穴。两人在逼仄昏暗的房内展开殊死肉搏，掌风与森森匕影激烈交错轰鸣，激荡的气劲将紫檀茶几与青瓷茶具撞得粉碎飞溅。康敏则抱臂缩至床角，眼波流转，神情冷漠地冷笑观战。白世镜雄浑的掌力震裂了全冠清的长袍左袖，全冠清锋利的匕首亦在白世镜肩头划出一道深可见骨的血痕。屋内桌椅倾覆、残烛摇曳，丐帮两大高层彻底陷入你死我活的同门血腥内讧，局势陷入不可逆转的失控。",
  "事件概要": "全冠清夤夜翻窗潜入马宅内室，与白世镜狭路相逢。私情嫉恨与弑兄败露的恐慌骤然引爆，白世镜暴怒施展缠丝擒拿手痛下杀手，全冠清挥舞精钢短匕狠辣抢攻。两人殊死肉搏震碎陈设，全冠清震裂袍袖，白世镜肩头重创见骨，内讧彻底失控。",
  "insert": {
    "全冠清": {
      "人物经历": {
        "天龙第二十三回03-全冠清潜入与白世镜相斗": "趁夜翻窗潜入马宅内室，骤见白世镜亦在房中，私怨妒火与败露惊恐之下拔出精钢短匕狠辣刺杀，虽被对方雄浑掌力震裂左袖，亦趁隙以利刃划破其肩头见骨。"
      }
    },
    "白世镜": {
      "人物经历": {
        "天龙第二十三回03-全冠清潜入与白世镜相斗": "正与康敏密谋之际惊见全冠清潜入，新仇旧怨与灭口之念骤起，暴喝使出缠丝擒拿手直取其要害，掌风震碎其长袍左袖，搏斗中肩头却被其短匕划出一道见骨血痕。"
      }
    },
    "康敏": {
      "人物经历": {
        "天龙第二十三回03-全冠清潜入与白世镜相斗": "见全冠清夤夜破窗而入并与白世镜大打出手，深知二人皆为己神魂颠倒且各怀鬼胎，遂抱臂冷漠退缩至床角，眼波流转间讥诮坐观两大丐帮高层殊死残杀。"
      }
    }
  },
  "update": {
