  "事件引子": "营地外蹄声如雷、箭矢如雨，契丹铁骑冲杀肆虐，阿骨打身陷重围命悬一线。",
  "事件详情": "目睹辽军肆虐屠戮、义弟阿骨打危在旦夕，帐外的乔峰怒发冲冠，救人之念决然升起。他足尖挑起雪地上一柄遗落的精钢长枪，身形腾空而起，如大鹏般稳稳落在一匹狂奔的战马之上，单骑单枪悍然撞入辽军铁骑战阵。面对数十柄迎面攒刺的精钢马槊，乔峰双臂灌注万斤神力，长枪如蛟龙出海般横扫一圈，狂暴劲风硬生生将当先十余名重甲骑兵扫落马下。眼见敌方中军主帅正挥刀狂呼，乔峰弃枪飞身凌空扑去，双掌齐推轰出刚猛无匹的“见龙在田”。磅礴浩瀚的降龙掌力如惊涛骇浪般席卷开来，主帅身前四名魁梧亲卫连人带马被掌风掀翻数丈，筋骨碎裂倒地。辽军主帅骇得面无人色，仓促挥刀劈向乔峰面门；乔峰不闪不避，右手法若闪电施展少林“龙爪手”精准扣住其持刀手腕，咔嚓一声卸落其短刀，左手顺势如铁箍般死死扼住主帅咽喉，将其生生凌空提离马鞍。乔峰如天神降世般厉声如雷喝道：“主将已被擒，放下兵刃者免死！”数百名契丹铁骑见主帅被俘，斗志彻底崩溃，纷纷抛下马刀长矛翻身下马跪伏投降。",
  "事件概要": "目睹女真营地遭袭与结义兄弟遇险，乔峰单骑持枪悍然凿阵，横扫当先十余名重骑。敌阵之中，他弃枪飞身以“见龙在田”震翻敌营亲卫，继以龙爪手扣腕夺刀并锁喉生擒辽军主帅，厉声喝退全军，迫使数百契丹铁骑掷刃伏降。",
  "insert": {
    "乔峰": {
      "人物经历": {
        "天龙第二十四回07-乔峰单骑陷阵生擒契丹主帅": "见契丹骑兵肆虐营地、阿骨打危在旦夕，挑枪策马单骑凿穿敌阵，长枪横扫扫落十余铁骑；旋即弃枪凌空发掌震碎亲卫防御，施龙爪手夺刀锁喉生擒辽军主帅，厉声喝令敌军全数抛戈跪降。"
      }
    }
  },
  "update": {},
  "后续事件": {
    "天龙第二十四回08-部落大捷乔峰重拾英雄豪情": "契丹铁骑尽数弃械受降，劫后余生的女真猎人欢呼雷动，簇拥着生擒敌帅的乔峰返回营寨筹备庆功。"
  },
  "参与人物": [
    "乔峰"
  ]
}

